// Personalização do plano pelos dados do cadastro. Regras isoladas aqui.
//
// Cada ação pode declarar:
//   requer:    condições do autor para a ação fazer sentido (todas precisam valer)
//   objetivos: objetivos do autor para os quais a ação é prioritária (sobe no plano)
//
// Condições disponíveis em CONDICOES. Para criar uma nova, basta adicionar uma linha.

export const CONDICOES = {
  lista_email: { descricao: 'tem lista de e-mail', vale: (a) => a.temListaEmail === true },
  sem_lista: { descricao: 'ainda não tem lista de e-mail', vale: (a) => a.temListaEmail !== true },
  tem_audiencia: { descricao: 'tem audiência em alguma rede', vale: (a) => temAudiencia(a) },
  publicado: { descricao: 'livro publicado', vale: (a) => a.livro.status === 'publicado' },
  link_venda: { descricao: 'tem link de venda', vale: (a) => Boolean(a.livro.linkVenda) },
  amazon: { descricao: 'vende na Amazon (KDP ou link da Amazon)', vale: (a) => a.livro.formato === 'KDP' || /amazon\./i.test(a.livro.linkVenda || '') },
  editora: { descricao: 'publicou por editora', vale: (a) => a.livro.formato === 'Editora' },
  nao_publicado: { descricao: 'livro ainda não publicado', vale: (a) => a.livro.status !== 'publicado' },
}

const FAIXAS_COM_AUDIENCIA = ['1 a 5 mil', '5 a 20 mil', '20 a 100 mil', 'mais de 100 mil']
function temAudiencia(autor) {
  return Object.values(autor.audiencia || {}).some((f) => FAIXAS_COM_AUDIENCIA.includes(f))
}

/** Minutos por semana que o autor disse ter. */
export const ORCAMENTO_MINUTOS = {
  'até 2 horas': 120,
  '2 a 4 horas': 240,
  '4 a 8 horas': 480,
  'mais de 8 horas': 600,
}

/** A ação cabe para este autor? (todas as condições em `requer` precisam valer) */
export function acaoCabe(acao, autor) {
  return (acao.requer || []).every((c) => CONDICOES[c]?.vale(autor) ?? true)
}

/** A ação é prioritária para o objetivo do autor? */
export function acaoPrioritaria(acao, autor) {
  return (acao.objetivos || []).includes(autor.objetivo)
}

/**
 * Ordena as ações candidatas para um autor:
 *   1. prioritárias para o objetivo dele primeiro;
 *   2. depois pela ordem cadastrada.
 */
export function ordenarParaAutor(acoes, autor) {
  return [...acoes].sort((a, b) => {
    const pa = acaoPrioritaria(a, autor) ? 0 : 1
    const pb = acaoPrioritaria(b, autor) ? 0 : 1
    return pa - pb || a.ordem - b.ordem
  })
}

/**
 * Corta a lista pelo orçamento de tempo do autor, sem descer de `minimo` ações.
 * Ação que estoura o orçamento fica de fora, a menos que ainda falte atingir o mínimo.
 */
export function caberNoTempo(acoes, autor, minimo, maximo) {
  const orcamento = ORCAMENTO_MINUTOS[autor.horasSemana] ?? Infinity
  const escolhidas = []
  let usados = 0
  for (const a of acoes) {
    if (escolhidas.length >= maximo) break
    if (usados + a.tempoMinutos <= orcamento || escolhidas.length < minimo) {
      escolhidas.push(a)
      usados += a.tempoMinutos
    }
  }
  return escolhidas
}

/** Frases curtas explicando o que moldou o plano (para mostrar ao autor). */
export function explicarPersonalizacao(autor) {
  const partes = []
  partes.push(autor.temListaEmail ? 'com lista de e-mail' : 'sem lista de e-mail')
  const objetivo = { vender_mais_copias: 'vender mais cópias', construir_autoridade: 'construir autoridade', conseguir_palestras: 'conseguir palestras', segunda_edicao: 'chegar à segunda edição' }[autor.objetivo]
  if (objetivo) partes.push(`foco: ${objetivo}`)
  if (autor.horasSemana) partes.push(`${autor.horasSemana} por semana`)
  return partes
}

const REDES_NOME = { instagram: 'Instagram', youtube: 'YouTube', linkedin: 'LinkedIn', tiktok: 'TikTok', facebook: 'Facebook' }
const NOME_OBJETIVO = { vender_mais_copias: 'vender mais cópias', construir_autoridade: 'construir autoridade', conseguir_palestras: 'conseguir palestras', segunda_edicao: 'chegar à segunda edição' }

function redePrincipal(autor) {
  const ordem = ['mais de 100 mil', '20 a 100 mil', '5 a 20 mil', '1 a 5 mil']
  for (const faixa of ordem) {
    const rede = Object.entries(autor.audiencia || {}).find(([, f]) => f === faixa)?.[0]
    if (rede) return REDES_NOME[rede] || rede
  }
  return null
}

/**
 * Uma frase curta dizendo por que esta ação entrou no plano deste autor.
 * Só cita motivos que dependem do cadastro; ações genéricas não ganham frase.
 * @returns {string|null}
 */
export function explicarEscolha(acao, autor) {
  const motivos = []
  const requer = acao.requer || []
  if (requer.includes('sem_lista')) motivos.push('você ainda não tem lista de e-mail')
  if (requer.includes('lista_email')) motivos.push('você já tem lista de e-mail')
  if (requer.includes('tem_audiencia')) {
    const rede = redePrincipal(autor)
    motivos.push(rede ? `você já tem público no ${rede}` : 'você já tem audiência')
  }
  if (requer.includes('amazon')) motivos.push('seu livro vende na Amazon')
  if (requer.includes('editora')) motivos.push('você publicou por editora')
  const objetivos = acao.objetivos || []
  if (autor.objetivo && objetivos.includes(autor.objetivo) && objetivos.length === 1) motivos.push(`seu foco é ${NOME_OBJETIVO[autor.objetivo]}`)
  if (motivos.length === 0) return null
  const [a, b] = motivos
  return b ? `${a} e ${b}` : a
}

/** Frase inteira, em tom de conversa, explicando por que estas ações: "você ainda não tem lista de e-mail, quer construir autoridade e tem de 2 a 4 horas por semana". */
export function fraseDoPlano(autor) {
  const partes = []
  partes.push(autor.temListaEmail ? 'você já tem lista de e-mail' : 'você ainda não tem lista de e-mail')
  const foco = { vender_mais_copias: 'quer vender mais cópias', construir_autoridade: 'quer construir autoridade', conseguir_palestras: 'quer conseguir palestras', segunda_edicao: 'quer chegar à segunda edição' }[autor.objetivo]
  if (foco) partes.push(foco)
  if (autor.horasSemana) partes.push(`tem ${/^\d/.test(autor.horasSemana) ? 'de ' : ''}${autor.horasSemana} por semana`)
  if (partes.length === 1) return partes[0]
  return partes.slice(0, -1).join(', ') + ' e ' + partes[partes.length - 1]
}
