// Regras do Plano da Semana. Cada regra é uma função pequena e independente.

import { inicioDaSemana, semanasEntre } from './datas.js'
import { datasDeAtividade } from './checkin.js'
import { acaoCabe, ordenarParaAutor, caberNoTempo } from './personalizacao.js'
import { evitadaPorTema, continuaAlgoFeito } from './memoria.js'

export const MIN_ACOES_SEMANA = 3
export const MAX_ACOES_SEMANA = 5
export const OPCOES_ACOES_SEMANA = [1, 2, 3, 4, 5]

/** Quantas ações o autor quer por semana: a escolha dele (1 a 5) ou null para a regra padrão pelo tempo declarado. */
export function acoesPorSemana(autor) {
  const n = Number(autor?.acoesPorSemana)
  return OPCOES_ACOES_SEMANA.includes(n) ? n : null
}
export const SEMANAS_PARA_AVISO_RETOMADA = 3

/**
 * Monta a lista de ações desta semana para um autor.
 * Regra atual, em ordem:
 *   1. só ações da fase que CABEM para o autor (condições em `requer`);
 *   2. ações concluídas NESTA semana continuam visíveis, marcadas;
 *   3. pendentes ordenadas: prioritárias para o objetivo do autor, depois pela ordem cadastrada;
 *   4. corte pelo tempo semanal declarado (nunca abaixo de MIN, nunca acima de MAX);
 *   5. se ainda faltar para MIN, recicla as concluídas há mais tempo (ações são recorrentes).
 * Ações rejeitadas pelo autor ficam de fora, e também as de um tema que ele rejeitou 2 vezes (memoria.js).
 * Entre as pendentes, as que continuam algo já feito vêm primeiro.
 */
export function montarPlanoDaSemana(acoes, fase, autor, hoje = new Date()) {
  const { concluidas, rejeitadas = [] } = autor
  const idsRejeitados = new Set(rejeitadas.map((r) => r.acaoId))
  const daFase = acoes
    .filter((a) => a.fase === fase && !idsRejeitados.has(a.id) && acaoCabe(a, autor) && !evitadaPorTema(a, autor, acoes))
    .sort((a, b) => a.ordem - b.ordem)
  const idsConcluidos = new Set(concluidas.map((c) => c.acaoId))
  const inicioSemana = inicioDaSemana(hoje).getTime()
  const idsNestaSemana = new Set(concluidas.filter((c) => new Date(c.data).getTime() >= inicioSemana).map((c) => c.acaoId))

  const feitasNestaSemana = daFase.filter((a) => idsNestaSemana.has(a.id))
  const pendentes = ordenarParaAutor(daFase.filter((a) => !idsConcluidos.has(a.id)), autor)
    .sort((a, b) => Number(continuaAlgoFeito(b, autor)) - Number(continuaAlgoFeito(a, autor))) // estável: só puxa quem continua algo feito
  const candidatas = [...feitasNestaSemana, ...pendentes]
  // o autor pode fixar a quantidade; senão, a regra padrão corta pelo tempo declarado
  const escolha = acoesPorSemana(autor)
  const minimo = escolha ?? MIN_ACOES_SEMANA, maximo = escolha ?? MAX_ACOES_SEMANA
  const plano = escolha ? candidatas.slice(0, escolha) : caberNoTempo(candidatas, autor, minimo, maximo)

  if (plano.length < minimo) {
    const dataConclusao = (acaoId) => Math.max(...concluidas.filter((c) => c.acaoId === acaoId).map((c) => new Date(c.data).getTime()))
    const noPlano = new Set(plano.map((a) => a.id))
    const recicladas = daFase
      .filter((a) => !noPlano.has(a.id))
      .sort((a, b) => dataConclusao(a.id) - dataConclusao(b.id))
      .slice(0, minimo - plano.length)
    plano.push(...recicladas)
  }
  return plano
}

/** Verdadeiro na semana do cadastro, sem nenhuma atividade ainda: modo "primeira semana". */
export function ePrimeiraSemana(autor, hoje = new Date()) {
  const semAtividade = autor.concluidas.length === 0 && (autor.checkins || []).length === 0
  return semAtividade && semanasEntre(autor.cadastradoEm, hoje) === 0
}

/** Resumo da semana passada: quantas ações foram concluídas. */
export function resumoSemanaPassada(autor, hoje = new Date()) {
  const inicioAtual = inicioDaSemana(hoje)
  const inicioPassada = new Date(inicioAtual); inicioPassada.setDate(inicioPassada.getDate() - 7)
  const acoes = autor.concluidas.filter((c) => { const d = new Date(c.data); return d >= inicioPassada && d < inicioAtual }).length
  const checkins = (autor.checkins || []).filter((c) => { const d = new Date(c.data); return d >= inicioPassada && d < inicioAtual }).length
  return { acoes, checkins }
}

/**
 * Progresso da fase: ações distintas concluídas sobre as ações da fase.
 * Rejeitadas saem do total (o autor decidiu que não se aplicam).
 */
export function calcularProgressoFase(acoes, fase, concluidas, rejeitadas = []) {
  const idsRejeitados = new Set(rejeitadas.map((r) => r.acaoId))
  const daFase = acoes.filter((a) => a.fase === fase && !idsRejeitados.has(a.id))
  const idsConcluidos = new Set(concluidas.map((c) => c.acaoId))
  const feitas = daFase.filter((a) => idsConcluidos.has(a.id)).length
  const rejeitadasNaFase = acoes.filter((a) => a.fase === fase && idsRejeitados.has(a.id)).length
  return {
    feitas,
    total: daFase.length,
    rejeitadas: rejeitadasNaFase,
    percentual: daFase.length ? Math.round((feitas / daFase.length) * 100) : 0,
  }
}

/**
 * Semanas consecutivas com pelo menos uma ATIVIDADE (ação concluída ou
 * check-in), contando para trás. A semana atual só entra se já tiver
 * atividade; se ainda não tiver, a sequência não quebra (começa da anterior).
 * Para contar só ações, troque datasDeAtividade(autor) por autor.concluidas.
 */
export function calcularSemanasConsecutivas(autor, hoje = new Date()) {
  const datas = datasDeAtividade(autor)
  if (datas.length === 0) return 0
  const semanasComAcao = new Set(datas.map((d) => inicioDaSemana(d).getTime()))
  let cursor = inicioDaSemana(hoje)
  if (!semanasComAcao.has(cursor.getTime())) cursor.setDate(cursor.getDate() - 7)
  let sequencia = 0
  while (semanasComAcao.has(cursor.getTime())) {
    sequencia += 1
    cursor.setDate(cursor.getDate() - 7)
  }
  return sequencia
}

/** Data da última atividade (ação concluída ou check-in); cai na data de cadastro se nunca houve. */
export function ultimaAtividade(autor) {
  const datas = datasDeAtividade(autor)
  if (datas.length === 0) return autor.cadastradoEm
  return datas.reduce((max, d) => (new Date(d) > new Date(max) ? d : max), datas[0])
}

/** Verdadeiro quando o autor ficou SEMANAS_PARA_AVISO_RETOMADA semanas ou mais sem nenhuma atividade. */
export function precisaRetomar(autor, hoje = new Date()) {
  return semanasEntre(ultimaAtividade(autor), hoje) >= SEMANAS_PARA_AVISO_RETOMADA
}

/** Verdadeiro se a ação foi concluída na semana corrente. */
export function concluidaNestaSemana(acaoId, concluidas, hoje = new Date()) {
  const inicio = inicioDaSemana(hoje).getTime()
  return concluidas.some((c) => c.acaoId === acaoId && new Date(c.data).getTime() >= inicio)
}

/** Verdadeiro se a ação foi rejeitada na semana corrente. */
export function rejeitadaNestaSemana(acaoId, rejeitadas, hoje = new Date()) {
  const inicio = inicioDaSemana(hoje).getTime()
  return rejeitadas.some((r) => r.acaoId === acaoId && new Date(r.data).getTime() >= inicio)
}
