// Regras da Vitrine pública e da Página do Livro.

import { STATUS_LIVRO } from './fase.js'
import { extrairAsin, linkAfiliado } from './amazon.js'
import { AMAZON_TAG_AFILIADO } from '../marca.js'
import { verificarAcesso } from './acesso.js'
import { cadastroLiberado } from './aprovacao.js'
import { listaTrechos } from './trechos.js'

/** URL amigável a partir do título: "O Silêncio das Araucárias" -> "o-silencio-das-araucarias" */
export function slugify(texto) {
  return (texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
}

/**
 * Monta a lista de livros da vitrine:
 *   - livros dos autores cadastrados que aceitaram aparecer;
 *   - mais os livros extras (alunos sem cadastro no protótipo).
 * Livro não publicado entra com `emBreve: true` (sem botão de compra, só captura).
 */
export function montarVitrine(autores, extras = []) {
  // um autor pode ter vários livros: cada um vira um cartão (cadastros antigos têm só `livro`)
  const dosAutores = autores
    .filter((a) => a.aparecerNaVitrine && verificarAcesso(a).liberado && cadastroLiberado(a))
    .flatMap((a) => (Array.isArray(a.livros) && a.livros.length ? a.livros : [a.livro]).filter((l) => l && l.titulo).map((livro) => ({
      slug: livro.slug || slugify(livro.titulo),
      autorId: a.id,
      nomeAutor: a.nome,
      bioAutor: a.bio,
      redesAutor: a.redes || {},
      fotoAutor: a.foto || null,
      conquistas: (livro.conquistas || a.conquistas || []).filter((c) => c.texto && c.texto.trim()).slice().reverse(),
      ...livro,
      trechos: listaTrechos(livro), // depois do spread: aqui são só textos, não os objetos do cadastro
      asin: extrairAsin(livro.linkVenda),
      // A vitrine é da The Book Business: o botão de compra leva a tag de afiliado da casa.
      linkCompra: linkAfiliado(livro.linkVenda, AMAZON_TAG_AFILIADO),
      emBreve: livro.status !== STATUS_LIVRO.PUBLICADO,
    })))
  return [...dosAutores, ...extras.map((l) => ({ ...l, emBreve: false, linkCompra: linkAfiliado(l.linkVenda, AMAZON_TAG_AFILIADO) }))]
}

/** Filtro da vitrine por gênero e busca livre (título, subtítulo, autor). */
export function filtrarVitrine(livros, { genero = '', busca = '' } = {}) {
  const termo = normalizar(busca)
  return livros.filter((l) => {
    if (genero && l.genero !== genero) return false
    if (!termo) return true
    return normalizar(`${l.titulo} ${l.subtitulo} ${l.nomeAutor}`).includes(termo)
  })
}

/** Gêneros presentes na vitrine, em ordem alfabética (para o filtro). */
export function generosDaVitrine(livros) {
  return [...new Set(livros.map((l) => l.genero).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'pt-BR'))
}

export function encontrarLivro(livros, slug) {
  return livros.find((l) => l.slug === slug) || null
}

/** Leitores de um livro (aba "Meus leitores"), mais recentes primeiro. */
export function leitoresDoLivro(leitores, slug) {
  return leitores.filter((r) => r.slug === slug).sort((a, b) => new Date(b.data) - new Date(a.data))
}

function normalizar(t) {
  return (t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim()
}
