// Campos de formulário compartilhados (Cadastro do Livro e Painel do Administrador).

export const classeInput = 'campo'

export function Campo({ rotulo, ajuda, erro, children }) {
  return (
    <label className="block">
      <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1.5">{rotulo}</span>
      {children}
      {ajuda && !erro && <span className="block text-xs text-mudo mt-1">{ajuda}</span>}
      {erro && <span className="block text-xs text-alerta mt-1 font-bold">{erro}</span>}
    </label>
  )
}

export function Select({ valor, onChange, opcoes, vazio }) {
  return (
    <select value={valor} onChange={(e) => onChange(e.target.value)} className={classeInput}>
      {vazio && <option value="">{vazio}</option>}
      {opcoes.map((o) =>
        typeof o === 'string' ? (
          <option key={o} value={o}>{o}</option>
        ) : (
          <option key={o.valor} value={o.valor}>{o.rotulo}</option>
        ),
      )}
    </select>
  )
}

export function Escolha({ valor, onChange, opcoes }) {
  return (
    <div className="flex flex-wrap gap-2">
      {opcoes.map((o) => {
        const v = typeof o === 'string' ? o : o.valor
        const r = typeof o === 'string' ? o : o.rotulo
        const ativo = valor === v
        return (
          <button
            key={v}
            type="button"
            onClick={() => onChange(v)}
            className={
              'text-[13px] font-bold px-3.5 py-2 transition-colors corte-btn ' +
              (ativo ? 'bg-tinta text-white border-2 border-tinta' : 'bg-white text-apoio border-2 border-fio hover:border-tinta')
            }
          >
            {r}
          </button>
        )
      })}
    </div>
  )
}

/** Vários valores (checkbox em forma de botão). */
export function EscolhaMultipla({ valores, onChange, opcoes }) {
  const alternar = (v) => onChange(valores.includes(v) ? valores.filter((x) => x !== v) : [...valores, v])
  return (
    <div className="flex flex-wrap gap-2">
      {opcoes.map((o) => {
        const v = typeof o === 'string' ? o : o.valor
        const r = typeof o === 'string' ? o : o.rotulo
        const ativo = valores.includes(v)
        return (
          <button
            key={v}
            type="button"
            onClick={() => alternar(v)}
            className={
              'text-[13px] font-bold px-3.5 py-2 transition-colors corte-btn ' +
              (ativo ? 'bg-tinta text-white border-2 border-tinta' : 'bg-white text-apoio border-2 border-fio hover:border-tinta')
            }
          >
            {r}
          </button>
        )
      })}
    </div>
  )
}

export const BOTAO_PRIMARIO = 'btn-primario'
export const BOTAO_SECUNDARIO = 'btn-preto'
export const BOTAO_LINK = 'btn-linha'
