import { useRef, useState } from 'react'
import { otimizarImagem, formatarBytes } from '../regras/imagens.js'
import { guardarImagem } from '../servicos/imagens.js'

/**
 * Campo de imagem com otimização automática (redimensiona + comprime em WebP).
 * `valor` é um data URL; `onChange(dataUrl|null)`.
 */
export default function UploadImagem({ valor, onChange, perfil = 'capa', rotulo, ajuda, formato = 'capa' }) {
  const input = useRef(null)
  const [estado, setEstado] = useState('')
  const [erro, setErro] = useState('')

  async function escolher(e) {
    const f = e.target.files?.[0]
    e.target.value = ''
    if (!f) return
    setErro(''); setEstado('Otimizando…')
    try {
      const r = await otimizarImagem(f, perfil)
      setEstado('Enviando…')
      onChange(await guardarImagem(r.dataUrl, perfil === 'foto' ? 'foto' : 'capa'))
      setEstado(`${r.largura}×${r.altura}, ${formatarBytes(r.bytes)} (original ${formatarBytes(f.size)})`)
    } catch (err) {
      setErro(err.message); setEstado('')
    }
  }

  const caixa = formato === 'foto' ? 'w-28 h-28 rounded-full' : 'w-28 min-h-16'
  return (
    <div>
      <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1.5">{rotulo}</span>
      <div className="flex items-start gap-4">
        <div className={`${caixa} bg-areia border-2 border-fio overflow-hidden grid place-items-center shrink-0`}>
          {valor ? <img src={valor} alt="" className={formato === 'foto' ? 'w-full h-full object-cover' : 'block w-full h-auto'} /> : <span className="text-[11px] text-mudo text-center px-2">sem imagem</span>}
        </div>
        <div className="grid gap-2 content-start">
          <div className="flex flex-wrap gap-2">
            <button type="button" onClick={() => input.current?.click()} className="btn-preto !py-1.5 !text-[12px]">{valor ? 'Trocar' : 'Enviar imagem'}</button>
            {valor && <button type="button" onClick={() => { onChange(null); setEstado('') }} className="btn-linha">Remover</button>}
          </div>
          <input ref={input} type="file" accept="image/jpeg,image/png,image/webp" onChange={escolher} className="hidden" />
          {ajuda && !erro && !estado && <span className="text-xs text-mudo">{ajuda}</span>}
          {estado && <span className="text-xs text-mudo">{estado}</span>}
          {erro && <span className="text-xs text-alerta font-bold">{erro}</span>}
        </div>
      </div>
    </div>
  )
}
