// Lembrete semanal sem servidor: evento recorrente no calendário do autor.
// Gera um .ics (Apple/Outlook) e um link do Google Agenda.

function proximaSegunda(hoje = new Date(), hora = 9) {
  const d = new Date(hoje)
  d.setHours(hora, 0, 0, 0)
  const dia = d.getDay() // 0 dom ... 1 seg
  const faltam = (8 - dia) % 7 || 7
  if (!(dia === 1 && hoje.getHours() < hora)) d.setDate(d.getDate() + faltam)
  return d
}

function fmtICS(d) {
  const p = (n) => String(n).padStart(2, '0')
  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}T${p(d.getHours())}${p(d.getMinutes())}00`
}

/** Dados do lembrete conforme a preferência do autor (semanal ou diário). */
export function montarLembrete(autor, urlApp, hoje = new Date()) {
  const diario = autor.lembrete === 'diario'
  const inicio = diario ? (() => { const d = new Date(hoje); d.setDate(d.getDate() + 1); d.setHours(9, 0, 0, 0); return d })() : proximaSegunda(hoje)
  const fim = new Date(inicio.getTime() + 15 * 60 * 1000)
  const titulo = diario ? `LOMBADA: 15 minutos pelo ${autor.livro.titulo}` : `LOMBADA: sua semana pelo ${autor.livro.titulo}`
  const descricao = diario
    ? `Abra seu plano e faça uma ação pelo livro. ${urlApp}`
    : `Nova semana, novo plano. Abra o LOMBADA, veja as ações da semana e marque a primeira. ${urlApp}`
  const regra = diario ? 'FREQ=DAILY;BYDAY=MO,TU,WE,TH,FR' : 'FREQ=WEEKLY;BYDAY=MO'
  return { titulo, descricao, inicio, fim, regra, diario }
}

export function gerarICS(lembrete, urlApp) {
  const uid = `lombada-${Date.now()}@thebookbusiness.com.br`
  return [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//LOMBADA//The Book Business//PT',
    'BEGIN:VEVENT', `UID:${uid}`, `DTSTAMP:${fmtICS(new Date())}Z`,
    `DTSTART;TZID=America/Sao_Paulo:${fmtICS(lembrete.inicio)}`, `DTEND;TZID=America/Sao_Paulo:${fmtICS(lembrete.fim)}`,
    `RRULE:${lembrete.regra}`, `SUMMARY:${lembrete.titulo}`, `DESCRIPTION:${lembrete.descricao.replace(/\n/g, '\\n')}`, `URL:${urlApp}`,
    'BEGIN:VALARM', 'TRIGGER:PT0M', 'ACTION:DISPLAY', `DESCRIPTION:${lembrete.titulo}`, 'END:VALARM',
    'END:VEVENT', 'END:VCALENDAR',
  ].join('\r\n')
}

export function linkGoogleAgenda(lembrete) {
  const p = new URLSearchParams({
    action: 'TEMPLATE',
    text: lembrete.titulo,
    details: lembrete.descricao,
    dates: `${fmtICS(lembrete.inicio)}/${fmtICS(lembrete.fim)}`,
    ctz: 'America/Sao_Paulo',
    recur: `RRULE:${lembrete.regra}`,
  })
  return `https://calendar.google.com/calendar/render?${p.toString()}`
}

/** Texto curto para compartilhar o progresso (WhatsApp, grupo, stories). */
export function textoDeProgresso({ autor, fase, feitasNaSemana, totalNaSemana, sequencia, tituloProxima }) {
  const nomeFase = { construcao: 'Construção', lancamento: 'Lançamento', permanencia: 'Permanência' }[fase] || fase
  const linhas = [
    `Minha semana pelo livro "${autor.livro.titulo}" (fase ${nomeFase}):`,
    `${feitasNaSemana} de ${totalNaSemana} ações concluídas · ${sequencia} ${sequencia === 1 ? 'semana seguida' : 'semanas seguidas'} sem parar.`,
  ]
  if (tituloProxima) linhas.push(`Próxima: ${tituloProxima}.`)
  linhas.push('#MetodoTheBookBusiness #LOMBADA')
  return linhas.join('\n')
}

export function linkWhatsApp(texto) {
  return `https://wa.me/?text=${encodeURIComponent(texto)}`
}
