// Aprovação do cadastro: o autor só entra depois que o time confere e libera.
// Autores antigos sem o campo `cadastro` contam como aprovados (compatibilidade).

export const STATUS_CADASTRO = { EM_ANALISE: 'em_analise', APROVADO: 'aprovado', AJUSTAR: 'ajustar' }
export const NOME_STATUS_CADASTRO = { em_analise: 'Em análise', aprovado: 'Aprovado', ajustar: 'Pedir ajustes' }

export function statusCadastro(autor) {
  return autor?.cadastro?.status || STATUS_CADASTRO.APROVADO
}

/** Só aprovado entra no plano e aparece na vitrine. */
export function cadastroLiberado(autor) {
  return statusCadastro(autor) === STATUS_CADASTRO.APROVADO
}

/** O que ainda falta para o cadastro estar completo (rótulos legíveis). Vazio = completo. */
export function camposFaltando(autor) {
  const l = autor.livro || {}
  const falta = []
  const vazio = (v) => v === undefined || v === null || String(v).trim() === ''
  if (vazio(l.titulo)) falta.push('título do livro')
  if (vazio(l.genero)) falta.push('gênero')
  if (vazio(l.subNicho)) falta.push('sub-nicho')
  if (vazio(l.publicoAlvo)) falta.push('público-alvo')
  if (vazio(l.sinopse)) falta.push('sinopse')
  if (vazio(l.promessa)) falta.push('promessa do livro')
  if (vazio(l.trecho) && !(l.trechos || []).some((t) => (typeof t === 'string' ? t : t?.texto || '').trim())) falta.push('trecho do livro')
  if (!l.capa && !l.linkVenda) falta.push('capa do livro')
  if (l.status === 'publicado') {
    if (vazio(l.dataPublicacao)) falta.push('data de publicação')
    if (l.naAmazon !== false && vazio(l.linkVenda)) falta.push('link da Amazon')
  }
  if (vazio(autor.nome)) falta.push('nome')
  if (vazio(autor.email)) falta.push('e-mail')
  if (vazio(autor.whatsapp)) falta.push('WhatsApp')
  if (vazio(autor.cidade)) falta.push('cidade')
  if (vazio(autor.profissao)) falta.push('profissão')
  if (vazio(autor.bio)) falta.push('bio')
  if (!autor.foto) falta.push('foto')
  return falta
}

export function cadastroCompleto(autor) {
  return camposFaltando(autor).length === 0
}

/** Ao salvar o cadastro: novo entra em análise; quem estava em "ajustar" volta para análise; aprovado segue aprovado. */
export function proximoStatusAoSalvar(inicial) {
  const atual = inicial?.cadastro
  if (!inicial) return { status: STATUS_CADASTRO.EM_ANALISE, enviadoEm: new Date().toISOString() }
  if (atual?.status === STATUS_CADASTRO.AJUSTAR) return { ...atual, status: STATUS_CADASTRO.EM_ANALISE, enviadoEm: new Date().toISOString(), observacao: atual.observacao }
  return atual || { status: STATUS_CADASTRO.APROVADO }
}


/** Avisos para a equipe (não bloqueiam): o link da Amazon parece ser de outro livro. */
export function avisosCadastro(autor) {
  const avisos = []
  for (const l of (Array.isArray(autor?.livros) && autor.livros.length ? autor.livros : [autor?.livro]).filter(Boolean)) {
    if (l.amazon && l.amazon.bate === false) avisos.push(`o link da Amazon de "${l.titulo}" aponta para "${l.amazon.titulo}"${l.amazon.autor ? `, de ${l.amazon.autor}` : ''}${l.amazon.confirmado ? ' (o autor confirmou que é dele)' : ''}`)
  }
  return avisos
}
