import { useState } from 'react'
import { leitoresDoLivro, slugify } from '../regras/vitrine.js'
import { slugsDoAutor } from '../regras/livros.js'
import { formatarData } from '../regras/datas.js'

export default function MeusLeitores({ autor, leitores, onVoltar }) {
  const slug = slugify(autor.livro.titulo)
  const slugs = slugsDoAutor(autor)
  const lista = slugs.length > 1 ? leitores.filter((l) => slugs.includes(l.slug)) : leitoresDoLivro(leitores, slug)
  const [copiado, setCopiado] = useState(false)
  const urlPagina = `${window.location.origin}${import.meta.env.BASE_URL.replace(/\/$/, '')}/livro/${slug}`

  function baixarCSV() {
    const linhas = [['nome', 'email', 'data'], ...lista.map((l) => [l.nome || '', l.email, new Date(l.data).toISOString().slice(0, 10)])]
    const csv = linhas.map((c) => c.map((v) => `"${String(v).replace(/"/g, '""')}"`).join(';')).join('\n')
    const blob = new Blob(['\ufeff' + csv], { type: 'text/csv;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a'); a.href = url; a.download = `leitores-${slug}.csv`; a.click()
    URL.revokeObjectURL(url)
  }

  async function copiarEmails() {
    try { await navigator.clipboard.writeText(lista.map((l) => l.email).join(', ')) } catch { /* sem clipboard */ }
    setCopiado(true); setTimeout(() => setCopiado(false), 2000)
  }

  return (
    <div>
      <button onClick={onVoltar} className="btn-linha">← Voltar ao perfil</button>
      <header className="grid grid-cols-1 md:grid-cols-[1fr_260px] mt-5">
        <div className="bg-tinta text-white px-8 py-8 relative z-10 md:corte-d">
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Meus leitores</p>
          <h1 className="display text-[34px] sm:text-[42px] mt-3 text-balance">{lista.length} {lista.length === 1 ? 'leitor quer' : 'leitores querem'} novidades de {autor.livro.titulo}</h1>
          <p className="text-[13.5px] text-white/75 mt-3">Quem deixa o e-mail na sua página do livro aparece aqui. Só você vê esta lista.</p>
        </div>
        <div className="bg-ambar text-tinta px-7 py-7 md:-ml-[44px] md:pl-[72px] grid content-between gap-4">
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em]">Sua página</p>
          {autor.aparecerNaVitrine ? (
            <a href={urlPagina} target="_blank" rel="noopener noreferrer" className="font-bold text-[13px] break-all underline underline-offset-4 decoration-2">{urlPagina.replace(/^https?:\/\//, '')}</a>
          ) : (
            <p className="text-[13px] font-semibold">Seu livro não está na vitrine. Ative em "Editar cadastro" para ganhar uma página pública.</p>
          )}
        </div>
      </header>

      {lista.length === 0 ? (
        <div className="bg-areia px-6 py-6 mt-6 text-[14px] text-apoio">Ainda ninguém se cadastrou. Compartilhe o link da sua página nas redes e na assinatura do e-mail.</div>
      ) : (
        <>
          <div className="flex flex-wrap justify-end gap-3 mt-6 mb-3">
            <button onClick={baixarCSV} className="btn bg-white border-2 border-tinta text-tinta corte-btn">Baixar CSV</button>
            <button onClick={copiarEmails} className="btn-preto min-w-[190px]">{copiado ? 'Copiado' : 'Copiar todos os e-mails'}</button>
          </div>
          <table className="w-full text-[14px]">
            <thead>
              <tr className="text-left text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo border-b-2 border-tinta">
                <th className="py-2">Nome</th><th className="py-2">E-mail</th><th className="py-2 text-right">Cadastro</th>
              </tr>
            </thead>
            <tbody>
              {lista.map((l, i) => (
                <tr key={i} className="border-b border-fio">
                  <td className="py-3 font-semibold">{l.nome || <span className="text-mudo font-normal">sem nome</span>}</td>
                  <td className="py-3 text-apoio">{l.email}</td>
                  <td className="py-3 text-right text-mudo tabular-nums">{formatarData(l.data)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </>
      )}
    </div>
  )
}
