import { NOME_PRODUTO } from '../marca.js'

/**
 * O anel do LOMBADA: um O com dois cortes verticais retos, em cima e embaixo.
 * Em SVG para o corte ficar reto em qualquer tamanho. Herda a cor do texto.
 */
export function AnelLombada({ className = '', style = {} }) {
  // caixa 100x100; traço fino (12), como o anel original; fenda de 10 no centro, em cima e embaixo
  return (
    <svg viewBox="0 0 100 100" aria-hidden="true" className={className} style={{ display: 'inline-block', ...style }}>
      <defs>
        <clipPath id="fenda-lombada">
          <rect x="0" y="0" width="45" height="100" />
          <rect x="55" y="0" width="45" height="100" />
        </clipPath>
      </defs>
      <circle cx="50" cy="50" r="44" fill="none" stroke="currentColor" strokeWidth="12" clipPath="url(#fenda-lombada)" />
    </svg>
  )
}

/** L○MBADA: o primeiro O vira o anel com fendas. `tamanho` em px. */
export default function Wordmark({ tamanho = 22, className = '' }) {
  const [antes, ...resto] = NOME_PRODUTO.split('O')
  const depois = resto.join('O')
  return (
    <span
      className={'display inline-flex items-center whitespace-nowrap ' + className}
      style={{ fontSize: tamanho, letterSpacing: '-0.03em' }}
      aria-label={NOME_PRODUTO}
    >
      {antes}
      <AnelLombada className="bate" style={{ width: '0.8em', height: '0.8em', margin: '0 0.02em', position: 'relative', top: '0.02em' }} />
      {depois}
    </span>
  )
}
