import { useState } from 'react'
import { formatarData } from '../regras/datas.js'

/** Canto do autor para sugerir melhorias no LOMBADA. Vai para o time (aba Sugestões no Admin). */
export default function Sugestoes({ autor, sugestoes, onEnviar, onVoltar }) {
  const [texto, setTexto] = useState('')
  const [enviada, setEnviada] = useState(false)
  const minhas = sugestoes.filter((s) => s.autorId === autor.id).sort((a, b) => new Date(b.data) - new Date(a.data))

  function enviar(e) {
    e.preventDefault()
    if (!texto.trim()) return
    onEnviar(autor.id, texto.trim())
    setTexto(''); setEnviada(true); setTimeout(() => setEnviada(false), 4000)
  }

  return (
    <div>
      <button onClick={onVoltar} className="btn-linha">← Voltar ao perfil</button>
      <header className="mt-5 bg-tinta text-white px-8 py-8 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Sugestões</p>
        <h1 className="display text-[34px] sm:text-[42px] mt-3 text-balance">O LOMBADA é feito com quem usa.</h1>
        <p className="text-[13.5px] text-white/75 mt-3 max-w-[56ch]">Faltou uma ação? Um texto não soou como você? Uma tela confunde? Conta aqui. O time do Método The Book Business lê tudo.</p>
      </header>

      <form onSubmit={enviar} className="mt-6 bg-areia px-6 py-6 grid gap-4">
        <label className="block">
          <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1">Sua sugestão</span>
          <textarea value={texto} onChange={(e) => setTexto(e.target.value)} className="campo min-h-28" placeholder="O que melhoraria o LOMBADA para você? Pode ser uma ideia, uma reclamação ou um elogio." />
        </label>
        <div className="flex flex-wrap items-center gap-3">
          <button type="submit" disabled={!texto.trim()} className="btn-primario disabled:opacity-40">Enviar sugestão</button>
          {enviada && <span className="text-[13px] font-bold text-verde surge-toast">Recebida. Obrigado, {autor.nome.split(' ')[0]}.</span>}
        </div>
      </form>

      {minhas.length > 0 && (
        <section className="mt-8">
          <h2 className="display text-[20px] mb-3">O que você já sugeriu</h2>
          <ul className="grid gap-3">
            {minhas.map((s) => (
              <li key={s.id} className="bg-white border-2 border-fio px-5 py-4">
                <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo">{formatarData(s.data)} · {s.status === 'lida' ? 'lida pelo time' : 'recebida'}</p>
                <p className="text-[14px] mt-1 leading-relaxed">{s.texto}</p>
              </li>
            ))}
          </ul>
        </section>
      )}
    </div>
  )
}
