// Assinatura do catálogo (ações, modelos, oportunidades). Muda sozinha quando o conteúdo muda no código,
// então o navegador troca o catálogo salvo sem depender de alguém lembrar de subir um número de versão.
export function assinaturaCatalogo(...listas) {
  const texto = JSON.stringify(listas)
  let h = 2166136261
  for (let i = 0; i < texto.length; i++) { h ^= texto.charCodeAt(i); h = Math.imul(h, 16777619) }
  return (h >>> 0).toString(36) + ':' + texto.length
}
