// Links da Amazon: extrair o ASIN, montar o link de afiliado e a capa oficial.
// Única função responsável por cada coisa.

/** Verdadeiro se a URL é da Amazon (qualquer país). */
export function eLinkAmazon(url) {
  const u = (url || '').trim()
  return /^https?:\/\/([a-z0-9-]+\.)*amazon\.[a-z.]+\//i.test(u)       // amazon.com.br, amazon.com, www.amazon...
    || /^https?:\/\/(www\.)?amzn\.(to|com\.br|eu)\//i.test(u)          // amzn.to/...
    || /^https?:\/\/(www\.)?link\.amazon\//i.test(u)                    // link.amazon/... (encurtador do Associados)
}

/** ASIN (10 caracteres) a partir de /dp/ASIN, /gp/product/ASIN, /gp/aw/d/ASIN ou ?asin=. Null se não achar. */
export function extrairAsin(url) {
  const u = (url || '').trim()
  const m = u.match(/\/(?:dp|gp\/product|gp\/aw\/d|product)\/([A-Z0-9]{10})(?:[/?#]|$)/i) || u.match(/[?&]asin=([A-Z0-9]{10})/i)
  return m ? m[1].toUpperCase() : null
}

/** Domínio da loja (amazon.com.br por padrão). */
export function dominioAmazon(url) {
  const m = (url || '').match(/https?:\/\/(?:[a-z0-9-]+\.)*(amazon\.[a-z.]+?)\//i)
  return m ? m[1].replace(/\.$/, '') : 'amazon.com.br'
}

/**
 * Link limpo com a tag de afiliado. Sem ASIN, devolve a URL original com a tag
 * acrescentada (funciona para links encurtados que redirecionam).
 */
/** Link curto do Associados (amzn.to, link.amazon): já carrega a atribuição, não mexer. */
export function eLinkCurtoAmazon(url) {
  const u = (url || '').trim()
  return /^https?:\/\/(www\.)?amzn\.(to|com\.br|eu)\//i.test(u) || /^https?:\/\/(www\.)?link\.amazon\//i.test(u)
}

export function linkAfiliado(url, tag) {
  if (!url) return url
  if (!tag) return url
  if (eLinkCurtoAmazon(url)) return url.trim()
  const asin = extrairAsin(url)
  if (asin) return `https://www.${dominioAmazon(url)}/dp/${asin}?tag=${encodeURIComponent(tag)}`
  try {
    const u = new URL(url)
    u.searchParams.set('tag', tag)
    return u.toString()
  } catch {
    return url
  }
}

/** Capa oficial da Amazon pelo ASIN (imagem pública do catálogo). */
export function urlCapaAmazon(asin, tamanho = 'L') {
  return asin ? `https://images-na.ssl-images-amazon.com/images/P/${asin}.01.${tamanho}.jpg` : null
}


/** Normaliza para comparar títulos: minúsculas, sem acento, sem pontuação, sem subtítulo depois de ":" . */
export function normalizarTitulo(t) {
  return String(t || '').split(':')[0].toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim()
}

/** O título da página da Amazon é o mesmo livro do cadastro? Tolera subtítulo e pequenas diferenças (60% das palavras em comum). */
export function titulosBatem(cadastro, amazon) {
  const a = normalizarTitulo(cadastro), b = normalizarTitulo(amazon)
  if (!a || !b) return false
  if (a === b || a.includes(b) || b.includes(a)) return true
  const pa = new Set(a.split(' ').filter((w) => w.length > 2)), pb = new Set(b.split(' ').filter((w) => w.length > 2))
  if (!pa.size || !pb.size) return false
  const comuns = [...pa].filter((w) => pb.has(w)).length
  return comuns / Math.min(pa.size, pb.size) >= 0.6
}
