// Forma canônica do autor: o que vem do banco (ou de um cliente antigo) pode faltar listas.
// Usado pelo app e pelo servidor (e-mail semanal), por isso fica fora de servicos/nuvem.js.
// Desde 17/09/2026 o autor tem vários livros (`livros[]`, `livroFoco`): aqui migramos o formato antigo
// e projetamos o livro em foco em `livro`/`concluidas`/... para o resto do código continuar igual.
import { migrarLivros, projetar } from './livros.js'

export function normalizarAutor(d) {
  if (!d) return d
  const a = projetar(migrarLivros(d))
  return {
    ...a,
    nome: a.nome || '',
    audiencia: a.audiencia || {},
    redes: a.redes || {},
    cadastradoEm: a.cadastradoEm || new Date().toISOString(),
  }
}
