// Medição de uso do LOMBADA: cada tela aberta, clique que importa e pulso de permanência
// vira um evento. Os eventos ficam numa fila e vão para o banco em lote a cada poucos segundos
// (RPC lombada_eventos_gravar, com o token da sessão). Sem token (protótipo local), não grava nada.
//
// Uso: import { uso } from '../servicos/uso.js'  →  uso('aula', { pageId })
// Eventos: tela · pulso · entrou · concluiu · desfez · rejeitou · checkin · conquista · copiou_texto
//          aula · ferramenta · card · gerador · lembrete · oportunidade · comunidade · compartilhou_pagina

let enviar = null          // (lote) => Promise
let fila = []
let timer = null
let pulso = null
const SESSAO = (typeof crypto !== 'undefined' && crypto.randomUUID ? crypto.randomUUID() : String(Date.now())).slice(0, 12)
const dispositivo = () => (typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(max-width: 767px)').matches ? 'celular' : 'desktop')

export function configurarUso(fn) {
  enviar = fn
  if (pulso) { clearInterval(pulso); pulso = null }
  if (fn) {
    // 1 pulso por minuto com a aba visível = minutos de permanência
    pulso = setInterval(() => { if (typeof document === 'undefined' || document.visibilityState === 'visible') uso('pulso') }, 60000)
    if (typeof document !== 'undefined' && !configurarUso._ouvindo) {
      configurarUso._ouvindo = true
      document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') despachar() })
      window.addEventListener('pagehide', despachar)
    }
  }
}

let ultimo = { chave: '', em: 0 }
export function uso(evento, dados) {
  if (!enviar || !evento) return
  // o mesmo evento repetido em menos de 1,5s é eco (StrictMode, duplo clique), não uso
  const chave = evento + JSON.stringify(dados || null)
  const agora = Date.now()
  if (chave === ultimo.chave && agora - ultimo.em < 1500) return
  ultimo = { chave, em: agora }
  fila.push({ evento, dados: dados || null, sessao: SESSAO, dispositivo: dispositivo(), em: new Date().toISOString() })
  if (fila.length >= 20) despachar()
  else if (!timer) timer = setTimeout(despachar, 4000)
}

export function despachar() {
  if (timer) { clearTimeout(timer); timer = null }
  if (!enviar || fila.length === 0) return
  const lote = fila; fila = []
  Promise.resolve(enviar(lote)).catch(() => { /* perder um lote de uso não pode atrapalhar o autor */ })
}
