import { montarHistorico, agruparPorSemana } from '../regras/checkin.js'
import { formatarData, formatarDataLonga } from '../regras/datas.js'

const ROTULO = { checkin: 'Check-in', concluida: 'Ação concluída', rejeitada: 'Não se aplica' }
const COR = { checkin: 'bg-verde', concluida: 'bg-tinta', rejeitada: 'bg-fio' }

export default function Historico({ autor, acoes, onVoltar }) {
  const semanas = agruparPorSemana(montarHistorico(autor, acoes))
  const totalCheckins = (autor.checkins || []).length

  return (
    <div>
      <button onClick={onVoltar} className="btn-linha">← Voltar ao plano da semana</button>
      <header className="mt-5 bg-tinta text-white px-8 py-8 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Histórico</p>
        <h1 className="display text-[34px] sm:text-[42px] mt-3 text-balance">Tudo o que você já fez por {autor.livro.titulo}</h1>
        <p className="text-[13.5px] text-white/75 mt-3 font-semibold">
          {totalCheckins} {totalCheckins === 1 ? 'check-in' : 'check-ins'} · {autor.concluidas.length} {autor.concluidas.length === 1 ? 'ação concluída' : 'ações concluídas'}
        </p>
      </header>

      {semanas.length === 0 && <p className="text-mudo mt-8">Ainda não há registros. O primeiro check-in aparece aqui.</p>}

      <ol className="mt-8 space-y-10">
        {semanas.map((semana) => (
          <li key={semana.inicio.getTime()}>
            <h2 className="display text-[20px] mb-4">Semana de {formatarDataLonga(semana.inicio)}</h2>
            <ul className="grid gap-3">
              {semana.itens.map((item, i) => (
                <li key={i} className="relative grid grid-cols-[16px_1fr] gap-4 bg-areia pl-7 pr-5 py-5">
                  <i className={'absolute left-0 top-0 bottom-0 w-4 ' + COR[item.tipo]} style={{ clipPath: 'polygon(0 0, 100% 0, 40% 100%, 0 100%)' }} />
                  <span />
                  <div>
                    <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo">{formatarData(item.data)} · {ROTULO[item.tipo]}</p>
                    <p className={'mt-1 leading-relaxed ' + (item.tipo === 'checkin' ? 'text-tinta font-semibold text-[15px]' : 'text-apoio text-[14px]')}>{item.texto}</p>
                  </div>
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ol>
    </div>
  )
}
