import { formatarDataLonga } from '../regras/datas.js'

export default function AvisoRetomada({ ultimaConclusao, proximaAcao, onRetomar }) {
  return (
    <div className="bg-creme px-7 py-6 mb-8 corte-d">
      <p className="display text-[26px]">Faz um tempo que você não registra nada pelo livro.</p>
      <p className="text-[14px] text-apoio mt-3 max-w-[60ch]">
        {ultimaConclusao ? `Sua última atividade foi em ${formatarDataLonga(ultimaConclusao)}. ` : 'Você ainda não registrou nenhuma atividade. '}
        Tudo bem. Seu plano continua do ponto onde parou{proximaAcao ? `: "${proximaAcao.titulo}".` : '.'}
      </p>
      <button onClick={onRetomar} className="btn-preto mt-4">Retomar o plano</button>
    </div>
  )
}
