// Resumo do painel da Amazon a partir do histórico diário de um livro (leituras públicas: ranking, nota, avaliações).
// Sem interface: só números prontos para a tela.

const DIA = 86400000

/** Leitura mais próxima de `alvo` (ms) que seja anterior ou igual a ele. */
function leituraEm(historico, alvo) {
  let melhor = null
  for (const h of historico) {
    const t = new Date(h.lidoEm).getTime()
    if (t <= alvo && (!melhor || t > new Date(melhor.lidoEm).getTime())) melhor = h
  }
  return melhor
}

/**
 * @param {Array<{lidoEm, ranking, rankings, nota, avaliacoes, titulo, autor, preco}>} historico ordenado por data
 * @returns null se não há leitura; senão { hoje, ranking, variacao7 (negativo = melhorou), avaliacoes, avaliacoesNovas7, nota, categorias, titulo, autor, preco, lidoEm, dias }
 */
export function resumoAmazon(historico, agora = new Date()) {
  const lista = (historico || []).filter((h) => h && h.lidoEm).sort((a, b) => new Date(a.lidoEm) - new Date(b.lidoEm))
  if (!lista.length) return null
  const hoje = lista[lista.length - 1]
  const ha7 = leituraEm(lista, new Date(hoje.lidoEm).getTime() - 7 * DIA) || lista[0]
  const variacao7 = hoje.ranking && ha7.ranking && ha7 !== hoje ? hoje.ranking - ha7.ranking : null
  const avaliacoesNovas7 = hoje.avaliacoes != null && ha7.avaliacoes != null && ha7 !== hoje ? Math.max(0, hoje.avaliacoes - ha7.avaliacoes) : 0
  const categorias = (hoje.rankings || []).filter((r) => !/Loja Kindle|^Livros$/i.test(r.lista)).slice(0, 3)
  return {
    hoje, ranking: hoje.ranking || null, variacao7, avaliacoes: hoje.avaliacoes ?? null, avaliacoesNovas7,
    nota: hoje.nota ?? null, categorias, titulo: hoje.titulo, autor: hoje.autor, preco: hoje.preco || null,
    lidoEm: hoje.lidoEm, dias: lista.length,
    horasDesde: Math.round((agora - new Date(hoje.lidoEm)) / 3600000),
  }
}

/** Frase curta sobre a variação do ranking. */
export function fraseVariacao(variacao7) {
  if (variacao7 == null) return 'Primeira leitura. A partir de amanhã, comparo com a semana anterior.'
  if (variacao7 < 0) return `Subiu ${Math.abs(variacao7).toLocaleString('pt-BR')} posições em 7 dias.`
  if (variacao7 > 0) return `Caiu ${variacao7.toLocaleString('pt-BR')} posições em 7 dias.`
  return 'Mesma posição de 7 dias atrás.'
}
