import Wordmark from '../componentes/Wordmark.jsx'
import { URL_SUPORTE } from '../marca.js'
import { STATUS_ACESSO } from '../regras/acesso.js'
import { formatarDataLonga } from '../regras/datas.js'

/** Tela que substitui a área logada quando o acesso ao Método The Book Business não está ativo. */
export default function AcessoBloqueado({ autor, acesso, onTrocarAutor, onSair }) {
  const reembolso = acesso.status === STATUS_ACESSO.REEMBOLSADO
  return (
    <div className="min-h-screen">
      <div className="border-b-2 border-tinta">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <Wordmark tamanho={24} />
          <span className="flex items-center gap-3">
            {onTrocarAutor && <button onClick={onTrocarAutor} className="btn-linha">ver outros autores (protótipo)</button>}
            {onSair && <button onClick={onSair} className="btn-linha">Sair</button>}
          </span>
        </div>
      </div>
      <main className="max-w-4xl mx-auto px-4 sm:px-6 py-8">
        <header className="grid grid-cols-1 md:grid-cols-[1.3fr_1fr]">
          <div className="bg-tinta text-white px-7 py-9 sm:px-9 relative z-10 md:corte-d">
            <p className="text-[12px] font-bold uppercase tracking-[.12em] text-ambar">Acesso</p>
            <h1 className="display text-[38px] sm:text-[50px] mt-3 text-balance">{autor.nome.split(' ')[0]}, seu acesso ao LOMBADA está pausado.</h1>
            <p className="text-[15px] text-white/75 mt-4 max-w-[48ch]">
              {acesso.motivo}{acesso.ate && acesso.status === STATUS_ACESSO.VENCIDO ? ` O prazo terminou em ${formatarDataLonga(acesso.ate)}.` : ''} O LOMBADA faz parte do Método The Book Business: quem está com o acesso ativo entra, planeja a semana e acompanha o livro.
            </p>
            <p className="text-[15px] text-white mt-4 max-w-[48ch] font-semibold">
              {reembolso ? 'Para voltar, fale com a Dezza.' : 'Para renovar, fale com a Dezza.'} Ela confere o seu cadastro e libera o acesso. A conversa já vai começar com a sua situação explicada.
            </p>
            <div className="mt-7 flex flex-wrap gap-3">
              <a href={URL_SUPORTE} target="_blank" rel="noopener noreferrer" className="btn-primario !text-[15px] !px-7 !py-3.5">Falar com a Dezza no WhatsApp</a>
            </div>
          </div>
          <div className="bg-alerta relative md:-ml-[44px] min-h-[200px] overflow-hidden">
            <div className="absolute inset-0 grid grid-cols-3 grid-rows-2 md:grid-cols-2 md:grid-rows-3 gap-3 px-6 pt-5 pb-8 md:p-6 md:pl-14">
              {['#1a1a1a', 'anel', '#f3f0e8', 'anel', '#1a1a1a', '#f3f0e8'].map((c, i) => (
                <i key={i} className="rounded-full aspect-square self-center justify-self-center" style={{ width: 'min(100%, 76px)', background: c === 'anel' ? 'transparent' : c, border: c === 'anel' ? '7px solid #1a1a1a' : 'none' }} />
              ))}
            </div>
          </div>
        </header>
        <section className="mt-8 bg-areia px-7 py-6 text-[14px] max-w-[70ch]">
          <p className="font-extrabold">O que fica guardado</p>
          <p className="text-apoio mt-1">Seu livro, seu histórico de ações, check-ins e a lista de leitores continuam salvos. Quando a Dezza liberar, você volta exatamente de onde parou, com a sequência preservada.</p>
          <p className="text-apoio mt-3">A página pública do seu livro na vitrine também fica pausada enquanto o acesso não estiver ativo.</p>
        </section>
      </main>
    </div>
  )
}
