import { useEffect, useState } from 'react'
import { extrairAsin } from '../regras/amazon.js'
import { resumoAmazon, fraseVariacao } from '../regras/amazon_painel.js'
import { historicoAmazon, lerEGravarAmazon } from '../servicos/amazon.js'
import { formatarData } from '../regras/datas.js'
import { uso } from '../servicos/uso.js'

/**
 * "Seu livro na Amazon": ranking de hoje, variação em 7 dias, nota e avaliações novas.
 * Dados públicos lidos uma vez por dia; na primeira vez, lê na hora. Sem link da Amazon, não aparece.
 */
export default function AmazonDoLivro({ livro }) {
  const asin = livro?.naAmazon === false ? null : extrairAsin(livro?.linkVenda)
  const [historico, setHistorico] = useState(null)
  const [estado, setEstado] = useState('carregando') // carregando | lendo | pronto | indisponivel

  useEffect(() => {
    if (!asin) return
    let vivo = true
    ;(async () => {
      let h = await historicoAmazon(asin)
      if (!vivo) return
      if (!h || h.length === 0) {
        setEstado('lendo')
        await lerEGravarAmazon(asin)
        h = await historicoAmazon(asin)
        if (!vivo) return
      }
      if (!h || h.length === 0) { setEstado('indisponivel'); return }
      setHistorico(h); setEstado('pronto')
    })()
    return () => { vivo = false }
  }, [asin])

  if (!asin || estado === 'indisponivel') return null
  const r = resumoAmazon(historico || [])
  if (!r) {
    return (
      <section className="bg-areia px-6 py-5 entra">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Seu livro na Amazon</p>
        <p className="text-[14px] text-apoio mt-2">{estado === 'lendo' ? 'Lendo a página do seu livro na Amazon…' : 'Carregando…'}</p>
      </section>
    )
  }
  const melhorou = r.variacao7 != null && r.variacao7 < 0
  const piorou = r.variacao7 != null && r.variacao7 > 0
  return (
    <section className="bg-areia px-5 py-5 sm:px-6 entra" aria-label="Seu livro na Amazon">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Seu livro na Amazon</p>
        <p className="text-[11px] text-mudo">lido {r.horasDesde < 1 ? 'agora' : r.horasDesde < 24 ? `há ${r.horasDesde}h` : `em ${formatarData(r.lidoEm)}`} · atualiza todo dia</p>
      </div>
      <div className="mt-4 grid grid-cols-2 sm:grid-cols-4 gap-5">
        <div>
          <p className="display text-[30px] leading-none">{r.ranking ? `nº ${r.ranking.toLocaleString('pt-BR')}` : '—'}</p>
          <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo mt-1">Ranking geral</p>
          <p className={'text-[12px] font-bold mt-1 ' + (melhorou ? 'text-verde' : piorou ? 'text-alerta' : 'text-apoio')}>{fraseVariacao(r.variacao7)}</p>
        </div>
        <div>
          <p className="display text-[30px] leading-none">{r.nota != null ? r.nota.toFixed(1).replace('.', ',') : '—'}</p>
          <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo mt-1">Nota</p>
        </div>
        <div>
          <p className="display text-[30px] leading-none">{r.avaliacoes != null ? r.avaliacoes.toLocaleString('pt-BR') : '—'}</p>
          <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo mt-1">Avaliações</p>
          {r.avaliacoesNovas7 > 0 && <p className="text-[12px] font-bold text-verde mt-1">+{r.avaliacoesNovas7} em 7 dias</p>}
        </div>
        <div>
          {r.categorias.length > 0 ? (
            <ul className="grid gap-1">
              {r.categorias.map((c) => <li key={c.lista} className="text-[12.5px]"><b>nº {c.posicao.toLocaleString('pt-BR')}</b> <span className="text-apoio">em {c.lista}</span></li>)}
            </ul>
          ) : <p className="text-[12.5px] text-apoio">Sem ranking por categoria hoje.</p>}
          <p className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo mt-1">Categorias</p>
        </div>
      </div>
      <p className="text-[12px] text-mudo mt-4">
        Quanto menor o número, mais o livro vende. Ranking e avaliações são públicos; vendas exatas só você vê no painel da KDP.{' '}
        <a href={livro.linkVenda} target="_blank" rel="noopener noreferrer" onClick={() => uso('amazon', { acao: 'abriu_pagina' })} className="underline underline-offset-4 hover:text-tinta">Abrir na Amazon ↗</a>
      </p>
    </section>
  )
}
