import { useEffect, useRef, useState } from 'react'
import { CORES } from '../marca.js'

/** As ações da semana como lombadas: feita = cheia na cor da fase; pendente = só o contorno.
 *  `sobreFase`: quando a estante fica em cima do painel da fase, a feita vira preta para não sumir. */
export default function EstanteDaSemana({ total, feitas, altura = 44, sobreFase = false }) {
  // a lombada que acabou de ser preenchida dá um pulo
  const anterior = useRef(feitas)
  const [pulando, setPulando] = useState(-1)
  useEffect(() => {
    if (feitas > anterior.current) { setPulando(feitas - 1); const t = setTimeout(() => setPulando(-1), 900); anterior.current = feitas; return () => clearTimeout(t) }
    anterior.current = feitas
  }, [feitas])
  if (!total) return null
  return (
    <span role="img" className="inline-flex items-end gap-1" style={{ height: altura }} aria-label={`${feitas} de ${total} ações feitas`}>
      {Array.from({ length: total }, (_, i) => {
        const feita = i < feitas
        const h = 70 + ((i * 23) % 30)
        return (
          <i
            key={i}
            className={'block relative transition-all duration-500 ' + (feita ? (sobreFase ? 'bg-tinta' : 'bg-fase') : 'bg-transparent') + (i === pulando ? ' lombada-pula' : '')}
            style={{ width: 14, height: `${h}%`, borderRadius: '3px 3px 0 0', boxShadow: feita ? undefined : `inset 0 0 0 2px ${CORES.tinta}`, opacity: feita ? 1 : .45 }}
          >
            <b className="absolute left-[3px] right-[3px] top-[7px] h-[2px]" style={{ background: feita ? 'rgba(255,255,255,.7)' : CORES.tinta }} />
            <b className="absolute left-[3px] right-[3px] top-[11px] h-[2px]" style={{ background: feita ? 'rgba(255,255,255,.7)' : CORES.tinta }} />
          </i>
        )
      })}
    </span>
  )
}
