// Atalho para o Gerador de Posts Magnéticos (GPT do ChatGPT).
// O agente faz 7 perguntas obrigatórias, nesta ordem e com estas opções
// (levantadas em teste real, 13/09/2026). Respondemos todas na primeira mensagem,
// no vocabulário dele, para ele ir direto ao "Posso gerar suas ideias?".

import { URL_GERADOR_POSTS } from '../marca.js'

export const OPCOES_GERADOR = {
  rede: ['Instagram', 'TikTok', 'LinkedIn', 'YouTube', 'Facebook'],
  habilidade: ['alto', 'médio', 'baixo'],
  audiencia: ['alta', 'média', 'baixa'],
  objetivo: ['vendas rápidas', 'autoridade', 'leads'],
  tom: ['inspirador', 'provocativo', 'educativo', 'humor'],
}

const FASE_GERADOR = { construcao: 'antes do lançamento', lancamento: 'lançamento', permanencia: 'pós-lançamento' }
const PESO_FAIXA = { 'não tenho': 0, 'até 1 mil': 1, '1 a 5 mil': 2, '5 a 20 mil': 3, '20 a 100 mil': 4, 'mais de 100 mil': 5 }

/** alta / média / baixa a partir da maior faixa de audiência. */
export function classificarAudiencia(autor) {
  const maior = Math.max(0, ...Object.values(autor.audiencia || {}).map((v) => PESO_FAIXA[v] ?? 0))
  return maior >= 4 ? 'alta' : maior >= 2 ? 'média' : 'baixa'
}


/** Objetivo dos posts no vocabulário do Gerador, a partir do objetivo do cadastro. */
export function objetivoPadrao(autor) {
  if (autor.objetivo === 'construir_autoridade' || autor.objetivo === 'conseguir_palestras') return 'autoridade'
  if (autor.temListaEmail === false) return 'leads'
  return 'vendas rápidas'
}

/**
 * Padrões: audiência e objetivo vêm do cadastro. Rede, habilidade e tom NÃO são
 * deduzidos (decisão do cliente, 13/09): o autor responde na hora, toda vez.
 */
export function padroesGerador(autor) {
  return { rede: '', habilidade: '', audiencia: classificarAudiencia(autor), objetivo: objetivoPadrao(autor), tom: '' }
}

/** As 3 perguntas que o autor responde na hora. */
export const PERGUNTAS_NA_HORA = ['rede', 'habilidade', 'tom']
export function briefingCompleto(escolhas) {
  return PERGUNTAS_NA_HORA.every((k) => Boolean(escolhas[k]))
}

/** Mensagem inicial: as 7 respostas na ordem das perguntas do agente + contexto do livro. */
export function montarBriefingGerador(autor, fase, escolhas = {}, { acaoDaSemana } = {}) {
  const e = { ...padroesGerador(autor), ...escolhas }
  const l = autor.livro
  const linhas = [
    'Oi! Sou aluno do Método The Book Business e vim pelo LOMBADA. Já respondo as suas 7 perguntas, na ordem:',
    `1. Fase: ${FASE_GERADOR[fase] || 'antes do lançamento'}.`,
    `2. Gênero principal: ${l.genero || 'não defini'}${l.subNicho ? ` (${l.subNicho})` : ''}.`,
    `3. Rede social: ${e.rede}.`,
    `4. Nível de habilidade em redes sociais: ${e.habilidade}.`,
    `5. Tamanho/engajamento da audiência: ${e.audiencia}.`,
    `6. Objetivo principal dos posts: ${e.objetivo}.`,
    `7. Tom: ${e.tom}.`,
    '',
    'Contexto do livro para personalizar as ideias:',
    `Título: "${l.titulo}"${l.subtitulo ? `: ${l.subtitulo}` : ''}. Público-alvo: ${l.publicoAlvo || 'não defini'}.${l.promessa ? ` Promessa: ${l.promessa}` : ''}${l.trecho ? ` Um trecho: "${l.trecho}"` : ''}`,
    `Autor: ${autor.nome}${autor.profissao ? `, ${autor.profissao}` : ''}${autor.cidade ? `, ${autor.cidade}` : ''}.`,
  ]
  if (acaoDaSemana) linhas.push(`Ação da minha semana no LOMBADA: "${acaoDaSemana}". Priorize ideias que sirvam para ela.`)
  linhas.push('Todas as 7 respostas estão acima. Pode gerar as minhas ideias de posts.')
  return linhas.join('\n')
}

/** URL do GPT com a mensagem pré-preenchida (o ChatGPT envia a mensagem sozinho). */
export function urlGerador(briefing) {
  return `${URL_GERADOR_POSTS}?q=${encodeURIComponent(briefing)}`
}
