// Acesso do autor ao LOMBADA acompanha o acesso ao Método The Book Business.
// No protótipo, `autor.acesso` é controlado no admin. Em produção, vem da
// Hotmart no login: aluno ativo (students) e compra sem reembolso/chargeback (sales).

export const STATUS_ACESSO = {
  ATIVO: 'ativo',
  VENCIDO: 'vencido',        // prazo de acesso ao Método The Book Business terminou
  REEMBOLSADO: 'reembolsado', // pediu reembolso ou chargeback
  SUSPENSO: 'suspenso',       // bloqueio manual pelo admin
}

export const MOTIVO_BLOQUEIO = {
  [STATUS_ACESSO.VENCIDO]: 'Seu acesso ao Método The Book Business venceu.',
  [STATUS_ACESSO.REEMBOLSADO]: 'Sua compra do Método The Book Business foi reembolsada.',
  [STATUS_ACESSO.SUSPENSO]: 'Seu acesso foi suspenso pela equipe.',
}

/**
 * Verifica o acesso. Sem `acesso` no cadastro, considera ativo (compatível com dados antigos).
 * `ate` (data) vence o acesso automaticamente quando passa.
 * @returns {{ liberado: boolean, status: string, motivo?: string, ate?: string }}
 */
export function verificarAcesso(autor, hoje = new Date()) {
  const a = autor.acesso || { status: STATUS_ACESSO.ATIVO }
  let status = a.status || STATUS_ACESSO.ATIVO
  if (status === STATUS_ACESSO.ATIVO && a.ate && new Date(a.ate) < hoje) status = STATUS_ACESSO.VENCIDO
  const liberado = status === STATUS_ACESSO.ATIVO
  return { liberado, status, motivo: liberado ? undefined : MOTIVO_BLOQUEIO[status], ate: a.ate }
}
