/** Referência de aula para uma ação: resolve o título oficial e o link direto. */
const M = (modulo, chave) => {
  const a = AULAS[chave]
  if (!a) throw new Error(`Aula não mapeada: ${chave}`)
  return { modulo: a.modulo, nome: a.nome, pageId: a.pageId, url: urlAula(a.pageId) }
}

