// Memória do plano: o que o autor já fez e o que rejeitou moldam as próximas semanas.
// Duas regras, cada uma numa função:
//   - temas evitados: 2 rejeições no mesmo tema tiram as outras ações daquele tema;
//   - encadeamento: uma ação que continua algo já feito ganha contexto e prioridade.

export const NOME_TEMA = {
  imprensa: 'imprensa', influenciadores: 'influenciadores', evento: 'evento de lançamento', amazon: 'Amazon',
  lista: 'lista de e-mail', redes: 'redes sociais', grupo: 'grupo de lançamento', avaliacoes: 'avaliações',
  palestras: 'palestras', blog: 'blog', datas: 'datas comemorativas', patrocinio: 'patrocínio', endosso: 'endossos',
  prevenda: 'pré-venda', planejamento: 'planejamento',
}

export const REJEICOES_PARA_EVITAR_TEMA = 2

/** Temas com REJEICOES_PARA_EVITAR_TEMA ou mais rejeições, menos os que o autor pediu de volta. */
export function temasEvitados(autor, acoes) {
  const contagem = {}
  for (const r of autor.rejeitadas || []) {
    const tema = acoes.find((a) => a.id === r.acaoId)?.tema
    if (tema) contagem[tema] = (contagem[tema] || 0) + 1
  }
  const reativados = new Set(autor.temasReativados || [])
  return Object.entries(contagem)
    .filter(([tema, n]) => n >= REJEICOES_PARA_EVITAR_TEMA && !reativados.has(tema))
    .map(([tema]) => tema)
}

/** Verdadeiro se a ação pertence a um tema que o autor evitou. */
export function evitadaPorTema(acao, autor, acoes) {
  return Boolean(acao.tema) && temasEvitados(autor, acoes).includes(acao.tema)
}

/** Frases para a tela: "Você marcou 2 ações de imprensa como não se aplica..." */
export function explicarTemasEvitados(autor, acoes) {
  return temasEvitados(autor, acoes).map((tema) => {
    const n = (autor.rejeitadas || []).filter((r) => acoes.find((a) => a.id === r.acaoId)?.tema === tema).length
    return { tema, nome: NOME_TEMA[tema] || tema, rejeitadas: n }
  })
}

/**
 * Se a ação continua algo que o autor já concluiu, devolve a ação anterior e a data.
 * Escolhe a conclusão mais recente entre as antecessoras. Senão, null.
 */
export function encadear(acao, autor, acoes) {
  const antecessoras = acao.continuaDe || []
  if (antecessoras.length === 0) return null
  let melhor = null
  for (const c of autor.concluidas || []) {
    if (!antecessoras.includes(c.acaoId)) continue
    if (!melhor || new Date(c.data) > new Date(melhor.data)) melhor = c
  }
  if (!melhor) return null
  const anterior = acoes.find((a) => a.id === melhor.acaoId)
  return anterior ? { anterior, data: melhor.data } : null
}

/** Verdadeiro se a ação dá sequência a algo já feito (usado para priorizar no plano). */
export function continuaAlgoFeito(acao, autor) {
  const feitos = new Set((autor.concluidas || []).map((c) => c.acaoId))
  return (acao.continuaDe || []).some((id) => feitos.has(id))
}
