// Camada de nuvem: Supabase do Miolo, só por funções (RPC). Sem Supabase Auth para autores:
// a sessão é um token gerado ao cadastrar ou ao entrar com e-mail + código.
// Se as variáveis não existirem no build, o app roda no modo local (protótipo em memória).
import { createClient } from '@supabase/supabase-js'

const URL = import.meta.env.VITE_SUPABASE_URL
const CHAVE = import.meta.env.VITE_SUPABASE_ANON_KEY
const FORCAR_LOCAL = typeof window !== 'undefined' && new URLSearchParams(window.location.search).has('local')
export const NUVEM_ATIVA = Boolean(URL && CHAVE) && !FORCAR_LOCAL
export const supabase = NUVEM_ATIVA ? createClient(URL, CHAVE, { auth: { persistSession: true, storageKey: 'lombada.equipe', autoRefreshToken: true } }) : null

const CHAVE_SESSAO = 'lombada.sessao'
export function lerSessao() { try { return window.localStorage.getItem(CHAVE_SESSAO) || null } catch { return null } }
export function gravarSessao(token) { try { window.localStorage.setItem(CHAVE_SESSAO, token) } catch { /* nada */ } }
export function apagarSessao() { try { window.localStorage.removeItem(CHAVE_SESSAO) } catch { /* nada */ } }

const MENSAGENS = {
  ja_cadastrado: 'Este e-mail já tem cadastro. Entre com o seu código de acesso.',
  email_invalido: 'Confira o e-mail.',
  nao_encontrado: 'Não achamos cadastro com este e-mail.',
  codigo_invalido: 'Código não confere. Esqueceu? Peça um novo para a Dezza.',
  codigo_curto: 'O código tem 6 números.',
  codigo_fraco: 'Escolha um código menos óbvio.',
  sessao_invalida: 'Sua sessão terminou. Entre de novo.',
  somente_equipe: 'Só a equipe pode fazer isso.',
  livro_nao_encontrado: 'Este livro não está na vitrine.',
  texto_curto: 'Escreva um pouco mais.',
}

export class ErroNuvem extends Error {
  constructor(codigo, original) { super(MENSAGENS[codigo] || original?.message || 'Algo deu errado. Tente de novo.'); this.codigo = codigo }
}

async function rpc(nome, args = {}) {
  const { data, error } = await supabase.rpc(nome, args)
  if (error) {
    const codigo = Object.keys(MENSAGENS).find((k) => (error.message || '').includes(k)) || 'erro'
    throw new ErroNuvem(codigo, error)
  }
  return data
}

export const nuvem = {
  cadastrar: (dados) => rpc('lombada_cadastrar', { p_dados: dados }),
  entrar: (email, codigo) => rpc('lombada_entrar', { p_email: email, p_codigo: codigo }),
  meu: (token) => rpc('lombada_meu', { p_token: token }),
  salvar: (token, dados) => rpc('lombada_salvar', { p_token: token, p_dados: dados }),
  sair: (token) => rpc('lombada_sair', { p_token: token }),
  vitrine: () => rpc('lombada_vitrine'),
  captarLeitor: (slug, nome, email) => rpc('lombada_captar_leitor', { p_slug: slug, p_nome: nome, p_email: email }),
  leitores: (token) => rpc('lombada_leitores', { p_token: token }),
  sugerir: (token, texto) => rpc('lombada_sugerir', { p_token: token, p_texto: texto }),
  minhasSugestoes: (token) => rpc('lombada_minhas_sugestoes', { p_token: token }),
  catalogo: () => rpc('lombada_catalogo_ler'),
  configPublica: () => rpc('lombada_config_publica'),
  // equipe (precisa de login do Miolo)
  gerarCodigo: (autorId) => rpc('lombada_gerar_codigo', { p_autor_id: autorId }),
  codigoAtual: (autorId) => rpc('lombada_codigo_atual', { p_autor_id: autorId }),
  definirCodigo: (autorId, codigo) => rpc('lombada_definir_codigo', { p_autor_id: autorId, p_codigo: codigo }),
  alterarEmail: (autorId, email) => rpc('lombada_alterar_email', { p_autor_id: autorId, p_email: email }),
  trocarCodigo: (token, atual, novo) => rpc('lombada_trocar_codigo', { p_token: token, p_atual: atual, p_novo: novo }),
  /** LGPD: apaga a própria conta (anonimização irreversível). */
  apagarConta: (token) => rpc('lombada_apagar_conta', { p_token: token }),
  /** Grava um lote de eventos de uso (medição). keepalive: sai mesmo se a aba fechar. */
  eventos: (token, lote) => fetch(`${URL}/rest/v1/rpc/lombada_eventos_gravar`, { method: 'POST', keepalive: true, headers: { 'Content-Type': 'application/json', apikey: CHAVE, Authorization: `Bearer ${CHAVE}` }, body: JSON.stringify({ p_token: token, p_eventos: lote }) }),
  /** Resumo de uso para o Admin (equipe). */
  usoResumo: (dias = 28) => rpc('lombada_uso_resumo', { p_dias: dias }),
  /** Sobe capa/foto (data URL já otimizado) para o Storage; devolve a URL pública. */
  enviarImagem: async (token, tipo, dataUrl) => {
    const res = await fetch(`${URL}/functions/v1/lombada-upload`, { method: 'POST', headers: { 'Content-Type': 'application/json', apikey: CHAVE, Authorization: `Bearer ${CHAVE}` }, body: JSON.stringify({ token, tipo, dataUrl }) })
    const d = await res.json().catch(() => ({}))
    if (!res.ok || !d.url) throw new ErroNuvem(d.erro || 'upload', new Error(d.erro || 'Não consegui enviar a imagem.'))
    return d.url
  },
  /** Chama uma Edge Function da operação com o login da equipe (Admin). */
  operacao: async (nome, sessao, params = {}) => {
    const q = new URLSearchParams(params).toString()
    const res = await fetch(`${URL}/functions/v1/${nome}${q ? `?${q}` : ''}`, { method: 'POST', headers: { 'Content-Type': 'application/json', apikey: CHAVE, Authorization: `Bearer ${sessao.access_token}` }, body: '{}' })
    const d = await res.json().catch(() => ({}))
    if (!res.ok) throw new Error(d.erro || `Falhou (${res.status})`)
    return d
  },
}

/** Garante a forma mínima de um autor vindo do banco: listas e objetos que as regras esperam. */
export { normalizarAutor } from '../regras/autor.js'
