import { useState, useEffect, useRef, lazy, Suspense } from 'react'
import { BrowserRouter, Routes, Route, Link } from 'react-router-dom'
import { AUTORES, ACOES, MODELOS, OPORTUNIDADES, LIVROS_EXTRA_VITRINE, LEITORES } from './dados/exemplo.js'
import { assinaturaCatalogo } from './regras/catalogo.js'
const VERSAO_CATALOGO = assinaturaCatalogo(ACOES, MODELOS, OPORTUNIDADES)
import { classificarFase } from './regras/fase.js'
import { concluidaNestaSemana } from './regras/plano.js'
import { escolherModelos } from './regras/modelos.js'
import { montarVitrine, slugify } from './regras/vitrine.js'
import Wordmark from './componentes/Wordmark.jsx'
import SeletorAutor from './componentes/SeletorAutor.jsx'
import Celebracao from './componentes/Celebracao.jsx'
import PlanoDaSemana from './telas/PlanoDaSemana.jsx'
import MaterialDeApoio from './telas/MaterialDeApoio.jsx'
import CadastroLivro from './telas/CadastroLivro.jsx'
import Historico from './telas/Historico.jsx'
import Oportunidades from './telas/Oportunidades.jsx'
import Vitrine from './telas/Vitrine.jsx'
import PaginaLivro from './telas/PaginaLivro.jsx'
import MeusLeitores from './telas/MeusLeitores.jsx'
const Admin = lazy(() => import('./telas/Admin.jsx'))
import Aulas from './telas/Aulas.jsx'
import Comecar from './telas/Comecar.jsx'
const EntrarVersoes = lazy(() => import('./telas/EntrarVersoes.jsx'))
const Legal = lazy(() => import('./telas/Legal.jsx'))
import { uso } from './servicos/uso.js'
import { normalizarAutor } from './regras/autor.js'
import { sincronizarLivros, trocarFoco, adicionarLivro, temVaga, slugsDoAutor, livroEmFoco } from './regras/livros.js'
import AcessoBloqueado from './telas/AcessoBloqueado.jsx'
import CadastroEmAnalise from './telas/CadastroEmAnalise.jsx'
import Sugestoes from './telas/Sugestoes.jsx'
import PerfilAutor from './telas/PerfilAutor.jsx'
import { cadastroLiberado } from './regras/aprovacao.js'
import { verificarAcesso } from './regras/acesso.js'
import { lerUI, gravarUI } from './regras/persistencia.js'
import { carregarEstado, salvarEstado, apagarEstado, exportarEstado, validarImportacao } from './regras/persistencia.js'
import { NUVEM_ATIVA } from './servicos/nuvem.js'
import AppNuvem from './AppNuvem.jsx'

export default function App() {
  // Com Supabase configurado no build, o app inteiro roda na nuvem (autores reais, equipe no Admin).
  if (NUVEM_ATIVA) return <AppNuvem />
  return <AppLocal />
}

/** Protótipo em memória: autores de exemplo e tudo salvo no navegador. */
function AppLocal() {
  // Estado: começa do arquivo de exemplo; se houver algo salvo no navegador, usa o salvo.
  const salvo = useRef(carregarEstado()).current
  // Autores salvos ganham os campos novos dos exemplos (ex.: conquistas) sem perder o que o autor editou.
  const [autores, setAutores] = useState(() => (salvo?.autores ?? AUTORES).map((a) => {
    const f = AUTORES.find((x) => x.id === a.id)
    return f ? { ...f, ...a, livro: { ...f.livro, ...(a.livro || {}) } } : a
  }))
  const [leitores, setLeitores] = useState(salvo?.leitores ?? LEITORES)
  // Conteúdo editável pelo administrador. Se o catálogo do código é mais novo que o salvo, o do código vence.
  const catalogoSalvoVale = salvo?.versaoCatalogo === VERSAO_CATALOGO
  const [acoes, setAcoes] = useState(catalogoSalvoVale ? salvo.acoes : ACOES)
  const [modelos, setModelos] = useState(catalogoSalvoVale ? salvo.modelos : MODELOS)
  const [oportunidades, setOportunidades] = useState(catalogoSalvoVale ? salvo.oportunidades : OPORTUNIDADES)
  const [sugestoes, setSugestoes] = useState(salvo?.sugestoes ?? [])
  const [salvoEm, setSalvoEm] = useState(salvo?.salvoEm ?? null)

  // Salva no navegador a cada mudança (substituir por banco depois).
  useEffect(() => {
    if (salvarEstado({ autores, leitores, acoes, modelos, oportunidades, sugestoes, versaoCatalogo: VERSAO_CATALOGO })) setSalvoEm(new Date().toISOString())
  }, [autores, leitores, acoes, modelos, oportunidades, sugestoes])

  const dados = {
    salvoEm,
    exportar: () => exportarEstado({ autores, leitores, acoes, modelos, oportunidades, sugestoes, versaoCatalogo: VERSAO_CATALOGO }),
    importar: (texto) => {
      const e = validarImportacao(texto)
      setAutores(e.autores); setLeitores(e.leitores); setAcoes(e.acoes); setModelos(e.modelos); setOportunidades(e.oportunidades); setSugestoes(e.sugestoes || [])
    },
    redefinir: () => {
      apagarEstado()
      setAutores(AUTORES); setLeitores(LEITORES); setAcoes(ACOES); setModelos(MODELOS); setOportunidades(OPORTUNIDADES)
    },
  }

  const upsert = (setter) => (item) => setter((lista) => (lista.some((x) => x.id === item.id) ? lista.map((x) => (x.id === item.id ? item : x)) : [...lista, item]))
  const remover = (setter) => (id) => setter((lista) => lista.filter((x) => x.id !== id))
  const enviarSugestao = (autorId, texto) => setSugestoes((l) => [...l, { id: `s${Date.now()}`, autorId, texto, data: new Date().toISOString(), status: 'recebida' }])
  const [codigosLocais, setCodigosLocais] = useState({})
  const admin = {
    sugestoes,
    codigos: codigosLocais,
    gerarCodigo: async (autorId) => { const c = String(Math.floor(Math.random() * 1e6)).padStart(6, '0'); setCodigosLocais((m) => ({ ...m, [autorId]: c })); return c },
    alterarVagas: (autorId, delta) => setAutores((lista) => lista.map((a) => (a.id === autorId ? { ...a, vagasLivros: Math.max(1, (Number(a.vagasLivros) || 1) + delta) } : a))),
    definirCodigo: async (autorId, c) => { if (c.length !== 6) throw new Error('O código tem 6 números.'); setCodigosLocais((m) => ({ ...m, [autorId]: c })); return c },
    alterarEmail: async (autorId, e) => { setAutores((l) => l.map((a) => (a.id === autorId ? { ...a, email: e } : a))) },
    marcarSugestaoLida: (id) => setSugestoes((l) => l.map((s) => (s.id === id ? { ...s, status: 'lida' } : s))),
    salvarAcao: upsert(setAcoes),
    excluirAcao: remover(setAcoes),
    salvarModelo: upsert(setModelos),
    // Excluir um modelo base leva junto as variantes por gênero e desvincula das ações
    excluirModelo: (id) => {
      setModelos((lista) => lista.filter((m) => m.id !== id && m.variaDe !== id))
      setAcoes((lista) => lista.map((a) => ({ ...a, modeloIds: a.modeloIds.filter((m) => m !== id) })))
    },
    salvarOportunidade: upsert(setOportunidades),
    excluirOportunidade: remover(setOportunidades),
    alterarCadastro: (autorId, status, observacao) => setAutores((lista) => lista.map((a) => (a.id === autorId ? { ...a, cadastro: { ...(a.cadastro || {}), status, observacao: status === 'ajustar' ? observacao : a.cadastro?.observacao, revisadoEm: new Date().toISOString() } } : a))),
    alterarAcesso: (autorId, status) => setAutores((lista) => lista.map((a) => (a.id === autorId ? { ...a, acesso: { ...(a.acesso || {}), status, ate: status === 'ativo' ? null : a.acesso?.ate } } : a))),
  }

  const livrosVitrine = montarVitrine(autores, LIVROS_EXTRA_VITRINE)

  function capturarLeitor(leitor) {
    setLeitores((lista) => {
      // Mesmo e-mail no mesmo livro não duplica.
      if (lista.some((l) => l.slug === leitor.slug && l.email === leitor.email)) return lista
      return [...lista, leitor]
    })
  }

  return (
    <BrowserRouter basename={import.meta.env.BASE_URL.replace(/\/$/, '')}>
      <Routes>
        {/* Público, sem login */}
        <Route path="/comecar" element={<Comecar />} />
        <Route path="/versoes-entrar" element={<Suspense fallback={null}><EntrarVersoes /></Suspense>} />
        <Route path="/termos" element={<Suspense fallback={null}><Legal tipo="termos" /></Suspense>} />
        <Route path="/privacidade" element={<Suspense fallback={null}><Legal tipo="privacidade" /></Suspense>} />
        <Route path="/vitrine" element={<Vitrine livros={livrosVitrine} />} />
        <Route path="/livro/:slug" element={<PaginaLivro livros={livrosVitrine} onCapturarLeitor={capturarLeitor} />} />
        {/* Administrador (protótipo: sem login) */}
        <Route path="/admin" element={<Suspense fallback={null}><Admin autores={autores} leitores={leitores} acoes={acoes} modelos={modelos} oportunidades={oportunidades} dados={dados} {...admin} /></Suspense>} />
        {/* Área logada (protótipo: sem autenticação, seletor de autor no topo) */}
        <Route path="/*" element={<AreaLogada autores={autores} setAutores={setAutores} leitores={leitores} acoes={acoes} modelos={modelos} oportunidades={oportunidades} sugestoes={sugestoes} onEnviarSugestao={enviarSugestao} />} />
      </Routes>
    </BrowserRouter>
  )
}

export function AreaLogada({ autores, setAutores, leitores, acoes, modelos, oportunidades, sugestoes, onEnviarSugestao, nuvem = false, onSair, onTrocarCodigo, onApagarConta, urlCheckoutLivro = '' }) {
  const [autorAtualId, setAutorAtualId] = useState(() => { try { return window.localStorage.getItem('lombada.autorAtual') || autores[0].id } catch { return autores[0].id } })
  useEffect(() => { try { window.localStorage.setItem('lombada.autorAtual', autorAtualId) } catch { /* nada */ } }, [autorAtualId])
  // Modo aluno (vindo de /comecar): esconde os autores de exemplo e abre direto no cadastro.
  const [modoAluno, setModoAluno] = useState(() => Boolean(lerUI().modoAluno))
  const [tela, setTela] = useState(() => (lerUI().abrirCadastro ? { nome: 'cadastro' } : { nome: 'plano' }))
  useEffect(() => { if (lerUI().abrirCadastro) gravarUI({ abrirCadastro: false }) }, [])
  // cada tela aberta é um evento de uso (com a ação, quando houver)
  useEffect(() => { uso('tela', { tela: tela.nome, ...(tela.acaoId ? { acaoId: tela.acaoId } : {}) }) }, [tela.nome, tela.acaoId])

  function sairDoModoAluno() { gravarUI({ modoAluno: false }); setModoAluno(false); setTela({ nome: 'plano' }) }

  const hoje = new Date()
  const fases = Object.fromEntries(autores.map((a) => [a.id, classificarFase(a.livro, hoje)]))
  // o autor que as telas leem é sempre a projeção do livro em foco (cadastros antigos são migrados aqui)
  const autor = normalizarAutor(autores.find((a) => a.id === autorAtualId) ?? autores[0])

  // toda mudança passa pela projeção do livro em foco e volta sincronizada para livros[]
  const atualizarAutor = (autorId, fn) => setAutores((lista) => lista.map((a) => (a.id === autorId ? normalizarAutor(sincronizarLivros(fn(normalizarAutor(a)))) : a)))

  function concluirAcao(autorId, acaoId) {
    uso('concluiu', { acaoId })
    atualizarAutor(autorId, (a) => ({ ...a, concluidas: [...a.concluidas, { acaoId, data: new Date().toISOString() }] }))
  }

  function desfazerConclusao(autorId, acaoId) {
    uso('desfez', { acaoId })
    // Remove só a conclusão mais recente daquela ação.
    atualizarAutor(autorId, (a) => {
      const idx = [...a.concluidas].reverse().findIndex((c) => c.acaoId === acaoId)
      if (idx === -1) return a
      const real = a.concluidas.length - 1 - idx
      return { ...a, concluidas: a.concluidas.filter((_, i) => i !== real) }
    })
  }

  function rejeitarAcao(autorId, acaoId) {
    uso('rejeitou', { acaoId })
    atualizarAutor(autorId, (a) => ({ ...a, rejeitadas: [...a.rejeitadas, { acaoId, data: new Date().toISOString() }] }))
  }

  function reativarTema(autorId, tema) {
    atualizarAutor(autorId, (a) => ({ ...a, temasReativados: [...new Set([...(a.temasReativados || []), tema])] }))
  }

  function desfazerRejeicao(autorId, acaoId) {
    atualizarAutor(autorId, (a) => ({ ...a, rejeitadas: a.rejeitadas.filter((r) => r.acaoId !== acaoId) }))
  }

  const [celebracao, setCelebracao] = useState(null)
  function registrarConquista(autorId, conquista) {
    if (!conquista) return
    uso('conquista')
    atualizarAutor(autorId, (a) => ({ ...a, conquistas: [...(a.conquistas || []), conquista] }))
    setCelebracao(conquista.texto)
  }

  function registrarCheckin(autorId, texto) {
    uso('checkin')
    atualizarAutor(autorId, (a) => ({ ...a, checkins: [...(a.checkins || []), { data: new Date().toISOString(), texto }] }))
  }

  function definirAcoesPorSemana(autorId, n) {
    uso('acoes_semana', { n })
    atualizarAutor(autorId, (a) => ({ ...a, acoesPorSemana: n }))
  }

  function dispensarCheckin(autorId) {
    atualizarAutor(autorId, (a) => ({ ...a, checkinsDispensados: [...(a.checkinsDispensados || []), new Date().toISOString()] }))
  }

  function salvarCadastro(autorBruto) {
    // autor novo chega sem as listas (concluidas, checkins...): normaliza antes de entrar na tela;
    // edição grava o livro em foco de volta em livros[]
    const autorSalvo = normalizarAutor(sincronizarLivros(autorBruto))
    setAutores((lista) => {
      const existe = lista.some((a) => a.id === autorSalvo.id)
      return existe ? lista.map((a) => (a.id === autorSalvo.id ? autorSalvo : a)) : [...lista, autorSalvo]
    })
    setAutorAtualId(autorSalvo.id)
    setTela({ nome: 'plano' }) // classificação de fase acontece no render (classificarFase)
  }

  /** Livro adicional: entra em foco na hora. Só com vaga (a equipe libera; a Hotmart cobra). */
  function salvarNovoLivro(dadosDoCadastro) {
    setAutores((lista) => lista.map((a) => (a.id === autor.id ? (adicionarLivro(a, dadosDoCadastro.livro) || a) : a)))
    setTela({ nome: 'plano' })
  }
  function focarLivro(livroId) {
    uso('trocou_livro', { livroId })
    setAutores((lista) => lista.map((a) => (a.id === autor.id ? trocarFoco(a, livroId) : a)))
    setTela({ nome: 'plano' })
  }

  function selecionarAutor(id) {
    setAutorAtualId(id)
    setTela({ nome: 'plano' })
  }

  // Acesso ao Método The Book Business: vencido, reembolsado ou suspenso não entra.
  const acesso = verificarAcesso(autor, hoje)
  if (!acesso.liberado) {
    return <AcessoBloqueado autor={autor} acesso={acesso} onTrocarAutor={modoAluno || nuvem ? null : () => selecionarAutor(autores.find((a) => verificarAcesso(a, hoje).liberado)?.id ?? autores[0].id)} onSair={nuvem ? onSair : null} />
  }

  // Cadastro em análise: só o cadastro (para revisar) fica acessível até o time liberar.
  if (!cadastroLiberado(autor) && tela.nome !== 'cadastro') {
    return <CadastroEmAnalise autor={autor} onEditar={() => setTela({ nome: 'cadastro', editar: true })} onTrocarAutor={modoAluno || nuvem ? null : () => selecionarAutor(autores.find((a) => cadastroLiberado(a) && verificarAcesso(a, hoje).liberado)?.id ?? autores[0].id)} onSair={nuvem ? onSair : null} />
  }

  const irPara = (nome) => () => setTela({ nome })
  const linkTopo = (nome, rotulo) => (
    <button
      onClick={irPara(nome)}
      className={'relative text-[13px] font-bold pb-1 transition-colors hover:text-tinta ' + (tela.nome === nome ? 'text-tinta' : 'text-mudo')}
    >
      {rotulo}
      {tela.nome === nome && <i className="absolute left-0 right-0 -bottom-[2px] h-[4px] bg-ambar" style={{ clipPath: 'polygon(0 0, 100% 0, 88% 100%, 0 100%)' }} />}
    </button>
  )

  return (
    <div className="min-h-screen">
      <a href="#conteudo" className="pular btn-preto">Ir para o conteúdo</a>
      {celebracao && <Celebracao texto={celebracao} onFechar={() => setCelebracao(null)} />}
      <div className="border-b-2 border-tinta">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 pt-4 pb-3 grid gap-3">
          {/* linha 1: marca + ações */}
          <div className="flex items-center justify-between gap-3">
            <Wordmark tamanho={22} />
            <div className="flex items-center gap-3">
              {(autor.livros || []).length > 1 && (
                <select aria-label="Livro em foco" value={autor.livroFoco} onChange={(e) => focarLivro(e.target.value)} className="max-w-[180px] sm:max-w-[240px] truncate bg-creme border-2 border-tinta text-[12.5px] font-bold px-2 py-1.5 focus:outline-none">
                  {autor.livros.map((l) => <option key={l.id} value={l.id}>{l.titulo || 'Livro sem título'}</option>)}
                </select>
              )}
              {autor.aparecerNaVitrine !== false && <Link to={`/livro/${autor.livro.slug || slugify(autor.livro.titulo)}`} target="_blank" className="btn-linha hidden sm:inline">Minha página ↗</Link>}
              <button onClick={() => setTela({ nome: 'perfil' })} className="btn-linha hidden sm:inline">Perfil do autor</button>
              {nuvem
                ? <button onClick={onSair} className="btn-linha">Sair</button>
                : <button onClick={() => setTela({ nome: 'cadastro' })} className="btn-preto !py-1.5 !text-[12px]">Cadastrar livro</button>}
            </div>
          </div>
          {/* linha 2: navegação rolável no celular */}
          <nav className="flex flex-wrap items-center gap-x-4 gap-y-1.5 sm:gap-5 pb-1">
            {linkTopo('plano', 'Plano')}
            {linkTopo('oportunidades', 'Oportunidades')}
            {linkTopo('historico', 'Histórico')}
            {linkTopo('aulas', 'Aulas')}
            <button onClick={() => setTela({ nome: 'perfil' })} className="text-[13px] font-bold pb-1 text-mudo hover:text-tinta sm:hidden">Perfil</button>
            {autor.aparecerNaVitrine !== false && <Link to={`/livro/${autor.livro.slug || slugify(autor.livro.titulo)}`} target="_blank" className="text-[13px] font-bold pb-1 text-mudo hover:text-tinta sm:hidden">Minha página ↗</Link>}
            <Link to="/vitrine" target="_blank" className="text-[13px] font-bold pb-1 text-mudo hover:text-tinta">Vitrine ↗</Link>
            <Link to="/admin" className="text-[13px] font-bold pb-1 text-mudo hover:text-tinta">Admin ↗</Link>
          </nav>
        </div>
        {nuvem ? null : modoAluno ? (
          <div className="max-w-4xl mx-auto px-4 sm:px-6 pb-3 flex items-center justify-between gap-3 text-[12px]">
            <span className="text-mudo font-semibold">Modo aluno: só o seu cadastro aparece.</span>
            <button onClick={sairDoModoAluno} className="btn-linha !text-[12px] underline underline-offset-4">ver autores de exemplo</button>
          </div>
        ) : (
          <div className="max-w-4xl mx-auto px-4 sm:px-6 pb-3 flex items-center justify-between gap-3">
            <SeletorAutor autores={autores} fases={fases} autorAtualId={autor.id} onSelecionar={selecionarAutor} />
            <Link to="/comecar" className="text-[12px] font-semibold text-mudo hover:text-tinta underline underline-offset-4 shrink-0 text-right leading-tight">autor novo<span className="hidden sm:inline">: como entra</span></Link>
          </div>
        )}
      </div>

      <main id="conteudo" className="max-w-4xl mx-auto px-4 sm:px-6 py-8 sm:py-10">
        {tela.nome === 'perfil' ? (
          <PerfilAutor autor={autor} fase={fases[autor.id]} leitores={leitores} sugestoes={sugestoes} onEditar={() => setTela({ nome: 'cadastro', editar: true })} onLeitores={irPara('leitores')} onSugestoes={irPara('sugestoes')} onVoltar={irPara('plano')} onTrocarCodigo={onTrocarCodigo} leitoresDoAutor={leitores.filter((l) => slugsDoAutor(autor).includes(l.slug))} onNovoLivro={() => setTela({ nome: 'novoLivro' })} onFocarLivro={focarLivro} urlCheckoutLivro={urlCheckoutLivro} onApagarConta={onApagarConta || (() => { setAutores((lista) => lista.filter((a) => a.id !== autor.id)); setTela({ nome: 'plano' }) })} />
        ) : tela.nome === 'sugestoes' ? (
          <Sugestoes autor={autor} sugestoes={sugestoes} onEnviar={onEnviarSugestao} onVoltar={irPara('perfil')} />
        ) : tela.nome === 'aulas' ? (
          <Aulas acoes={acoes} onVoltar={irPara('plano')} />
        ) : tela.nome === 'leitores' ? (
          <MeusLeitores autor={autor} leitores={leitores} onVoltar={irPara('perfil')} />
        ) : tela.nome === 'oportunidades' ? (
          <Oportunidades autor={autor} oportunidades={oportunidades} onVoltar={irPara('plano')} />
        ) : tela.nome === 'historico' ? (
          <Historico autor={autor} acoes={acoes} onVoltar={irPara('plano')} />
        ) : tela.nome === 'novoLivro' ? (
          <CadastroLivro key="novo-livro" soLivro inicial={null} onSalvar={salvarNovoLivro} onCancelar={irPara('perfil')} />
        ) : tela.nome === 'cadastro' ? (
          <CadastroLivro
            key={tela.editar ? autor.id : 'novo'}
            inicial={tela.editar ? autor : null}
            etapaInicial={tela.etapa || 0}
            onSalvar={salvarCadastro}
            onCancelar={irPara('plano')}
          />
        ) : tela.nome === 'material' ? (
          (() => {
            const acao = acoes.find((a) => a.id === tela.acaoId)
            if (!acao) { setTela({ nome: 'plano' }); return null }
            const modelosDaAcao = escolherModelos(acao, autor, modelos)
            return (
              <MaterialDeApoio
                acao={acao}
                modelos={modelosDaAcao}
                autor={autor}
                jaConcluida={concluidaNestaSemana(acao.id, autor.concluidas)}
                onVoltar={irPara('plano')}
                onConcluir={() => { concluirAcao(autor.id, acao.id); setTela({ nome: 'plano' }) }}
                onRejeitar={() => { rejeitarAcao(autor.id, acao.id); setTela({ nome: 'plano' }) }}
              />
            )
          })()
        ) : (
          <PlanoDaSemana
            key={autor.id}
            autor={autor}
            fase={fases[autor.id]}
            acoes={acoes}
            onConcluir={concluirAcao}
            onDesfazer={desfazerConclusao}
            onRejeitar={rejeitarAcao}
            onDesfazerRejeicao={desfazerRejeicao}
            onReativarTema={reativarTema}
            onAbrirMaterial={(acao) => setTela({ nome: 'material', acaoId: acao.id })}
            onCheckin={registrarCheckin}
            onDispensarCheckin={dispensarCheckin}
            onVerHistorico={irPara('historico')}
            onEditarCadastro={() => setTela({ nome: 'cadastro', editar: true })}
            onPerfil={() => setTela({ nome: 'perfil' })}
            onRegistrarConquista={registrarConquista}
            onAcoesPorSemana={definirAcoesPorSemana}
            onVerAulas={irPara('aulas')}
          />
        )}
      </main>
    </div>
  )
}
