// Conquistas do autor: frases curtas que vão para a página pública.
// O plano sugere uma conquista quando a ação concluída costuma render uma.
import { preencherModelo } from './variaveis.js'

/** Cria a conquista já com id e data. Texto vazio devolve null. */
export function novaConquista(texto, ano = '') {
  const t = String(texto || '').trim()
  if (!t) return null
  return { id: `q${Date.now()}`, texto: t, ano: String(ano || '').trim(), data: new Date().toISOString() }
}

/** Texto sugerido pela ação (campo `conquistaSugerida`), já com os dados do autor. Null se a ação não sugere. */
export function conquistaSugerida(acao, autor) {
  if (!acao?.conquistaSugerida) return null
  return preencherModelo(acao.conquistaSugerida, autor).texto
}

/** Verdadeiro se o autor já registrou algo com esse texto (evita duplicar pela sugestão). */
export function jaRegistrada(autor, texto) {
  const alvo = String(texto || '').trim().toLowerCase()
  return (autor.conquistas || []).some((c) => String(c.texto).trim().toLowerCase() === alvo)
}
