import { NOME_FASE } from '../regras/fase.js'
import { ESTILO_FASE } from '../marca.js'

/** Seletor de protótipo: um menu discreto para alternar entre os autores de exemplo. */
export default function SeletorAutor({ autores, fases, autorAtualId, onSelecionar }) {
  const atual = autores.find((a) => a.id === autorAtualId)
  const est = atual ? ESTILO_FASE[fases[atual.id]] : null
  return (
    <label className="inline-flex items-center gap-2 text-[12px] text-mudo font-semibold">
      <span className="uppercase tracking-[.08em] text-[10.5px] whitespace-nowrap hidden sm:inline">Protótipo · ver como</span>
      <span className="inline-flex items-center gap-2 bg-areia px-2.5 py-1">
        {est && <i className="inline-block w-2.5 h-2.5 rounded-full" style={{ background: est.cor }} />}
        <select aria-label="Trocar autor de exemplo" value={autorAtualId} onChange={(e) => onSelecionar(e.target.value)} className="bg-transparent text-tinta font-bold text-[12.5px] focus:outline-none">
          {autores.map((a) => <option key={a.id} value={a.id}>{a.nome} · {NOME_FASE[fases[a.id]]}</option>)}
        </select>
      </span>
    </label>
  )
}
