import { useState } from 'react'
import { Link } from 'react-router-dom'
import { filtrarVitrine, generosDaVitrine } from '../regras/vitrine.js'
import Capa from '../componentes/Capa.jsx'
import CabecalhoPublico from '../componentes/CabecalhoPublico.jsx'
import { Estante, LIVROS } from '../componentes/Prateleira.jsx'
import { CORES } from '../marca.js'

export default function Vitrine({ livros }) {
  const [genero, setGenero] = useState('')
  const [busca, setBusca] = useState('')
  const lista = filtrarVitrine(livros, { genero, busca })
  const generos = generosDaVitrine(livros)

  return (
    <div className="min-h-screen">
      <CabecalhoPublico />
      <main className="max-w-5xl mx-auto px-6 py-8">
        {/* composição de painéis */}
        <header className="relative grid grid-cols-1 md:grid-cols-[1.4fr_1fr] min-h-[220px]">
          <div className="bg-tinta text-white px-8 py-9 relative z-10 md:corte-d">
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Vitrine dos autores</p>
            <h1 className="display text-[36px] sm:text-[48px] mt-3 text-balance">Livros de quem aprendeu a vender livros</h1>
            <p className="text-[14px] text-white/75 mt-3 max-w-[50ch]">{livros.length} livros de autores independentes. Clique em uma capa para conhecer o livro e o autor.</p>
          </div>
          <div className="bg-laranja relative md:-ml-[44px] min-h-[200px] overflow-hidden px-6 pt-6 md:pl-[60px]">
            <div className="absolute inset-x-6 md:left-[60px] top-6 bottom-0">
              <Estante livros={LIVROS.filter((l) => ['LEITORES', 'HISTÓRIAS', 'AUTOR', 'VENDAS', 'PUBLICAÇÃO', 'LIBERDADE'].includes(l.p))} altura="100%" gap={6} fonte={11} />
            </div>
          </div>
        </header>

        <div className="flex flex-wrap items-center gap-3 mt-8 mb-8">
          <input type="search" value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar por título ou autor" className="campo !w-full sm:!w-72 text-[14px]" />
          <select aria-label="Filtrar por gênero" value={genero} onChange={(e) => setGenero(e.target.value)} className="campo !w-auto text-[14px]">
            <option value="">Todos os gêneros</option>
            {generos.map((g) => <option key={g} value={g}>{g}</option>)}
          </select>
          {(genero || busca) && <button onClick={() => { setGenero(''); setBusca('') }} className="btn-linha underline underline-offset-4">limpar filtros</button>}
          <span className="text-[12px] font-extrabold uppercase tracking-[.1em] text-mudo ml-auto">{lista.length} {lista.length === 1 ? 'livro' : 'livros'}</span>
        </div>

        {lista.length === 0 && <p className="text-mudo">Nenhum livro encontrado com esses filtros.</p>}

        <ul className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-x-6 gap-y-10">
          {lista.map((l, i) => (
            <li key={l.slug} className={`entra atraso-${(i % 6) + 1}`}>
              <Link to={`/livro/${l.slug}`} className="block group">
                <Capa livro={l} className="transition-transform duration-300 group-hover:-translate-y-2 group-hover:-rotate-1" />
                <p className="mt-3 font-bold text-[14px] leading-snug tracking-tight group-hover:underline underline-offset-4 decoration-2 decoration-ambar">{l.titulo}</p>
                <p className="text-[12.5px] text-mudo font-semibold mt-0.5">{l.nomeAutor}</p>
                {l.emBreve && <p className="text-[10.5px] font-extrabold uppercase tracking-[.12em] text-laranja mt-1">Em breve</p>}
              </Link>
            </li>
          ))}
        </ul>
      </main>
    </div>
  )
}
