import { uso } from '../servicos/uso.js'
import { useState } from 'react'
import { montarBriefingGerador, urlGerador, padroesGerador, OPCOES_GERADOR, PERGUNTAS_NA_HORA, briefingCompleto } from '../regras/gerador.js'
import { URL_GERADOR_POSTS } from '../marca.js'

const ROTULO = { rede: 'Para qual rede?', habilidade: 'Sua habilidade em redes', audiencia: 'Sua audiência', objetivo: 'Objetivo dos posts', tom: 'Que tom?' }
const PLACEHOLDER = { rede: 'escolha a rede', habilidade: 'alto, médio ou baixo', tom: 'escolha o tom' }

function Seletor({ k, valor, onChange, destaque }) {
  return (
    <label className="block">
      <span className="block text-[10.5px] font-extrabold uppercase tracking-[.1em] text-mudo mb-1">{ROTULO[k]}</span>
      <select value={valor} onChange={(e) => onChange(e.target.value)} className={'w-full bg-white border-2 px-2 py-1.5 text-[13px] font-semibold focus:outline-none focus:border-tinta ' + (destaque && !valor ? 'border-laranja' : 'border-fio')}>
        {PLACEHOLDER[k] && <option value="">{PLACEHOLDER[k]}</option>}
        {OPCOES_GERADOR[k].map((o) => <option key={o} value={o}>{o}</option>)}
      </select>
    </label>
  )
}

/** Painel que abre o Gerador de Posts Magnéticos já com as 7 respostas do agente. */
export default function GeradorPosts({ autor, fase, acaoDaSemana, compacto = false }) {
  const [escolhas, setEscolhas] = useState(() => padroesGerador(autor))
  const [copiado, setCopiado] = useState(false)
  const briefing = montarBriefingGerador(autor, fase, escolhas, { acaoDaSemana })
  const set = (k, v) => setEscolhas((e) => ({ ...e, [k]: v }))

  async function copiar() {
    uso('gerador', { acao: 'copiou' })
    try { await navigator.clipboard.writeText(briefing) } catch { /* sem clipboard */ }
    setCopiado(true); setTimeout(() => setCopiado(false), 2000)
  }

  const completo = briefingCompleto(escolhas)
  const BotaoAbrir = ({ rotulo }) => completo
    ? <a href={urlGerador(briefing)} target="_blank" rel="noopener noreferrer" onClick={() => uso('gerador', { acao: 'abriu_gpt' })} className="btn-preto">{rotulo} ↗</a>
    : <span className="btn-preto opacity-40 cursor-not-allowed" title="Responda rede, habilidade e tom">{rotulo} ↗</span>

  if (compacto) {
    return (
      <div className="grid gap-3 w-full">
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
          {PERGUNTAS_NA_HORA.map((k) => <Seletor key={k} k={k} valor={escolhas[k]} onChange={(v) => set(k, v)} destaque />)}
        </div>
        <div className="flex flex-wrap items-center gap-3">
          <BotaoAbrir rotulo="Gerar ideias de posts com meus dados" />
          {completo && <button onClick={copiar} className="btn-linha underline underline-offset-4">{copiado ? 'Copiado' : 'copiar minhas respostas'}</button>}
        </div>
      </div>
    )
  }

  return (
    <section className="mt-4 border-2 border-tinta grid grid-cols-1 md:grid-cols-[1.2fr_1fr]">
      <div className="bg-creme text-tinta px-7 py-6 relative z-10 md:corte-d">
        <p className="text-[13.5px] text-apoio max-w-[50ch]">
          Três respostas e o Gerador faz o resto:
        </p>
        <p className="text-[10.5px] font-extrabold uppercase tracking-[.12em] text-mudo mt-4">Responda agora</p>
        <div className="mt-1 grid grid-cols-1 sm:grid-cols-3 gap-3">
          {PERGUNTAS_NA_HORA.map((k) => <Seletor key={k} k={k} valor={escolhas[k]} onChange={(v) => set(k, v)} destaque />)}
        </div>
        <p className="text-[10.5px] font-extrabold uppercase tracking-[.12em] text-mudo mt-4">Do seu cadastro (pode ajustar)</p>
        <div className="mt-1 grid grid-cols-2 gap-3 max-w-sm">
          {['objetivo', 'audiencia'].map((k) => <Seletor key={k} k={k} valor={escolhas[k]} onChange={(v) => set(k, v)} />)}
        </div>
        <div className="mt-4 flex flex-wrap items-center gap-3">
          <BotaoAbrir rotulo="Abrir o Gerador com minhas respostas" />
          {completo && <button onClick={copiar} className="btn bg-white border-2 border-tinta text-tinta corte-btn">{copiado ? 'Copiado' : 'Copiar respostas'}</button>}
          {!completo && <span className="text-[12.5px] text-apoio font-semibold">Falta responder {PERGUNTAS_NA_HORA.filter((k) => !escolhas[k]).length === 3 ? 'as 3 perguntas' : 'o que está em laranja'}.</span>}
        </div>
        <p className="text-[11.5px] text-mudo mt-3">Abre no ChatGPT (conta gratuita serve). <a href={URL_GERADOR_POSTS} target="_blank" rel="noopener noreferrer" className="underline underline-offset-4">Abrir o Gerador vazio ↗</a></p>
      </div>
      <div className="bg-areia px-7 py-6 md:-ml-[44px] md:pl-[72px]">
        <details>
          <summary className="cursor-pointer text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo hover:text-tinta">Ver o que o LOMBADA envia ao Gerador</summary>
          <pre className="mt-3 text-[12px] font-sans whitespace-pre-wrap leading-snug text-apoio max-h-64 overflow-auto">{briefing}</pre>
        </details>
        <p className="text-[12.5px] text-apoio mt-3">Suas 4 respostas do cadastro vão junto. As 3 da esquerda, você escolhe agora.</p>
      </div>
    </section>
  )
}
