import { Link, useNavigate } from 'react-router-dom'
import Wordmark from '../componentes/Wordmark.jsx'
import Prateleira from '../componentes/Prateleira.jsx'
import { CORES, ESTILO_FASE } from '../marca.js'
import { NOME_FASE, DESCRICAO_FASE, FASES } from '../regras/fase.js'
import { gravarUI } from '../regras/persistencia.js'

/** Porta de entrada do autor novo: explica o LOMBADA em uma tela e leva ao cadastro. */
export default function Comecar() {
  const navigate = useNavigate()
  function comecar() {
    gravarUI({ modoAluno: true, abrirCadastro: true })
    navigate('/')
  }
  return (
    <div className="min-h-screen">
      <div className="border-b-2 border-tinta">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <Wordmark tamanho={24} />
          <Link to="/vitrine" className="text-[13px] font-bold text-mudo hover:text-tinta">Vitrine ↗</Link>
        </div>
      </div>
      <main className="max-w-4xl mx-auto px-4 sm:px-6 py-8">
        <Prateleira altura={260} frase="Ferramentas, conexões e oportunidades para autores" className="entra mb-4" />
        <header className="grid grid-cols-1 md:grid-cols-[1.3fr_1fr] min-h-[340px]">
          <div className="bg-tinta text-white px-7 py-9 sm:px-9 relative z-10 md:corte-d">
            <p className="text-[12px] font-bold uppercase tracking-[.12em] text-ambar">Método The Book Business</p>
            <h1 className="display text-[40px] sm:text-[56px] mt-3 text-balance">O que fazer pelo seu livro esta semana.</h1>
            <p className="text-[15px] text-white/75 mt-4 max-w-[46ch]">
              Cadastre o livro. O LOMBADA descobre em que fase você está e monta, toda semana, de 3 a 5 ações do Método The Book Business para vender mais, com o texto pronto e a aula que ensina cada uma.
            </p>
            <button onClick={comecar} className="btn-primario !text-[15px] !px-7 !py-3.5 mt-7">Cadastrar meu livro</button>
            <p className="text-[12px] text-white/50 mt-3">Leva uns 10 minutos. Depois o time do Método The Book Business confere e libera o seu acesso.</p>
          </div>
          <div className="bg-ambar relative md:-ml-[44px] min-h-[220px] overflow-hidden">
            <div className="absolute inset-0 grid grid-cols-3 grid-rows-2 md:grid-cols-2 md:grid-rows-3 gap-3 px-6 pt-5 pb-8 md:p-6 md:pl-14">
              {[CORES.verde, CORES.laranja, CORES.tinta, 'anel', CORES.creme, CORES.tinta].map((c, i) => (
                <i key={i} className={'rounded-full aspect-square self-center justify-self-center ' + (c === 'anel' ? 'gira-lento' : i % 2 ? 'flutua-x' : 'flutua')} style={{ width: 'min(100%, 76px)', background: c === 'anel' ? 'transparent' : c, border: c === 'anel' ? `7px solid ${CORES.tinta}` : 'none', borderRightColor: c === 'anel' ? 'transparent' : undefined, animationDelay: `${(i * 0.9) % 3}s` }} />
              ))}
            </div>
          </div>
        </header>

        <section className="grid grid-cols-1 md:grid-cols-3 mt-8">
          {[FASES.CONSTRUCAO, FASES.LANCAMENTO, FASES.PERMANENCIA].map((f, i) => {
            const e = ESTILO_FASE[f]
            return (
              <div key={f} className={'px-7 py-6 ' + (i === 0 ? 'relative z-20 md:corte-d' : i === 1 ? 'md:-ml-[44px] md:pl-[72px] relative z-10 md:corte-d' : 'md:-ml-[44px] md:pl-[72px]')} style={{ background: e.cor, color: e.tinta }}>
                <p className="text-[11px] font-extrabold uppercase tracking-[.14em] opacity-80">Fase</p>
                <p className="display text-[28px] mt-2">{NOME_FASE[f]}</p>
                <p className="text-[13px] font-medium mt-2 opacity-90">{DESCRICAO_FASE[f]}</p>
              </div>
            )
          })}
        </section>

        <section className="grid grid-cols-1 sm:grid-cols-3 gap-6 mt-10 text-[14px]">
          {[
            ['Plano da semana', 'De 3 a 5 ações escolhidas pelo seu cadastro: lista de e-mail, audiência, objetivo, horas disponíveis.'],
            ['Texto pronto e aula', 'Cada ação vem com post, e-mail ou mensagem já preenchidos com os dados do seu livro, e o link da aula do Método The Book Business.'],
            ['Vitrine e leitores', 'Uma página pública do seu livro para compartilhar, com captura de e-mail de quem quer suas novidades.'],
          ].map(([t, d]) => (
            <div key={t} className="border-t-[3px] border-tinta pt-4">
              <p className="font-extrabold text-[15px]">{t}</p>
              <p className="text-apoio mt-1">{d}</p>
            </div>
          ))}
        </section>

        <p className="text-[12.5px] text-mudo mt-10">Já tem cadastro neste navegador? <Link to="/" className="underline underline-offset-4 font-semibold text-tinta">Abrir meu plano</Link>.</p>
      </main>
    </div>
  )
}
