import { uso } from '../servicos/uso.js'
import { useState } from 'react'
import { urlAula, modulos, sincronizacao } from '../regras/aulas.js'
import { formatarDataLonga } from '../regras/datas.js'
import { URL_AREA_DE_MEMBROS } from '../marca.js'

export default function Aulas({ acoes, onVoltar }) {
  const [busca, setBusca] = useState('')
  const MODULOS = modulos(), SINCRONIZACAO = sincronizacao()
  const [aberto, setAberto] = useState(() => new Set(MODULOS.filter((m) => m.tipo === 'curso').map((m) => m.id)))
  const termo = busca.trim().toLowerCase()
  const usadaEmAcao = new Set(acoes.map((a) => a.aula?.pageId).filter(Boolean))

  const alternar = (id) => setAberto((s) => { const n = new Set(s); n.has(id) ? n.delete(id) : n.add(id); return n })

  return (
    <div>
      <button onClick={onVoltar} className="btn-linha">← Voltar ao plano da semana</button>
      <header className="mt-5 bg-tinta text-white px-8 py-8 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Aulas do Método The Book Business</p>
        <h1 className="display text-[34px] sm:text-[42px] mt-3 text-balance">Cada ação do seu plano nasce de uma aula.</h1>
        <p className="text-[13.5px] text-white/75 mt-3">
          Assista à aula antes de fazer a ação: leva poucos minutos e muda o resultado. As marcadas com o ponto âmbar têm ação ligada no seu plano. Atualizado em {formatarDataLonga(SINCRONIZACAO.em)}.
        </p>
      </header>

      <div className="mt-6 flex flex-wrap items-center gap-3">
        <input type="search" value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar aula por título" className="campo !w-full sm:!w-80 text-[14px]" />
        <a href={URL_AREA_DE_MEMBROS} target="_blank" rel="noopener noreferrer" className="btn-linha ml-auto">Abrir área de membros ↗</a>
      </div>

      <div className="mt-6 grid gap-4">
        {MODULOS.map((m) => {
          const aulas = m.aulas.filter(([, nome]) => !termo || nome.toLowerCase().includes(termo))
          if (termo && aulas.length === 0) return null
          const abertoAgora = termo ? true : aberto.has(m.id)
          return (
            <section key={m.id} className="bg-areia">
              <button onClick={() => alternar(m.id)} className="w-full flex items-baseline justify-between gap-4 px-6 py-4 text-left">
                <span className="display text-[18px]">{m.nome}</span>
                <span className="text-[12px] font-extrabold uppercase tracking-[.1em] text-mudo shrink-0">{abertoAgora ? 'Fechar −' : 'Ver aulas +'}</span>
              </button>
              {abertoAgora && (
                <ul className="border-t-2 border-white">
                  {aulas.map(([id, nome]) => (
                    <li key={id}>
                      <a href={urlAula(id)} target="_blank" rel="noopener noreferrer" onClick={() => uso('aula', { pageId: id, nome, origem: 'lista' })} className="group grid grid-cols-[16px_1fr_auto] gap-4 items-baseline px-6 py-3 border-b border-white hover:bg-white transition-colors">
                        <i className={'w-2.5 h-2.5 rounded-full relative top-[1px] ' + (usadaEmAcao.has(id) ? 'bg-ambar' : 'bg-fio')} />
                        <span className="text-[14px] font-semibold leading-snug">{nome}</span>
                        <span className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo group-hover:text-tinta">Assistir ↗</span>
                      </a>
                    </li>
                  ))}
                </ul>
              )}
            </section>
          )
        })}
      </div>
    </div>
  )
}
