import Wordmark from '../componentes/Wordmark.jsx'
import Capa from '../componentes/Capa.jsx'
import { URL_SUPORTE } from '../marca.js'
import { STATUS_CADASTRO, statusCadastro } from '../regras/aprovacao.js'
import { formatarDataLonga } from '../regras/datas.js'

/** O que o autor vê enquanto o time confere o cadastro (ou pede ajustes). */
export default function CadastroEmAnalise({ autor, onEditar, onTrocarAutor, onSair }) {
  const status = statusCadastro(autor)
  const ajustar = status === STATUS_CADASTRO.AJUSTAR
  const primeiro = autor.nome.split(' ')[0]
  return (
    <div className="min-h-screen">
      <div className="border-b-2 border-tinta">
        <div className="max-w-4xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <Wordmark tamanho={24} />
          <span className="flex items-center gap-3">
            {onTrocarAutor && <button onClick={onTrocarAutor} className="btn-linha">ver outros autores (protótipo)</button>}
            {onSair && <button onClick={onSair} className="btn-linha">Sair</button>}
          </span>
        </div>
      </div>
      <main className="max-w-4xl mx-auto px-4 sm:px-6 py-8">
        <header className="grid grid-cols-1 md:grid-cols-[1.3fr_1fr] entra">
          <div className={'text-white px-7 py-9 sm:px-9 relative z-10 md:corte-d ' + (ajustar ? 'bg-alerta' : 'bg-tinta')}>
            <p className="text-[12px] font-bold uppercase tracking-[.12em] text-ambar">{ajustar ? 'Precisa de um ajuste' : 'Cadastro em análise'}</p>
            <h1 className="display text-[36px] sm:text-[48px] mt-3 text-balance">
              {ajustar ? `${primeiro}, o time pediu um ajuste no seu cadastro.` : `${primeiro}, seu cadastro chegou. Agora é com o time.`}
            </h1>
            {ajustar ? (
              <div className="mt-5 bg-white/15 px-5 py-4">
                <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-white/70">Observação do time</p>
                <p className="text-[15px] font-semibold mt-1">{autor.cadastro?.observacao || 'Confira os campos e envie de novo.'}</p>
              </div>
            ) : (
              <p className="text-[15px] text-white/75 mt-4 max-w-[48ch]">
                O time do Método The Book Business confere se está tudo certo com o livro e com a sua página. Assim que liberar, o seu plano da primeira semana aparece aqui.
                {autor.cadastro?.enviadoEm ? ` Enviado em ${formatarDataLonga(autor.cadastro.enviadoEm)}.` : ''}
              </p>
            )}
            <div className="mt-7 flex flex-wrap gap-3">
              <button onClick={onEditar} className="btn-primario !text-[15px] !px-7 !py-3.5">{ajustar ? 'Ajustar e reenviar' : 'Revisar meu cadastro'}</button>
              <a href={URL_SUPORTE} target="_blank" rel="noopener noreferrer" className="btn bg-white/10 text-white corte-btn">Falar com a Dezza</a>
            </div>
          </div>
          <div className="bg-areia relative md:-ml-[44px] md:pl-[72px] px-7 py-8 grid grid-cols-[96px_1fr] gap-5 items-start">
            <Capa livro={{ ...autor.livro, nomeAutor: autor.nome }} className="w-24" />
            <div>
              <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">O que você enviou</p>
              <p className="font-extrabold text-[18px] leading-tight mt-2">{autor.livro.titulo}</p>
              <p className="text-[12.5px] text-apoio font-semibold mt-1">{autor.livro.genero}{autor.livro.subNicho ? ` · ${autor.livro.subNicho}` : ''}</p>
              <p className="text-[12.5px] text-mudo mt-2">{autor.nome}{autor.cidade ? ` · ${autor.cidade}` : ''}</p>
            </div>
          </div>
        </header>
        <section className="mt-8 bg-areia px-7 py-6 text-[14px] max-w-[70ch]">
          <p className="font-extrabold">Enquanto isso</p>
          <p className="text-apoio mt-1">Assista às primeiras aulas do Método The Book Business e entre na Comunidade de Escritores. Quando o cadastro for liberado, o LOMBADA já monta a sua semana.</p>
        </section>
      </main>
    </div>
  )
}
