// Escolha do modelo de texto para um autor.
// Única função responsável por isso.

/**
 * Para cada modelo da ação, procura uma variante do gênero do livro do autor.
 * Variante = modelo com `variaDe` apontando para o modelo base e `genero` igual
 * ao do livro. Se não houver, usa o modelo base.
 */
export function escolherModelos(acao, autor, modelos) {
  const genero = autor.livro.genero
  return (acao.modeloIds || [])
    .map((baseId) => {
      const variante = modelos.find((m) => m.variaDe === baseId && m.genero === genero)
      return variante || modelos.find((m) => m.id === baseId)
    })
    .filter(Boolean)
}
