import { useState } from 'react'
import { Link } from 'react-router-dom'
import Wordmark from '../componentes/Wordmark.jsx'
import { URL_SUPORTE } from '../marca.js'
import { Estante, Pilha, LIVROS } from '../componentes/Prateleira.jsx'

/**
 * Entrada do autor (versão 2 do estudo, sem moldura): estante creme à esquerda,
 * formulário limpo à direita. E-mail + código de 6 números enviado pelo time no WhatsApp.
 */
export default function Entrar({ onEntrar, onCadastrar, erro, carregando }) {
  const [email, setEmail] = useState('')
  const [codigo, setCodigo] = useState('')
  return (
    <div className="min-h-screen grid md:grid-cols-2">
      {/* marca + estante */}
      <div className="bg-creme px-6 py-7 sm:px-10 sm:py-10 flex flex-col justify-between gap-8 relative z-10 md:corte-d entra">
        <div>
          <Wordmark tamanho={40} />
          <p className="text-[12px] font-bold uppercase tracking-[.2em] text-apoio mt-2 max-w-[30ch] leading-relaxed">A área do autor do Método The Book Business</p>
        </div>
        <div className="hidden md:block"><Estante livros={LIVROS.slice(0, 7)} altura={300} /></div>
        <div className="md:hidden"><Pilha livros={LIVROS.filter((_, i) => [0, 1, 4, 6].includes(i))} /></div>
        <Link to="/vitrine" className="hidden md:inline text-[13px] font-bold text-mudo hover:text-tinta">Vitrine dos autores ↗</Link>
      </div>

      {/* formulário */}
      <div className="px-6 py-10 sm:px-12 md:-ml-[44px] md:pl-[88px] flex flex-col justify-center entra atraso-1">
        <div className="max-w-[400px]">
          <h1 className="display text-[34px]">Entrar</h1>
          <p className="text-[14px] text-apoio mt-2">Use o e-mail do cadastro e o código de 6 números.</p>
          <form onSubmit={(e) => { e.preventDefault(); onEntrar(email, codigo) }} className="mt-6 grid gap-4">
            <label className="block">
              <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1.5">E-mail</span>
              <input type="email" required autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} className="campo" placeholder="voce@exemplo.com" />
            </label>
            <label className="block">
              <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1.5">Código de acesso</span>
              <input inputMode="numeric" autoComplete="one-time-code" required value={codigo} onChange={(e) => setCodigo(e.target.value.replace(/\D/g, '').slice(0, 6))} className="campo !text-[20px] tracking-[.3em] display" placeholder="••••••" />
              <span className="block text-[12px] text-mudo mt-1.5">Chegou pelo WhatsApp quando seu cadastro foi liberado.</span>
            </label>
            {erro && <p className="text-[13px] font-bold text-alerta">{erro}</p>}
            <button type="submit" disabled={carregando || codigo.length < 6} className="btn-primario w-full !py-3.5 !text-[15px] disabled:opacity-50">{carregando ? 'Entrando…' : 'Entrar'}</button>
            <div className="flex flex-wrap gap-x-4 gap-y-1 text-[13px]">
              <a href={URL_SUPORTE} target="_blank" rel="noopener noreferrer" className="font-bold text-mudo hover:text-tinta underline underline-offset-4">Não tenho código</a>
              <span className="text-fio">·</span>
              <button type="button" onClick={onCadastrar} className="font-bold text-tinta underline underline-offset-4">Cadastrar meu livro</button>
            </div>
          </form>
          <p className="text-[12px] text-mudo mt-10"><Link to="/termos" className="underline underline-offset-4 hover:text-tinta">Termos de uso</Link> · <Link to="/privacidade" className="underline underline-offset-4 hover:text-tinta">Privacidade</Link></p>
        </div>
      </div>
    </div>
  )
}
