// Otimização de imagem no navegador antes de salvar: redimensiona, recorta
// (opcional) e comprime em WebP (JPEG se o navegador não suportar).

export const PERFIS = {
  capa: { maxLargura: 600, maxAltura: 900, qualidade: 0.82, recorte: null },
  foto: { maxLargura: 400, maxAltura: 400, qualidade: 0.82, recorte: 'quadrado' },
}

function carregar(file) {
  return new Promise((ok, erro) => {
    const img = new Image()
    img.onload = () => ok(img)
    img.onerror = () => erro(new Error('Não consegui ler a imagem.'))
    img.src = URL.createObjectURL(file)
  })
}

/**
 * Devolve { dataUrl, largura, altura, bytes }.
 * @param {File} file
 * @param {'capa'|'foto'} perfil
 */
export async function otimizarImagem(file, perfil = 'capa') {
  if (!file || !file.type.startsWith('image/')) throw new Error('Escolha um arquivo de imagem (JPG, PNG ou WebP).')
  if (file.size > 15 * 1024 * 1024) throw new Error('Imagem acima de 15 MB. Escolha uma menor.')
  const p = PERFIS[perfil] || PERFIS.capa
  const img = await carregar(file)

  // recorte
  let sx = 0, sy = 0, sw = img.naturalWidth, sh = img.naturalHeight
  if (p.recorte === 'quadrado') {
    const lado = Math.min(sw, sh)
    sx = Math.floor((sw - lado) / 2); sy = Math.floor((sh - lado) / 2); sw = lado; sh = lado
  }
  // escala
  const escala = Math.min(1, p.maxLargura / sw, p.maxAltura / sh)
  const w = Math.max(1, Math.round(sw * escala)), h = Math.max(1, Math.round(sh * escala))

  const canvas = document.createElement('canvas')
  canvas.width = w; canvas.height = h
  const ctx = canvas.getContext('2d')
  ctx.imageSmoothingQuality = 'high'
  ctx.drawImage(img, sx, sy, sw, sh, 0, 0, w, h)
  URL.revokeObjectURL(img.src)

  let dataUrl = canvas.toDataURL('image/webp', p.qualidade)
  if (!dataUrl.startsWith('data:image/webp')) dataUrl = canvas.toDataURL('image/jpeg', p.qualidade)
  const bytes = Math.round((dataUrl.length - dataUrl.indexOf(',') - 1) * 3 / 4)
  return { dataUrl, largura: w, altura: h, bytes }
}

export function formatarBytes(b) {
  return b > 1024 * 1024 ? `${(b / 1024 / 1024).toFixed(1)} MB` : `${Math.round(b / 1024)} KB`
}
