import { classeInput } from './campos.jsx'

/**
 * Conquistas do autor: frases curtas com ano opcional. Aparecem na página pública do livro.
 * O autor cadastra no começo ou vai acrescentando ao longo do uso.
 */
export default function ListaConquistas({ valor = [], onChange }) {
  const lista = valor
  const set = (i, campo, v) => onChange(lista.map((c, k) => (k === i ? { ...c, [campo]: v } : c)))
  const remover = (i) => onChange(lista.filter((_, k) => k !== i))
  const adicionar = () => onChange([...lista, { id: `q${Date.now()}`, texto: '', ano: '' }])
  return (
    <div>
      <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1">Conquistas (opcional)</span>
      <p className="text-[12.5px] text-mudo mb-3">Prêmios, listas de mais vendidos, palestras, imprensa, número de exemplares. Uma por linha, curta. Aparecem na sua página na vitrine e você pode acrescentar quando quiser.</p>
      <ul className="grid gap-2">
        {lista.map((c, i) => (
          <li key={c.id || i} className="grid grid-cols-[1fr_88px_auto] gap-2 items-center">
            <input className={classeInput} placeholder="Ex.: Finalista do Prêmio Jabuti" value={c.texto} onChange={(e) => set(i, 'texto', e.target.value)} />
            <input className={classeInput} placeholder="Ano" inputMode="numeric" maxLength={4} value={c.ano || ''} onChange={(e) => set(i, 'ano', e.target.value.replace(/\D/g, ''))} />
            <button type="button" onClick={() => remover(i)} className="text-[12px] font-bold text-mudo hover:text-alerta px-1" title="Remover conquista" aria-label="Remover conquista">×</button>
          </li>
        ))}
      </ul>
      <button type="button" onClick={adicionar} className="mt-3 inline-flex items-center gap-2 text-[12.5px] font-extrabold border-2 border-tinta px-3.5 py-2 hover:bg-tinta hover:text-white transition-colors">
        + Adicionar conquista
      </button>
    </div>
  )
}
