// Regra de classificação de fase do autor.
// Única função responsável por isso: alterar aqui muda todo o sistema.

export const FASES = {
  CONSTRUCAO: 'construcao',
  LANCAMENTO: 'lancamento',
  PERMANENCIA: 'permanencia',
}

export const NOME_FASE = {
  [FASES.CONSTRUCAO]: 'Construção',
  [FASES.LANCAMENTO]: 'Lançamento',
  [FASES.PERMANENCIA]: 'Permanência',
}

export const DESCRICAO_FASE = {
  [FASES.CONSTRUCAO]: 'Livro ainda não publicado. O foco é preparar o terreno e reunir leitores antes do lançamento.',
  [FASES.LANCAMENTO]: 'Livro publicado há menos de 90 dias. O foco é ativar quem já te acompanha e gerar as primeiras avaliações.',
  [FASES.PERMANENCIA]: 'Livro publicado há mais de 90 dias. O foco é manter o livro vivo, ser lembrado e alcançar novos leitores.',
}

// Status possíveis do livro no cadastro
export const STATUS_LIVRO = {
  ESCREVENDO: 'escrevendo',
  PRONTO_NAO_PUBLICADO: 'pronto_nao_publicado',
  PUBLICADO: 'publicado',
}

export const DIAS_LIMITE_LANCAMENTO = 90

/**
 * Classifica a fase do autor a partir do livro cadastrado.
 * @param {{ status: string, dataPublicacao?: string|null }} livro
 * @param {Date} hoje
 * @returns {string} uma das FASES
 */
export function classificarFase(livro, hoje = new Date()) {
  if (livro.status !== STATUS_LIVRO.PUBLICADO || !livro.dataPublicacao) {
    return FASES.CONSTRUCAO
  }
  const publicadoEm = new Date(livro.dataPublicacao)
  const diasPublicado = Math.floor((hoje - publicadoEm) / (1000 * 60 * 60 * 24))
  return diasPublicado < DIAS_LIMITE_LANCAMENTO ? FASES.LANCAMENTO : FASES.PERMANENCIA
}
