import { classeInput } from './campos.jsx'

/** Trechos favoritos do livro: quantos quiser. Um por semana vira citação, post e página. */
export default function ListaTrechos({ valor = [], onChange, erro }) {
  const lista = valor.length ? valor : [{ id: 't1', texto: '' }]
  const set = (i, v) => onChange(lista.map((t, k) => (k === i ? { ...t, texto: v } : t)))
  const remover = (i) => onChange(lista.filter((_, k) => k !== i))
  const adicionar = () => onChange([...lista, { id: `t${Date.now()}`, texto: '' }])
  return (
    <div>
      <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1">Trechos favoritos do livro</span>
      <p className="text-[12.5px] text-mudo mb-3">Uma ou duas frases suas por trecho. Cada semana o LOMBADA usa um deles na citação, nos textos prontos e na sua página. Quanto mais, menos repete.</p>
      <ul className="grid gap-2">
        {lista.map((t, i) => (
          <li key={t.id || i} className="grid grid-cols-[1fr_auto] gap-2 items-start">
            <textarea className={classeInput + ' min-h-16'} value={t.texto} onChange={(e) => set(i, e.target.value)} placeholder={i === 0 ? 'Ex.: A casa não tinha mudado. Eu é que tinha aprendido a não olhar.' : 'Outro trecho'} />
            {lista.length > 1 && <button type="button" onClick={() => remover(i)} className="text-[12px] font-bold text-mudo hover:text-alerta px-1 mt-2" title="Remover trecho" aria-label="Remover trecho">×</button>}
          </li>
        ))}
      </ul>
      {erro && <p className="text-[12.5px] font-semibold text-alerta mt-1">{erro}</p>}
      <button type="button" onClick={adicionar} className="mt-3 inline-flex items-center gap-2 text-[12.5px] font-extrabold border-2 border-tinta px-3.5 py-2 hover:bg-tinta hover:text-white transition-colors">
        + Adicionar trecho
      </button>
    </div>
  )
}
