import { useState } from 'react'

/**
 * Compartilhar um link: no celular abre a folha nativa (WhatsApp, Instagram, etc.);
 * no desktop abre um menu com WhatsApp e copiar link.
 */
export default function Compartilhar({ url, titulo, texto, rotulo = 'Compartilhar', className = 'btn-preto' }) {
  const [aberto, setAberto] = useState(false)
  const [copiado, setCopiado] = useState(false)
  const mensagem = `${texto || titulo}\n${url}`
  const podeNativo = typeof navigator !== 'undefined' && typeof navigator.share === 'function'

  async function compartilhar() {
    if (podeNativo) {
      try { await navigator.share({ title: titulo, text: texto, url }); return } catch { /* cancelou */ }
    }
    setAberto((a) => !a)
  }
  async function copiar() {
    try { await navigator.clipboard.writeText(url) } catch { /* sem clipboard */ }
    setCopiado(true); setTimeout(() => { setCopiado(false); setAberto(false) }, 1500)
  }

  return (
    <span className="relative inline-block">
      <button type="button" onClick={compartilhar} className={className}>{rotulo}</button>
      {aberto && !podeNativo && (
        <span className="absolute left-0 top-full mt-2 z-20 grid gap-1 bg-white border-2 border-tinta p-2 min-w-[220px] surge-toast">
          <a href={`https://wa.me/?text=${encodeURIComponent(mensagem)}`} target="_blank" rel="noopener noreferrer" onClick={() => setAberto(false)} className="px-3 py-2 text-[13px] font-bold hover:bg-areia">WhatsApp</a>
          <a href={`mailto:?subject=${encodeURIComponent(titulo)}&body=${encodeURIComponent(mensagem)}`} onClick={() => setAberto(false)} className="px-3 py-2 text-[13px] font-bold hover:bg-areia">E-mail</a>
          <button type="button" onClick={copiar} className="px-3 py-2 text-[13px] font-bold text-left hover:bg-areia">{copiado ? 'Link copiado' : 'Copiar link'}</button>
        </span>
      )}
    </span>
  )
}
