// Vários livros por autor, um em foco.
//
// Forma guardada (banco/localStorage):
//   autor.livros      = [{ id, slug, titulo, ..., concluidas, rejeitadas, checkins, checkinsDispensados, conquistas, temasReativados }]
//   autor.livroFoco   = id do livro em foco
//   autor.vagasLivros = quantos livros o autor pode ter (padrão 1; a equipe libera mais)
//
// Forma que o resto do app lê (projeção): autor.livro + autor.concluidas/rejeitadas/checkins/... do livro em foco.
// `projetar` monta essa forma; `sincronizarLivros` grava as mudanças da projeção de volta no livro em foco.
// Cadastros antigos (um `livro` solto) são migrados em `migrarLivros`.

import { slugify } from './vitrine.js'

export const CAMPOS_DO_LIVRO = ['concluidas', 'rejeitadas', 'checkins', 'checkinsDispensados', 'conquistas', 'temasReativados']

const lista = (v) => (Array.isArray(v) ? v : [])
export const novoIdLivro = () => `l${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`

/** Um livro "cheio": campos do cadastro + histórico próprio, com id e slug garantidos. */
export function completarLivro(l = {}) {
  const livro = { titulo: '', genero: '', status: 'escrevendo', ...l }
  livro.id = livro.id || novoIdLivro()
  livro.slug = slugify(livro.titulo || '') || livro.slug || livro.id
  livro.trechos = lista(livro.trechos)
  livro.criadoEm = livro.criadoEm || null // quando este livro entrou (o plano conta a "primeira semana" a partir daqui)
  for (const c of CAMPOS_DO_LIVRO) livro[c] = lista(livro[c])
  return livro
}

/** Cadastro antigo (um livro solto com histórico no autor) vira `livros[]` + `livroFoco`. Idempotente. */
export function migrarLivros(d) {
  if (!d) return d
  if (Array.isArray(d.livros) && d.livros.length) {
    const livros = d.livros.map(completarLivro)
    const foco = livros.some((l) => l.id === d.livroFoco) ? d.livroFoco : livros[0].id
    return { ...d, livros, livroFoco: foco, vagasLivros: Math.max(1, Number(d.vagasLivros) || 1), autorCadastradoEm: d.autorCadastradoEm || d.cadastradoEm || null }
  }
  const primeiro = completarLivro({ ...(d.livro || {}), criadoEm: d.livro?.criadoEm || d.cadastradoEm || null, ...Object.fromEntries(CAMPOS_DO_LIVRO.map((c) => [c, lista(d[c])])) })
  // autorCadastradoEm guarda a data de entrada do autor (cadastradoEm passa a acompanhar o livro em foco)
  return { ...d, livros: [primeiro], livroFoco: primeiro.id, vagasLivros: Math.max(1, Number(d.vagasLivros) || 1), autorCadastradoEm: d.autorCadastradoEm || d.cadastradoEm || null }
}

export function livroEmFoco(autor) {
  const livros = lista(autor?.livros)
  return livros.find((l) => l.id === autor.livroFoco) || livros[0] || null
}

/** Autor como o app lê: `livro` e o histórico do livro em foco no topo. */
export function projetar(autor) {
  const a = migrarLivros(autor)
  const foco = livroEmFoco(a)
  if (!foco) return a
  const { id, ...campos } = foco
  const livro = { ...campos, id }
  for (const c of CAMPOS_DO_LIVRO) delete livro[c]
  // cadastradoEm passa a ser a data do livro em foco: "primeira semana" e "retomar" são por livro
  return { ...a, livro, cadastradoEm: foco.criadoEm || a.cadastradoEm, ...Object.fromEntries(CAMPOS_DO_LIVRO.map((c) => [c, foco[c]])) }
}

/** Grava a projeção (livro + histórico do topo) de volta no livro em foco. Use antes de salvar. */
export function sincronizarLivros(autor) {
  const a = migrarLivros(autor)
  const foco = livroEmFoco(a)
  if (!foco || !a.livro) return a
  const atualizado = completarLivro({ ...foco, ...a.livro, id: foco.id, ...Object.fromEntries(CAMPOS_DO_LIVRO.map((c) => [c, lista(a[c])])) })
  return { ...a, livros: a.livros.map((l) => (l.id === foco.id ? atualizado : l)) }
}

/** Troca o livro em foco (depois de guardar o que estava em edição) e devolve a nova projeção. */
export function trocarFoco(autor, livroId) {
  const a = sincronizarLivros(autor)
  if (!a.livros.some((l) => l.id === livroId)) return projetar(a)
  return projetar({ ...a, livroFoco: livroId })
}

/** Acrescenta um livro (já em foco) se houver vaga. Devolve a projeção ou null se não há vaga. */
export function adicionarLivro(autor, dadosDoLivro) {
  const a = sincronizarLivros(autor)
  if (!temVaga(a)) return null
  const novo = completarLivro({ ...dadosDoLivro, criadoEm: new Date().toISOString() })
  return projetar({ ...a, livros: [...a.livros, novo], livroFoco: novo.id })
}

/** Remove um livro (nunca o último). */
export function removerLivro(autor, livroId) {
  const a = sincronizarLivros(autor)
  if (a.livros.length <= 1) return projetar(a)
  const livros = a.livros.filter((l) => l.id !== livroId)
  return projetar({ ...a, livros, livroFoco: a.livroFoco === livroId ? livros[0].id : a.livroFoco })
}

export function temVaga(autor) {
  const a = migrarLivros(autor)
  return a.livros.length < (Math.max(1, Number(a.vagasLivros) || 1))
}

/** Todos os slugs do autor (páginas públicas). */
export function slugsDoAutor(autor) {
  return migrarLivros(autor).livros.map((l) => l.slug).filter(Boolean)
}
