// Filtro da Central de Oportunidades. Única função responsável por isso.

const DIA_MS = 1000 * 60 * 60 * 24
export const DIAS_PARA_DESTAQUE = 7

/** Dias inteiros até o prazo (negativo se já venceu). Prazo vale até o fim do dia. */
export function diasAteOPrazo(prazo, hoje = new Date()) {
  const fimDoPrazo = new Date(prazo)
  fimDoPrazo.setHours(23, 59, 59, 999)
  const inicioDeHoje = new Date(hoje)
  inicioDeHoje.setHours(0, 0, 0, 0)
  return Math.floor((fimDoPrazo - inicioDeHoje) / DIA_MS)
}

/**
 * Oportunidades para um autor:
 *   - só as que se aplicam ao gênero do livro (ou a todos, se `todosGeneros`);
 *   - vencidas não aparecem;
 *   - ordenadas do prazo mais próximo ao mais distante;
 *   - `destaque` = vence em até DIAS_PARA_DESTAQUE dias.
 */
export function filtrarOportunidades(oportunidades, genero, hoje = new Date(), { todosGeneros = false } = {}) {
  return oportunidades
    .filter((o) => todosGeneros || o.generos.includes(genero))
    .map((o) => ({ ...o, diasRestantes: diasAteOPrazo(o.prazo, hoje) }))
    .filter((o) => o.diasRestantes >= 0)
    .sort((a, b) => a.diasRestantes - b.diasRestantes)
    .map((o) => ({ ...o, destaque: o.diasRestantes <= DIAS_PARA_DESTAQUE }))
}
