import { uso } from '../servicos/uso.js'
import { useState } from 'react'
import { montarLembrete, gerarICS, linkGoogleAgenda } from '../regras/lembretes.js'
import GeradorPosts from './GeradorPosts.jsx'
import CardSemana from './CardSemana.jsx'

/**
 * Linha compacta de ferramentas: Gerador de posts, lembrete no calendário e
 * compartilhar a semana. Cada uma abre só quando o autor quer.
 */
export default function FerramentasSemana({ autor, fase, feitasNaSemana, totalNaSemana, sequencia, tituloProxima, numeroSemana, urlComunidade }) {
  const [aberta, setAberta] = useState(null) // 'gerador' | 'lembrete' | 'compartilhar'
  const urlApp = window.location.origin + import.meta.env.BASE_URL.replace(/\/$/, '')
  const lembrete = montarLembrete(autor, urlApp)
  const alternar = (k) => setAberta((a) => { if (a !== k) uso('ferramenta', { qual: k }); return a === k ? null : k })

  function baixarICS() {
    uso('lembrete', { tipo: 'ics' })
    const blob = new Blob([gerarICS(lembrete, urlApp)], { type: 'text/calendar;charset=utf-8' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a'); a.href = url; a.download = 'lombada-lembrete.ics'; a.click()
    URL.revokeObjectURL(url)
  }

  const cartoes = [
    { k: 'gerador', cor: 'bg-ambar text-tinta', botao: 'bg-tinta text-white', kicker: 'Gerador de Posts Magnéticos', titulo: 'Tá sem ideia do que postar?', desc: '5 ideias na hora, com os seus dados.', cta: 'Gerar 5 ideias' },
    { k: 'compartilhar', cor: 'bg-verde text-creme', botao: 'bg-creme text-tinta', kicker: 'Comunidade de Escritores', titulo: 'Quem não é visto, não é lembrado...', desc: 'Card da semana e texto prontos para o grupo.', cta: 'Compartilhar na Comunidade' },
    { k: 'lembrete', cor: 'bg-tinta text-white', botao: 'bg-ambar text-tinta', kicker: lembrete.diario ? 'Lembrete diário' : 'Lembrete semanal', titulo: 'O que não está na agenda, não acontece.', desc: lembrete.diario ? 'Todo dia útil, 9h, na sua agenda.' : 'Toda segunda, 9h, na sua agenda.', cta: 'Configurar lembrete' },
  ]

  return (
    <section className="mt-14 entra atraso-5 bg-areia px-5 py-6 sm:px-8 sm:py-8">
      <div className="flex flex-wrap items-end justify-between gap-2 border-b-[3px] border-tinta pb-4">
        <h2 className="display text-[26px]">Caixa de ferramentas</h2>
      </div>

      <ol className="divide-y-2 divide-tinta/15">
        {cartoes.map((c, i) => {
          const ativo = aberta === c.k
          return (
            <li key={c.k}>
              <button
                onClick={() => alternar(c.k)}
                aria-expanded={ativo}
                className={
                  'group w-full text-left grid grid-cols-[44px_1fr] sm:grid-cols-[64px_1fr_auto] gap-x-4 gap-y-3 items-center py-5 sm:py-6 px-3 sm:px-4 transition-colors ' +
                  (ativo ? 'bg-tinta text-white' : 'hover:bg-white')
                }
              >
                <span className="relative block w-[26px] sm:w-[34px] h-[52px] sm:h-[64px] justify-self-start" style={{ background: ativo ? '#FAAB00' : ['#14523E', '#FC783C', '#14110F'][i], borderRadius: '4px 4px 0 0' }} aria-hidden="true">
                  <b className="absolute left-1.5 right-1.5 top-2 h-[2px] bg-white/70" />
                  <b className="absolute left-1.5 right-1.5 top-3.5 h-[2px] bg-white/70" />
                  <b className="absolute left-1/2 -translate-x-1/2 bottom-2.5 w-2.5 h-2.5 rounded-full bg-white/80" />
                </span>
                <span className="min-w-0">
                  <span className={'block text-[10.5px] font-extrabold uppercase tracking-[.12em] ' + (ativo ? 'text-ambar' : 'text-mudo')}>{c.kicker}</span>
                  <span className={'block display text-[20px] sm:text-[24px] leading-[1.05] mt-1 text-balance ' + (ativo ? 'text-white' : 'text-tinta')}>{c.titulo}</span>
                  <span className={'block text-[13px] mt-1.5 max-w-[60ch] ' + (ativo ? 'text-white/75' : 'text-apoio')}>{c.desc}</span>
                </span>
                <span
                  className={
                    'inline-flex items-center gap-2 justify-self-start sm:justify-self-end col-start-2 sm:col-start-3 px-4 py-2.5 text-[12px] font-extrabold uppercase tracking-[.06em] border-2 transition-colors ' +
                    (ativo ? 'bg-ambar border-ambar text-tinta' : 'bg-tinta border-tinta text-white group-hover:bg-ambar group-hover:border-ambar group-hover:text-tinta')
                  }
                >
                  {ativo ? 'Fechar' : c.cta}
                  <span aria-hidden="true" className={'inline-block transition-transform ' + (ativo ? 'rotate-45' : '')}>+</span>
                </span>
              </button>
              {ativo && (
                <div className="pb-6">
                  {aberta === 'gerador' && <GeradorPosts autor={autor} fase={fase} acaoDaSemana={tituloProxima} />}

                  {aberta === 'lembrete' && (
        <div className="mt-4 bg-areia border-2 border-tinta px-7 py-7 grid grid-cols-1 md:grid-cols-[1fr_auto] gap-5 items-center">
          <div>
            <p className="text-[13.5px] text-apoio max-w-[52ch]">O evento abre o seu plano e repete sozinho.</p>
          </div>
          <div className="flex flex-wrap gap-3">
            <a href={linkGoogleAgenda(lembrete)} target="_blank" rel="noopener noreferrer" onClick={() => uso('lembrete', { tipo: 'google' })} className="btn-preto">Google Agenda</a>
            <button onClick={baixarICS} className="btn bg-white border-2 border-tinta text-tinta corte-btn">Apple ou Outlook (.ics)</button>
          </div>
        </div>
      )}

                  {aberta === 'compartilhar' && (
        <CardSemana autor={autor} fase={fase} feitasNaSemana={feitasNaSemana} totalNaSemana={totalNaSemana} sequencia={sequencia} tituloProxima={tituloProxima} numeroSemana={numeroSemana} urlComunidade={urlComunidade} />
      )}
                </div>
              )}
            </li>
          )
        })}
      </ol>

    </section>
  )
}
