// Utilitários de data. Semana começa na segunda-feira.

const DIA_MS = 1000 * 60 * 60 * 24

export function diasAtras(n, base = new Date()) {
  const d = new Date(base)
  d.setHours(12, 0, 0, 0)
  d.setDate(d.getDate() - n)
  return d.toISOString()
}

export function diasAFrente(n, base = new Date()) {
  return diasAtras(-n, base)
}

/** Retorna a segunda-feira (00:00) da semana em que a data cai. */
export function inicioDaSemana(data) {
  const d = new Date(data)
  d.setHours(0, 0, 0, 0)
  const diaSemana = d.getDay() // 0 = domingo
  const ajuste = diaSemana === 0 ? -6 : 1 - diaSemana
  d.setDate(d.getDate() + ajuste)
  return d
}

/** Quantas semanas inteiras separam duas datas (pela segunda-feira de cada). */
export function semanasEntre(a, b) {
  const ia = inicioDaSemana(a).getTime()
  const ib = inicioDaSemana(b).getTime()
  return Math.round((ib - ia) / (7 * DIA_MS))
}

export function formatarData(data) {
  return new Date(data).toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })
}

export function formatarDataLonga(data) {
  return new Date(data).toLocaleDateString('pt-BR', { day: 'numeric', month: 'long' })
}

export function formatarTempo(minutos) {
  if (minutos < 60) return `${minutos} min`
  const h = Math.floor(minutos / 60)
  const m = minutos % 60
  return m === 0 ? `${h}h` : `${h}h${String(m).padStart(2, '0')}`
}
