import { useEffect, useState } from 'react'
import { Link, useParams } from 'react-router-dom'
import { encontrarLivro } from '../regras/vitrine.js'
import { redesDoAutor } from '../regras/redes.js'
import Compartilhar from '../componentes/Compartilhar.jsx'
import Capa from '../componentes/Capa.jsx'
import CabecalhoPublico from '../componentes/CabecalhoPublico.jsx'

function formatarPreco(v) {
  return v == null ? null : v.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' })
}

export default function PaginaLivro({ livros, onCapturarLeitor }) {
  const { slug } = useParams()
  const livro = encontrarLivro(livros, slug)
  const [nome, setNome] = useState('')
  const [email, setEmail] = useState('')
  const [enviado, setEnviado] = useState(false)
  const [erro, setErro] = useState('')

  useEffect(() => {
    if (!livro) return
    document.title = `${livro.titulo}, de ${livro.nomeAutor}`
    let meta = document.querySelector('meta[name="description"]')
    if (!meta) { meta = document.createElement('meta'); meta.name = 'description'; document.head.appendChild(meta) }
    meta.content = (livro.sinopse || livro.subtitulo || '').slice(0, 160)
    return () => { document.title = 'LOMBADA' }
  }, [livro])

  if (!livro) {
    return (
      <div className="min-h-screen">
        <CabecalhoPublico />
        <main className="max-w-3xl mx-auto px-6 py-16 text-center">
          <h1 className="display text-[32px]">Livro não encontrado</h1>
          <p className="text-apoio mt-3">O endereço pode estar errado ou o autor tirou o livro da vitrine.</p>
          <Link to="/vitrine" className="btn-preto inline-flex mt-6">Voltar à vitrine</Link>
        </main>
      </div>
    )
  }

  function enviar(e) {
    e.preventDefault()
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { setErro('Digite um e-mail válido.'); return }
    setErro('')
    onCapturarLeitor({ slug: livro.slug, nome: nome.trim(), email: email.trim().toLowerCase(), data: new Date().toISOString() })
    setEnviado(true)
  }

  const preco = formatarPreco(livro.precoCapa)

  return (
    <div className="min-h-screen">
      <CabecalhoPublico />
      <main className="max-w-5xl mx-auto px-6 py-8">
        <div className="flex items-center justify-between gap-4">
          <Link to="/vitrine" className="btn-linha">← Todos os livros</Link>
          {/* compartilhar fica discreto: quem chega aqui veio para conhecer o livro, não para divulgá-lo */}
          <Compartilhar
            url={window.location.href}
            titulo={`${livro.titulo}, de ${livro.nomeAutor}`}
            texto={livro.emBreve ? `Conheça ${livro.titulo}, o livro de ${livro.nomeAutor} que está chegando.` : `Conheça ${livro.titulo}, de ${livro.nomeAutor}.`}
            rotulo="Compartilhar"
            className="text-[13px] font-bold text-mudo hover:text-tinta underline underline-offset-4"
          />
        </div>

        <article className="mt-5 grid grid-cols-1 md:grid-cols-[260px_1fr]">
          <div className="bg-tinta p-8 relative z-10 md:corte-d">
            <Capa livro={livro} className="max-w-[190px]" />
          </div>
          <div className="bg-areia px-8 py-8 md:-ml-[44px] md:pl-[72px]">
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">{livro.genero}{livro.subNicho ? ` · ${livro.subNicho}` : ''}</p>
            <h1 className="display text-[36px] sm:text-[46px] mt-3 text-balance">{livro.titulo}</h1>
            {livro.subtitulo && <p className="text-[18px] font-semibold text-apoio mt-3 leading-snug">{livro.subtitulo}</p>}
            <p className="text-[13px] font-bold mt-4">por {livro.nomeAutor}</p>
            <div className="mt-6 flex flex-wrap items-center gap-4">
              {livro.emBreve ? (
                <span className="btn bg-laranja text-tinta corte-btn cursor-default">Lançamento em breve</span>
              ) : (livro.linkCompra || livro.linkVenda) ? (
                <a href={livro.linkCompra || livro.linkVenda} target="_blank" rel="noopener noreferrer sponsored" className="btn-primario !text-[14px] !px-6 !py-3">Comprar na Amazon</a>
              ) : livro.linkLoja ? (
                <a href={livro.linkLoja} target="_blank" rel="noopener noreferrer" className="btn-primario !text-[14px] !px-6 !py-3">Comprar o livro</a>
              ) : null}
              {preco && !livro.emBreve && <span className="text-[13px] font-semibold text-apoio">{preco}{livro.formato ? ` · ${livro.formato}` : ''}</span>}
            </div>
          </div>
        </article>

        <div className="grid grid-cols-1 md:grid-cols-[1fr_1fr] gap-10 mt-10">
          <div>
            {livro.sinopse && (
              <section>
                <h2 className="display text-[20px] mb-3">Sobre o livro</h2>
                <p className="text-[15px] text-apoio leading-relaxed">{livro.sinopse}</p>
              </section>
            )}
            <section className="mt-8 grid grid-cols-[auto_1fr] gap-5 items-start">
              {livro.fotoAutor ? (
                <img src={livro.fotoAutor} alt={livro.nomeAutor} loading="lazy" decoding="async" className="w-24 h-24 rounded-full object-cover border-[3px] border-tinta" />
              ) : (
                <div className="w-24 h-24 rounded-full bg-tinta text-white grid place-items-center display text-[26px]">{(livro.nomeAutor || '?').split(' ').map((n) => n[0]).slice(0, 2).join('')}</div>
              )}
              <div>
                <h2 className="display text-[20px] mb-2">Sobre {livro.nomeAutor}</h2>
                <p className="text-[15px] text-apoio leading-relaxed">{livro.bioAutor || 'Autor independente, aluno do Método The Book Business.'}</p>
                {redesDoAutor(livro.redesAutor).length > 0 && (
                  <ul className="flex flex-wrap gap-2 mt-4">
                    {redesDoAutor(livro.redesAutor).map((r) => (
                      <li key={r.chave}>
                        <a href={r.link} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1.5 border-2 border-tinta px-3 py-1.5 text-[12.5px] font-extrabold hover:bg-tinta hover:text-white transition-colors">
                          <span className="text-[10.5px] uppercase tracking-[.1em] opacity-70">{r.rotulo}</span>
                          <span>{r.texto}</span>
                        </a>
                      </li>
                    ))}
                  </ul>
                )}
              </div>
            </section>
            {livro.conquistas?.length > 0 && (
              <section className="mt-8 bg-tinta text-white px-7 py-7 corte-d">
                <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Conquistas</p>
                <ul className="mt-4 grid gap-3">
                  {livro.conquistas.map((c, i) => (
                    <li key={c.id || i} className="grid grid-cols-[22px_1fr] gap-3 items-start">
                      <i aria-hidden="true" className="mt-1 w-[18px] h-[18px] rounded-full border-[3px] border-ambar" />
                      <span className="text-[15px] font-bold leading-snug">
                        {c.texto}{c.ano ? <span className="text-white/55 font-semibold"> · {c.ano}</span> : null}
                      </span>
                    </li>
                  ))}
                </ul>
              </section>
            )}
          </div>
          <div className="grid gap-6 content-start">
            {(livro.trechos || []).length > 0 && (
              <blockquote className="bg-creme px-7 pt-7 pb-6 corte-d">
                <span className="display text-[64px] leading-[.6] block">“</span>
                <p className="font-extrabold text-[20px] leading-tight tracking-tight mt-3">{livro.trechos[0]}</p>
                {livro.trechos.slice(1, 3).map((t, i) => (
                  <p key={i} className="font-semibold text-[15px] leading-snug text-apoio mt-4 border-t-2 border-tinta/10 pt-4">{t}</p>
                ))}
                <small className="block text-[11px] font-bold uppercase tracking-[.08em] text-apoio mt-3">{livro.trechos.length === 1 ? 'Trecho do livro' : 'Trechos do livro'}</small>
              </blockquote>
            )}
            <section className="bg-tinta text-white px-7 py-7">
              <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Receba novidades deste autor</p>
              <p className="text-[14px] text-white/75 mt-2">
                {livro.emBreve ? `Seja avisado quando ${livro.titulo} for lançado.` : `Próximos lançamentos, eventos e conteúdos de ${livro.nomeAutor}, direto no seu e-mail.`}
              </p>
              {enviado ? (
                <p className="mt-4 font-bold text-ambar">Pronto. Você vai receber as novidades de {livro.nomeAutor}.</p>
              ) : (
                <form onSubmit={enviar} className="mt-4 grid gap-3">
                  <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Seu nome (opcional)" className="w-full bg-white/10 border-2 border-white/25 text-white placeholder:text-white/50 px-3 py-2.5 text-[14px] focus:outline-none focus:border-ambar" />
                  <input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Seu melhor e-mail" required className="w-full bg-white/10 border-2 border-white/25 text-white placeholder:text-white/50 px-3 py-2.5 text-[14px] focus:outline-none focus:border-ambar" />
                  <button type="submit" className="btn-primario justify-self-start">Quero receber</button>
                </form>
              )}
              {erro && <p className="text-[12px] mt-2 font-bold text-laranja">{erro}</p>}
              <p className="text-[11.5px] text-white/50 mt-4">Seu e-mail vai só para o autor. Sem spam, cancele quando quiser.</p>
            </section>
          </div>
        </div>

        <footer className="mt-14 pt-6 border-t-2 border-tinta/10 text-[12px] text-mudo leading-relaxed">
          <p>Página do autor no LOMBADA, a área do autor do Método The Book Business. <Link to="/vitrine" className="underline underline-offset-4 hover:text-tinta">Vitrine dos autores</Link> · <Link to="/privacidade" className="underline underline-offset-4 hover:text-tinta">Privacidade</Link>.</p>
          {!livro.emBreve && livro.linkCompra && livro.linkCompra !== livro.linkVenda && (
            <p className="mt-1">O botão "Comprar na Amazon" usa o link de afiliado da The Book Business: o preço para você é o mesmo, e uma pequena comissão da Amazon ajuda a manter esta vitrine.</p>
          )}
        </footer>
      </main>
    </div>
  )
}
