// Card da semana: uma imagem pronta para postar na Comunidade, no Instagram ou no WhatsApp.
// Desenhado em canvas, no estilo do LOMBADA (painéis chapados, corte diagonal, cor da fase).

import { CORES, ESTILO_FASE } from '../marca.js'
import { LIVROS_POR_FASE } from '../dados/lombadas.js'

export const FORMATOS = {
  feed: { largura: 1080, altura: 1350, nome: 'Feed (4:5)' },
  stories: { largura: 1080, altura: 1920, nome: 'Stories (9:16)' },
}

const NOME_FASE = { construcao: 'Construção', lancamento: 'Lançamento', permanencia: 'Permanência' }

/**
 * Manchete do card: sempre o que foi FEITO, nunca o que falta.
 * Ordem de força: semanas seguidas > ações feitas nesta semana > total acumulado > começo.
 */
export function manchete({ feitasNaSemana, sequencia, totalFeitas = 0 }) {
  if (sequencia >= 2) return `${sequencia} SEMANAS SEGUIDAS PELO MEU LIVRO.`
  if (feitasNaSemana >= 1) return `${feitasNaSemana} ${feitasNaSemana === 1 ? 'AÇÃO FEITA' : 'AÇÕES FEITAS'} PELO MEU LIVRO.`
  if (totalFeitas >= 1) return `${totalFeitas} ${totalFeitas === 1 ? 'AÇÃO FEITA' : 'AÇÕES FEITAS'} PELO MEU LIVRO.`
  return 'ESTA SEMANA EU TRABALHO PELO MEU LIVRO.'
}

/** Linha de apoio do card: o segundo dado mais forte, sem repetir a manchete. */
export function linhaDeApoio({ feitasNaSemana, sequencia, totalFeitas = 0 }) {
  if (sequencia >= 2 && feitasNaSemana >= 1) return `${feitasNaSemana} ${feitasNaSemana === 1 ? 'ação feita' : 'ações feitas'} esta semana · ${totalFeitas} no total.`
  if (totalFeitas > feitasNaSemana) return `${totalFeitas} ações feitas desde que comecei.`
  return 'Uma ação por vez. Toda semana.'
}

/** Texto para o post no grupo: progresso + pergunta que puxa conversa. */
export function textoComunidade({ autor, fase, feitasNaSemana, totalNaSemana, sequencia, tituloProxima, numeroSemana, totalFeitas = 0 }) {
  const primeiro = autor.nome.split(' ')[0]
  const perguntas = {
    construcao: 'Quem mais está escrevendo e já começou a divulgar antes de publicar? Como está sendo?',
    lancamento: 'Quem está em lançamento também? O que mais funcionou para vocês nas primeiras semanas?',
    permanencia: 'Quem tem livro publicado há mais tempo: o que vocês fazem para ele não cair no esquecimento?',
  }
  const linhas = [
    `Minha semana no LOMBADA pelo livro "${autor.livro.titulo}" (fase ${NOME_FASE[fase] || fase}).`,
    feitasNaSemana >= 1
      ? `Esta semana fiz ${feitasNaSemana} ${feitasNaSemana === 1 ? 'ação' : 'ações'} de divulgação${sequencia > 1 ? `, e já são ${sequencia} semanas seguidas sem parar` : ''}.`
      : sequencia > 1 ? `Já são ${sequencia} semanas seguidas trabalhando pelo livro.` : totalFeitas >= 1 ? `Já fiz ${totalFeitas} ${totalFeitas === 1 ? 'ação' : 'ações'} de divulgação até aqui.` : 'Comecei esta semana a trabalhar a divulgação.',
  ]
  if (tituloProxima) linhas.push(`A próxima: ${tituloProxima.toLowerCase()}.`)
  linhas.push('', perguntas[fase] || 'E vocês, o que fizeram pelo livro esta semana?', '', `${primeiro} · #MetodoTheBookBusiness #LOMBADA`)
  return linhas.join('\n')
}

/** Quebra um texto em linhas que cabem na largura (canvas). */
function quebrar(ctx, texto, larguraMax) {
  const palavras = String(texto).split(' ')
  const linhas = []
  let atual = ''
  for (const p of palavras) {
    const tentativa = atual ? `${atual} ${p}` : p
    if (ctx.measureText(tentativa).width > larguraMax && atual) { linhas.push(atual); atual = p } else atual = tentativa
  }
  if (atual) linhas.push(atual)
  return linhas
}

function anel(ctx, x, y, r, traco, cor) {
  ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.lineWidth = traco; ctx.strokeStyle = cor; ctx.stroke()
}

/** O anel do LOMBADA: círculo grosso com duas fendas verticais retas (em cima e embaixo). */
function anelComFendas(ctx, x, y, r, traco, cor) {
  const fenda = r * 0.3
  ctx.save()
  ctx.beginPath()
  ctx.rect(x - r - traco, y - r - traco, (r + traco) - fenda / 2, (r + traco) * 2)
  ctx.rect(x + fenda / 2, y - r - traco, (r + traco) - fenda / 2, (r + traco) * 2)
  ctx.clip()
  anel(ctx, x, y, r, traco, cor)
  ctx.restore()
}

/** Carrega as fontes usadas no card (o canvas só desenha fontes já carregadas). */
export async function prepararFontes() {
  if (!document.fonts) return
  await Promise.all([
    document.fonts.load('900 100px Archivo'), document.fonts.load('700 40px Montserrat'), document.fonts.load('600 40px Montserrat'),
  ]).catch(() => {})
}

/**
 * Desenha o card no canvas. Só usa a imagem da capa se for um arquivo do autor (data URL);
 * capa vinda de outro site mancharia o canvas e impediria o download.
 */
/**
 * Medida da capa no card sem distorcer: cabe na caixa (larguraMax × alturaMax) mantendo a proporção da imagem.
 * Capa mais alta que 2:3 encosta na altura; mais larga, encosta na largura. Sem imagem válida, devolve a caixa.
 */
export function medidaDaCapa(imgW, imgH, larguraMax, alturaMax) {
  if (!imgW || !imgH) return { w: larguraMax, h: alturaMax }
  const escala = Math.min(larguraMax / imgW, alturaMax / imgH)
  return { w: Math.round(imgW * escala), h: Math.round(imgH * escala) }
}

export function desenharCard(canvas, { autor, fase, feitasNaSemana, totalNaSemana, sequencia, numeroSemana, capaImg, totalFeitas = 0 }, formato = 'feed') {
  const { largura: W, altura: H } = FORMATOS[formato]
  canvas.width = W; canvas.height = H
  const ctx = canvas.getContext('2d')
  const est = ESTILO_FASE[fase] || ESTILO_FASE.lancamento
  const corFase = est.cor, tintaFase = est.tinta
  const M = 72 // margem

  // fundo: cor da fase
  ctx.fillStyle = corFase; ctx.fillRect(0, 0, W, H)

  // mede a manchete antes: o painel preto precisa acompanhar o texto
  const titulo = manchete({ feitasNaSemana, sequencia, totalFeitas })
  const fonteTitulo = titulo.length > 34 ? '900 96px Archivo, sans-serif' : '900 118px Archivo, sans-serif'
  const alturaLinha = titulo.length > 34 ? 98 : 118
  ctx.font = fonteTitulo
  const linhasTitulo = quebrar(ctx, titulo, W - M * 2 - 60)
  const yTitulo = M + 54 + 96 + 150
  const fimTexto = yTitulo + (linhasTitulo.length - 1) * alturaLinha + 60 // linha de apoio

  // painel preto de cima com corte diagonal (nunca menor que o texto pede)
  const hPreto = Math.max(formato === 'stories' ? H * 0.56 : H * 0.6, fimTexto + 130)
  ctx.fillStyle = CORES.tinta
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(W, 0); ctx.lineTo(W, hPreto - 90); ctx.lineTo(0, hPreto); ctx.closePath(); ctx.fill()

  // wordmark L○MBADA
  ctx.fillStyle = '#fff'; ctx.textBaseline = 'alphabetic'
  ctx.font = '900 54px Archivo, sans-serif'
  const yLogo = M + 54
  ctx.fillText('L', M, yLogo)
  const wL = ctx.measureText('L').width
  anelComFendas(ctx, M + wL + 24, yLogo - 20, 19, 6, '#fff')
  ctx.fillText('MBADA', M + wL + 50, yLogo)

  // etiqueta da semana
  ctx.font = '700 26px Montserrat, sans-serif'; ctx.fillStyle = CORES.ambar
  ctx.fillText(`FASE ${(NOME_FASE[fase] || fase).toUpperCase()}`, M, yLogo + 96)

  // manchete: sempre o que foi feito
  ctx.fillStyle = '#fff'; ctx.font = fonteTitulo
  let y = yTitulo
  for (const l of linhasTitulo) { ctx.fillText(l, M, y); y += alturaLinha }

  // linha de apoio
  ctx.font = '600 34px Montserrat, sans-serif'; ctx.fillStyle = 'rgba(255,255,255,.8)'
  ctx.fillText(linhaDeApoio({ feitasNaSemana, sequencia, totalFeitas }), M, y + 20)

  // parte de baixo (cor da fase). Feed: livro e autor à esquerda, estante com a capa à direita.
  // Stories: sobra altura, então o texto fica em cima e a estante ocupa a base inteira, maior.
  const stories = formato === 'stories'
  const escala = stories ? 1.35 : 1
  const areaW = stories ? W - M * 2 : 540, areaX = W - M - areaW
  const larguraTexto = stories ? W - M * 2 : areaX - M - 30
  const yBase = hPreto + 74
  ctx.fillStyle = tintaFase; ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'
  ctx.font = '700 24px Montserrat, sans-serif'
  ctx.fillText('MEU LIVRO', M, yBase)
  // título inteiro, em até 2 linhas: encolhe a fonte até caber, nunca corta
  let tam = 52, linhasLivro
  for (;;) {
    ctx.font = `900 ${tam}px Archivo, sans-serif`
    linhasLivro = quebrar(ctx, autor.livro.titulo.toUpperCase(), larguraTexto)
    if (linhasLivro.length <= 2 || tam <= 32) break
    tam -= 4
  }
  linhasLivro = linhasLivro.slice(0, 2)
  let yt = yBase + 14 + tam
  for (const l of linhasLivro) { ctx.fillText(l, M, yt); yt += tam + 6 }
  ctx.font = '600 26px Montserrat, sans-serif'
  const autorLinha = `${autor.nome}${autor.livro.genero ? ` · ${autor.livro.genero}` : ''}`
  ctx.fillText(quebrar(ctx, autorLinha, larguraTexto)[0], M, yt)

  // frase de fecho + hashtags. Feed: ancoradas embaixo (a frase só entra se sobrar respiro). Stories: logo abaixo do autor.
  ctx.font = '600 22px Montserrat, sans-serif'
  const tags = quebrar(ctx, '#MetodoTheBookBusiness #LOMBADA', larguraTexto).slice(0, 2)
  const yTags = stories ? yt + 100 : H - M - (tags.length - 1) * 28
  const yFrase = yTags - (tags.length - 1) * 28 - 44
  if (stories || yt < yFrase - 60) {
    ctx.font = '700 30px Montserrat, sans-serif'
    ctx.fillText('Quem conta, continua.', M, yFrase)
  }
  ctx.font = '600 22px Montserrat, sans-serif'; ctx.globalAlpha = .8
  tags.forEach((t, i) => ctx.fillText(t, M, yTags + i * 28))
  ctx.globalAlpha = 1

  // estante da fase: lombadas chapadas nas cores da marca e a capa do autor em pé, encostada
  const lombadas = LIVROS_POR_FASE[fase] || LIVROS_POR_FASE.construcao
  const areaBase = H - M + 12
  const cw = Math.round(210 * escala), ch = Math.round(315 * escala)
  const areaH = Math.min(Math.round(360 * escala), areaBase - hPreto - 40)
  const estW = areaW - cw - 30
  const somaLarg = lombadas.reduce((acc, l) => acc + l.larg, 0)
  let lx = areaX
  lombadas.forEach((l) => {
    const lw = (estW - (lombadas.length - 1) * 8) * (l.larg / somaLarg)
    if (stories && lw > 150) { /* na base larga do stories a lombada não vira uma tábua */ }
    const lh = areaH * (l.alt / 100)
    const ly = areaBase - lh
    ctx.fillStyle = l.cor
    ctx.beginPath(); ctx.roundRect(lx, ly, lw, lh, [8, 8, 0, 0]); ctx.fill()
    if (l.escuro) { ctx.lineWidth = 4; ctx.strokeStyle = CORES.tinta; ctx.stroke() }
    const filete = l.escuro ? 'rgba(20,17,15,.55)' : 'rgba(255,255,255,.75)'
    ctx.fillStyle = filete
    const fy = l.filetes === 'topo' ? ly + 26 : areaBase - 40
    ctx.fillRect(lx + 12, fy, lw - 24, 4); ctx.fillRect(lx + 12, fy + 10, lw - 24, 4)
    if (l.ponto) { ctx.fillStyle = l.escuro ? CORES.verde : CORES.creme; ctx.beginPath(); ctx.arc(lx + lw / 2, ly + 40, 11, 0, Math.PI * 2); ctx.fill() }
    // palavra em pé, encolhendo se a lombada for curta
    const tam = Math.min(Math.round(20 * escala), Math.floor((lh - 110) / (l.p.length * 0.78)))
    ctx.save()
    ctx.translate(lx + lw / 2, ly + lh / 2 + (l.ponto && l.filetes !== 'topo' ? 22 : 0)); ctx.rotate(-Math.PI / 2)
    ctx.fillStyle = l.escuro ? CORES.tinta : '#fff'; ctx.font = `800 ${tam}px Montserrat, sans-serif`; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'
    ctx.fillText(l.p, 0, 0)
    ctx.restore()
    lx += lw + 8
  })
  ctx.textAlign = 'left'; ctx.textBaseline = 'alphabetic'

  // a capa, em pé e um pouco inclinada, encostada na estante.
  // REGRA: a imagem real nunca é esticada: o quadro assume a proporção da capa (medidaDaCapa).
  const capaReal = capaImg ? medidaDaCapa(capaImg.naturalWidth || capaImg.width, capaImg.naturalHeight || capaImg.height, cw, ch) : { w: cw, h: ch }
  const cwR = capaReal.w, chR = capaReal.h
  const cx = W - M - cwR, cy = areaBase - chR - 6
  ctx.save()
  ctx.translate(cx + cwR / 2, cy + chR / 2); ctx.rotate(-3 * Math.PI / 180); ctx.translate(-(cx + cwR / 2), -(cy + chR / 2))
  ctx.fillStyle = 'rgba(20,17,15,.28)'; ctx.fillRect(cx + 14, cy + 14, cwR + 16, chR + 16)
  ctx.fillStyle = CORES.creme; ctx.fillRect(cx - 8, cy - 8, cwR + 16, chR + 16)
  if (capaImg) {
    ctx.drawImage(capaImg, cx, cy, cwR, chR)
  } else {
    ctx.fillStyle = autor.livro.capaCor || '#1a1a1a'; ctx.fillRect(cx, cy, cw, ch)
    ctx.fillStyle = '#fff'; ctx.font = '900 26px Archivo, sans-serif'
    let ty = cy + ch - 84
    const linhas = quebrar(ctx, autor.livro.titulo.toUpperCase(), cw - 36).slice(0, 4)
    ty -= (linhas.length - 1) * 28
    for (const l of linhas) { ctx.fillText(l, cx + 18, ty); ty += 28 }
    ctx.font = '600 15px Montserrat, sans-serif'; ctx.fillStyle = 'rgba(255,255,255,.85)'
    ctx.fillText(autor.nome, cx + 18, cy + ch - 30)
  }
  ctx.restore()

  return canvas
}

/** Blob PNG do card (para baixar ou compartilhar). */
export function cardParaBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'))
}
