import { uso } from '../servicos/uso.js'
import { useEffect, useRef, useState } from 'react'
import { FORMATOS, desenharCard, prepararFontes, cardParaBlob, textoComunidade } from '../regras/card.js'

/**
 * Compartilhar na Comunidade: card visual da semana (feed ou stories) + texto pronto com pergunta.
 * No celular, o botão principal usa o compartilhamento nativo já com a imagem.
 */
export default function CardSemana({ autor, fase, feitasNaSemana, totalNaSemana, sequencia, tituloProxima, numeroSemana, urlComunidade }) {
  const canvasRef = useRef(null)
  const [formato, setFormato] = useState('feed')
  const [copiado, setCopiado] = useState(false)
  const [aviso, setAviso] = useState(null)
  const totalFeitas = new Set((autor.concluidas || []).map((c) => c.acaoId)).size
  const texto = textoComunidade({ autor, fase, feitasNaSemana, totalNaSemana, sequencia, tituloProxima, numeroSemana, totalFeitas })
  const podeCompartilharArquivo = typeof navigator !== 'undefined' && typeof navigator.canShare === 'function'

  // Capa do próprio autor entra no card: base64 (cadastros antigos) ou a URL do nosso Storage
  // (carregada com crossOrigin para não manchar o canvas; o Storage libera CORS). Capa de outro site não.
  useEffect(() => {
    let vivo = true
    async function desenhar() {
      await prepararFontes()
      let capaImg = null
      const capa = autor.livro.capa || ''
      const nossa = capa.startsWith('data:') || /\/storage\/v1\/object\/public\/lombada\//.test(capa)
      if (nossa) {
        capaImg = await new Promise((ok) => { const i = new Image(); if (!capa.startsWith('data:')) i.crossOrigin = 'anonymous'; i.onload = () => ok(i); i.onerror = () => ok(null); i.src = capa })
      }
      if (vivo && canvasRef.current) desenharCard(canvasRef.current, { autor, fase, feitasNaSemana, totalNaSemana, sequencia, numeroSemana, capaImg, totalFeitas }, formato)
    }
    desenhar()
    return () => { vivo = false }
  }, [autor, fase, feitasNaSemana, totalNaSemana, sequencia, numeroSemana, formato, totalFeitas])

  const nomeArquivo = () => `lombada-semana-${numeroSemana}-${formato}.png`

  async function baixar() {
    uso('card', { acao: 'baixou', formato })
    const blob = await cardParaBlob(canvasRef.current)
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a'); a.href = url; a.download = nomeArquivo(); a.click()
    URL.revokeObjectURL(url)
    setAviso('Card salvo. Agora é só anexar no post do grupo.')
  }
  async function compartilhar() {
    uso('card', { acao: 'compartilhou', formato })
    const blob = await cardParaBlob(canvasRef.current)
    const arquivo = new File([blob], nomeArquivo(), { type: 'image/png' })
    if (podeCompartilharArquivo && navigator.canShare({ files: [arquivo] })) {
      try { await navigator.share({ files: [arquivo], text: texto }); return } catch { /* cancelou */ }
    }
    await baixar()
  }
  async function copiar() {
    uso('card', { acao: 'copiou_texto' })
    try { await navigator.clipboard.writeText(texto) } catch { /* sem clipboard */ }
    setCopiado(true); setTimeout(() => setCopiado(false), 2000)
  }

  return (
    <div className="mt-4 border-2 border-tinta grid grid-cols-1 md:grid-cols-[minmax(0,360px)_1fr]">
      {/* prévia do card */}
      <div className="bg-areia p-5 md:p-6 grid content-start gap-3">
        <div className="flex items-center justify-between gap-2">
          <p className="text-[10.5px] font-extrabold uppercase tracking-[.12em] text-mudo">Seu card da semana</p>
          <div className="inline-flex border-2 border-tinta text-[11px] font-extrabold uppercase tracking-[.06em]">
            {Object.entries(FORMATOS).map(([k, f]) => (
              <button key={k} onClick={() => setFormato(k)} className={'px-2.5 py-1 ' + (formato === k ? 'bg-tinta text-white' : 'bg-white text-tinta hover:bg-areia')}>{f.nome}</button>
            ))}
          </div>
        </div>
        <canvas ref={canvasRef} className={'w-full h-auto shadow-[10px_10px_0_0_rgba(20,17,15,.2)] ' + (formato === 'stories' ? 'max-w-[240px] mx-auto' : '')} aria-label="Card da semana" />
        <div className="flex flex-wrap gap-2">
          <button onClick={compartilhar} className="btn-preto">{podeCompartilharArquivo ? 'Compartilhar card' : 'Baixar card'}</button>
          {podeCompartilharArquivo && <button onClick={baixar} className="btn bg-white border-2 border-tinta text-tinta corte-btn">Baixar</button>}
        </div>
        {aviso && <p className="text-[12px] text-apoio">{aviso}</p>}
      </div>

      {/* texto para o grupo */}
      <div className="bg-verde text-creme px-6 py-6 md:px-8 grid content-start gap-4">
        <div>
          <p className="text-[10.5px] font-extrabold uppercase tracking-[.12em] text-ambar">Comunidade de Escritores</p>
          <p className="display text-[26px] mt-1">Quem conta, continua.</p>
        </div>
        <pre className="bg-tinta/25 px-4 py-3 text-[13px] font-sans whitespace-pre-wrap leading-relaxed">{texto}</pre>
        <div className="flex flex-wrap items-center gap-3">
          {urlComunidade && <a href={urlComunidade} target="_blank" rel="noopener noreferrer" onClick={() => uso('comunidade', { origem: 'card' })} className="btn-primario">Abrir a Comunidade ↗</a>}
          <button onClick={copiar} className="btn bg-creme text-tinta corte-btn">{copiado ? 'Copiado' : 'Copiar texto'}</button>
        </div>
      </div>
    </div>
  )
}
