import { useState } from 'react'
import { novaConquista } from '../regras/conquistas.js'

/** Janela para registrar uma conquista: frase curta e ano. Vai para a página pública e dispara a festa. */
export default function RegistroConquista({ autor, sugestao = '', onSalvar, onFechar }) {
  const [texto, setTexto] = useState(sugestao)
  const [ano, setAno] = useState(String(new Date().getFullYear()))
  const total = (autor.conquistas || []).length

  function salvar(e) {
    e.preventDefault()
    const c = novaConquista(texto, ano)
    if (!c) return
    onSalvar(c)
    onFechar()
  }

  return (
    <div className="fixed inset-0 z-40 grid place-items-center px-4 bg-tinta/70 festa-fundo" onClick={onFechar} style={{ background: 'rgba(20,17,15,.72)' }}>
      <form onSubmit={salvar} onClick={(e) => e.stopPropagation()} className="w-full max-w-lg bg-white text-tinta border-[3px] border-tinta p-6 sm:p-8 grid gap-4 surge-toast">
        <div>
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Nova conquista</p>
          <h2 className="display text-[28px] mt-1 leading-none">O que {autor.livro.titulo} conquistou?</h2>
          <p className="text-[13px] text-apoio mt-2">Prêmio, lista de mais vendidos, palestra, imprensa, exemplares. Uma frase curta. Vai para a sua página pública.</p>
        </div>
        <label className="block">
          <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1">Conquista</span>
          <input autoFocus value={texto} onChange={(e) => setTexto(e.target.value)} placeholder="Ex.: Nº 1 em Liderança na Amazon" className="campo" />
        </label>
        <label className="block max-w-[140px]">
          <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1">Ano</span>
          <input value={ano} onChange={(e) => setAno(e.target.value.replace(/\D/g, '').slice(0, 4))} inputMode="numeric" className="campo" />
        </label>
        <div className="flex flex-wrap items-center gap-3 pt-1">
          <button type="submit" disabled={!texto.trim()} className="btn-primario disabled:opacity-40">Registrar conquista</button>
          <button type="button" onClick={onFechar} className="btn-linha">cancelar</button>
          {total > 0 && <span className="text-[12px] text-mudo ml-auto">{total} já na sua página</span>}
        </div>
      </form>
    </div>
  )
}
