// Leitura pública de um livro na Amazon.com.br pela função lombada-amazon (título, autor, nota, avaliações, ranking).
// Usada no cadastro para conferir se o link é mesmo do livro do autor. Falhou? Devolve null e ninguém é bloqueado.
const URL = import.meta.env.VITE_SUPABASE_URL
export async function lerLivroAmazon(asin) {
  if (!URL || !asin) return null
  try {
    const ctrl = new AbortController(); const t = setTimeout(() => ctrl.abort(), 12000)
    const res = await fetch(`${URL}/functions/v1/lombada-amazon?asin=${encodeURIComponent(asin)}`, { signal: ctrl.signal })
    clearTimeout(t)
    if (!res.ok) return null
    const d = await res.json()
    return d && d.titulo && !d.captcha ? d : null
  } catch { return null }
}

/** Histórico diário público do livro (últimos 60 dias). */
export async function historicoAmazon(asin) {
  const CHAVE = import.meta.env.VITE_SUPABASE_ANON_KEY
  if (!URL || !CHAVE || !asin) return null
  try {
    const res = await fetch(`${URL}/rest/v1/rpc/lombada_amazon_historico`, { method: 'POST', headers: { 'Content-Type': 'application/json', apikey: CHAVE, Authorization: `Bearer ${CHAVE}` }, body: JSON.stringify({ p_asin: asin }) })
    if (!res.ok) return null
    return await res.json()
  } catch { return null }
}

/** Pede uma leitura agora e grava (o servidor recusa se já leu nas últimas 20h). */
export async function lerEGravarAmazon(asin) {
  if (!URL || !asin) return null
  try { const res = await fetch(`${URL}/functions/v1/lombada-amazon?asin=${encodeURIComponent(asin)}&gravar=1`); return res.ok ? await res.json() : null } catch { return null }
}
