import { useEffect, useState } from 'react'

/** Faixa fixa quando a internet cai: o autor sabe por que nada salva, e vê quando voltou. */
export default function AvisoOffline() {
  const [online, setOnline] = useState(typeof navigator === 'undefined' ? true : navigator.onLine)
  const [voltou, setVoltou] = useState(false)
  useEffect(() => {
    const off = () => { setOnline(false); setVoltou(false) }
    const on = () => { setOnline(true); setVoltou(true); setTimeout(() => setVoltou(false), 4000) }
    window.addEventListener('offline', off); window.addEventListener('online', on)
    return () => { window.removeEventListener('offline', off); window.removeEventListener('online', on) }
  }, [])
  if (online && !voltou) return null
  return (
    <div role="status" className={'fixed top-0 inset-x-0 z-50 text-center text-[12.5px] font-bold py-2 px-4 ' + (online ? 'bg-verde text-creme' : 'bg-tinta text-ambar')}>
      {online ? 'Internet de volta. Tudo salvo.' : 'Sem internet. Você pode continuar lendo; as mudanças são salvas quando a conexão voltar.'}
    </div>
  )
}
