/**
 * Anel de estado de uma ação (vem do "○26○" do FIRE).
 * estado: 'pendente' | 'agora' | 'feita' | 'nao_aplica'
 * 'agora' usa a cor da fase (variável --fase).
 */
export default function Anel({ numero, estado = 'pendente', tamanho = 36 }) {
  const base = 'rounded-full grid place-items-center display shrink-0'
  const porEstado = {
    pendente: 'border-[3px] border-tinta text-tinta bg-white',
    agora: 'bg-fase text-fase-tinta border-[3px] border-fase pulsa-anel',
    feita: 'bg-tinta text-white border-[3px] border-tinta',
    nao_aplica: 'border-[3px] border-dashed border-fio text-mudo bg-white',
  }
  return (
    <span key={estado} className={`${base} ${porEstado[estado] || porEstado.pendente} ${estado === 'feita' ? 'pop' : ''}`} style={{ width: tamanho, height: tamanho, fontSize: tamanho * 0.44, letterSpacing: '-0.02em' }}>
      {numero}
    </span>
  )
}
