import { uso } from '../servicos/uso.js'
import { useState } from 'react'
import { filtrarOportunidades, DIAS_PARA_DESTAQUE } from '../regras/oportunidades.js'
import { formatarDataLonga } from '../regras/datas.js'
import { datasComoOportunidades } from '../regras/datas_comemorativas.js'

function rotuloPrazo(o) {
  const d = o.diasRestantes
  const verbo = o.tipoPrazo === 'evento' || o.tipoPrazo === 'data' ? 'É' : 'Vence'
  if (d === 0) return `${verbo} hoje`
  if (d === 1) return `${verbo} amanhã`
  return `${verbo === 'É' ? 'Em' : 'Vence em'} ${d} dias`
}

const TIPOS = [
  { id: 'tudo', rotulo: 'Tudo' },
  { id: 'chamadas', rotulo: 'Prêmios, feiras e editais' },
  { id: 'datas', rotulo: 'Datas comemorativas' },
]

export default function Oportunidades({ autor, oportunidades, onVoltar }) {
  const [todosGeneros, setTodosGeneros] = useState(false)
  const [tipoFiltro, setTipoFiltro] = useState('tudo')
  const genero = autor.livro.genero
  const hoje = new Date()
  const fonte = tipoFiltro === 'chamadas' ? oportunidades : tipoFiltro === 'datas' ? datasComoOportunidades(hoje) : [...oportunidades, ...datasComoOportunidades(hoje)]
  const lista = filtrarOportunidades(fonte, genero, hoje, { todosGeneros }).filter((o) => tipoFiltro !== 'tudo' || o.tipoPrazo !== 'data' || o.diasRestantes <= 120)
  const urgentes = lista.filter((o) => o.destaque && o.tipoPrazo !== 'data').length

  return (
    <div>
      <button onClick={onVoltar} className="btn-linha">← Voltar ao plano da semana</button>
      <header className="mt-5 bg-tinta text-white px-8 py-8 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Central de Oportunidades</p>
        <h1 className="display text-[34px] sm:text-[42px] mt-3 text-balance">Prêmios, feiras, editais e datas {todosGeneros ? 'do ano' : `para ${genero}`}</h1>
        <p className="text-[13.5px] text-white/75 mt-3 font-semibold">
          {lista.length === 0 ? 'Nada no radar agora.' : `${lista.length} no radar`}{urgentes ? ` · ${urgentes} ${urgentes === 1 ? 'vence' : 'vencem'} em até ${DIAS_PARA_DESTAQUE} dias` : ''}
        </p>
      </header>

      <div className="mt-6 flex flex-wrap items-center gap-2 text-[12.5px]">
        {TIPOS.map((t) => (
          <button key={t.id} onClick={() => setTipoFiltro(t.id)} className={'font-bold px-4 py-2 corte-btn transition-colors ' + (tipoFiltro === t.id ? 'bg-tinta text-white' : 'bg-areia text-apoio hover:bg-fio')}>{t.rotulo}</button>
        ))}
      </div>
      <div className="mt-2 flex flex-wrap items-center gap-2 text-[12.5px]">
        {[{ valor: false, rotulo: `Só ${genero}` }, { valor: true, rotulo: 'Todos os gêneros' }].map((op) => (
          <button key={String(op.valor)} onClick={() => setTodosGeneros(op.valor)} className={'font-bold px-4 py-2 corte-btn transition-colors ' + (todosGeneros === op.valor ? 'bg-tinta text-white' : 'bg-areia text-apoio hover:bg-fio')}>{op.rotulo}</button>
        ))}
      </div>

      {lista.length === 0 && <div className="bg-areia px-6 py-6 mt-4 text-[14px] text-apoio">Nada para {genero} neste filtro.</div>}

      <ul className="mt-8 grid gap-4">
        {lista.map((o) => (
          <li key={o.id} className={'relative pl-8 pr-5 py-5 ' + (o.destaque ? 'bg-white border-2 border-alerta' : 'bg-areia')}>
            <i className={'absolute left-0 top-0 bottom-0 w-4 ' + (o.destaque && o.tipoPrazo !== 'data' ? 'bg-alerta' : o.tipoPrazo === 'data' ? 'bg-ambar' : 'bg-fio')} style={{ clipPath: 'polygon(0 0, 100% 0, 40% 100%, 0 100%)' }} />
            <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
              <div className="flex flex-wrap items-baseline gap-3">
                <span className="text-[11px] font-extrabold uppercase tracking-[.12em] text-mudo">{o.tipo}</span>
                <h2 className="font-bold text-[16px] tracking-tight">{o.nome}</h2>
              </div>
              <span className={'text-[12px] font-extrabold uppercase tracking-[.08em] shrink-0 ' + (o.destaque && o.tipoPrazo !== 'data' ? 'text-alerta' : 'text-mudo')}>{rotuloPrazo(o)}</span>
            </div>
            <p className="text-[13.5px] text-apoio mt-2 leading-relaxed max-w-[70ch]">{o.descricao}</p>
            <div className="flex flex-wrap items-center justify-between gap-3 mt-4 text-[12.5px]">
              <span className="text-mudo font-semibold">
                {o.tipoPrazo === 'data'
                  ? (o.foco === 'promocao' ? 'Data de promoção' : 'Data de relacionamento')
                  : `${o.tipoPrazo === 'evento' ? 'Acontece a partir de' : o.tipoPrazo === 'acompanhar' ? 'Acompanhe até' : 'Inscrições até'} ${formatarDataLonga(o.prazo)}`}
                {o.estimado && <span className="text-ambar"> · data prevista pela edição anterior, confirme no site</span>}
                {o.janela && !o.estimado && o.tipoPrazo === 'evento' && <span> · {o.janela}</span>}
                {todosGeneros && <span> · {o.generos.length >= 8 ? 'todos os gêneros' : o.generos.join(', ')}</span>}
              </span>
              {o.link
                ? <a href={o.link} target="_blank" rel="noopener noreferrer" onClick={() => uso('oportunidade', { id: o.id, nome: o.nome })} className={o.destaque && o.tipoPrazo !== 'data' ? 'btn bg-alerta text-white corte-btn' : 'btn-preto'}>{o.tipoPrazo === 'evento' ? 'Ver o evento' : 'Ver e inscrever-se'}</a>
                : <span className="text-[11px] font-extrabold uppercase tracking-[.1em] text-mudo">Aula 4: microciclos e datas</span>}
            </div>
          </li>
        ))}
      </ul>
    </div>
  )
}
