// Trechos do livro: o autor cadastra vários; o LOMBADA gira um por semana
// (citação do plano, variável {trecho} nos textos, página pública).
import { inicioDaSemana } from './datas.js'

/** Lista limpa de trechos: `livro.trechos` mais o antigo `livro.trecho`, sem vazios nem repetidos. */
export function listaTrechos(livro) {
  const todos = [...(livro?.trechos || []).map((t) => (typeof t === 'string' ? t : t?.texto)), livro?.trecho]
  const vistos = new Set()
  return todos.map((t) => String(t || '').trim()).filter((t) => t && !vistos.has(t.toLowerCase()) && vistos.add(t.toLowerCase()))
}

/** Índice da semana (estável ao longo da semana, muda na segunda). */
function numeroDaSemana(hoje) {
  return Math.floor(inicioDaSemana(hoje).getTime() / (7 * 86400000))
}

/** O trecho desta semana: roda pela lista, um por semana. `deslocamento` permite "outro trecho". */
export function trechoDaSemana(livro, hoje = new Date(), deslocamento = 0) {
  const lista = listaTrechos(livro)
  if (lista.length === 0) return ''
  const n = lista.length
  return lista[(((numeroDaSemana(hoje) + deslocamento) % n) + n) % n]
}
