// A jornada do autor em três fases e o próximo marco. Uma função, sem interface.
import { FASES } from './fase.js'
import { formatarDataLonga } from './datas.js'

export const ETAPAS = [FASES.CONSTRUCAO, FASES.LANCAMENTO, FASES.PERMANENCIA]
const DIAS_LANCAMENTO = 90

function dias(a, b) { return Math.floor((b - new Date(a)) / 86400000) }

/**
 * @returns {{ etapaAtual: number, marco: string, detalhe: string }}
 *  marcoTitulo: a manchete curta (ex.: "Lançamento 29 de outubro"); marco: a frase de apoio; detalhe: onde a pessoa está hoje.
 */
export function situacaoNaJornada(autor, fase, hoje = new Date()) {
  const etapaAtual = Math.max(0, ETAPAS.indexOf(fase))
  const titulo = autor.livro.titulo
  if (fase === FASES.CONSTRUCAO) {
    const d = dias(autor.cadastradoEm, hoje)
    const prev = autor.livro.dataLancamentoPrevista ? -dias(autor.livro.dataLancamentoPrevista, hoje) : null
    const marcoTitulo = prev === null ? 'Livro ainda não publicado' : `Lançamento ${formatarDataLonga(autor.livro.dataLancamentoPrevista)}`
    const marco = prev === null
      ? `Próximo marco: publicar ${titulo}.`
      : prev > 0 ? `Faltam ${prev} ${prev === 1 ? 'dia' : 'dias'} para ${titulo} sair.`
      : prev === 0 ? `É hoje: ${titulo} sai.` : `A data passou. Publicou? Marque no cadastro.`
    return {
      etapaAtual,
      detalhe: d <= 0 ? 'Você entrou hoje. O livro ainda não foi publicado.' : `Há ${d} ${d === 1 ? 'dia' : 'dias'} preparando o terreno. O livro ainda não foi publicado.`,
      marcoTitulo,
      marco,
      diasParaLancamento: prev,
    }
  }
  if (fase === FASES.LANCAMENTO) {
    const d = Math.max(0, dias(autor.livro.dataPublicacao, hoje))
    const faltam = Math.max(0, DIAS_LANCAMENTO - d)
    return {
      etapaAtual,
      detalhe: `${titulo} está publicado há ${d} ${d === 1 ? 'dia' : 'dias'}. Estes 90 primeiros dias decidem a tração.`,
      marcoTitulo: `Publicado há ${d} ${d === 1 ? 'dia' : 'dias'}`,
      marco: faltam > 0 ? `Faltam ${faltam} ${faltam === 1 ? 'dia' : 'dias'} para entrar em Permanência.` : 'Próximo marco: entrar em Permanência.',
    }
  }
  const d = Math.max(0, dias(autor.livro.dataPublicacao, hoje))
  const meses = Math.floor(d / 30)
  return {
    etapaAtual,
    detalhe: `${titulo} está publicado há ${meses >= 2 ? `${meses} meses` : `${d} dias`}. Fase final: o livro que fica.`,
    marcoTitulo: `Publicado há ${meses >= 2 ? `${meses} meses` : `${d} dias`}`,
    marco: 'Um microciclo por mês mantém o livro lembrado.',
  }
}
