import { formatarDataLonga } from '../regras/datas.js'

/** Momento de virada: aparece na primeira visita de uma semana nova, com o resumo da anterior. */
export default function NovaSemana({ inicioSemana, semanaPassada, sequencia, primeiroNome, onFechar }) {
  const fezAlgo = semanaPassada.acoes > 0 || semanaPassada.checkins > 0
  return (
    <div className="bg-ambar text-tinta px-7 py-6 mb-8 corte-d flex flex-wrap items-start justify-between gap-4">
      <div>
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em]">Semana nova · {formatarDataLonga(inicioSemana)}</p>
        <p className="display text-[26px] mt-2">
          {fezAlgo ? `${primeiroNome}, semana passada você fez ${semanaPassada.acoes} ${semanaPassada.acoes === 1 ? 'ação' : 'ações'}${semanaPassada.checkins ? ` e ${semanaPassada.checkins} check-in` : ''}.` : `${primeiroNome}, semana nova, plano novo.`}
        </p>
      </div>
      <button onClick={onFechar} className="btn-preto">Ver o plano</button>
    </div>
  )
}
