// Ponte entre o campo de imagem e a nuvem: quando o autor está logado na nuvem,
// a imagem otimizada sobe para o Storage e o cadastro guarda só a URL.
// Sem nuvem (protótipo, ou antes de entrar), fica o data URL mesmo.
let enviar = null
export function configurarEnvioDeImagem(fn) { enviar = fn }
export const ehDataUrl = (v) => typeof v === 'string' && v.startsWith('data:')
/** Devolve URL pública se houver envio configurado; senão devolve o próprio data URL. */
export async function guardarImagem(dataUrl, tipo) {
  if (!enviar || !ehDataUrl(dataUrl)) return dataUrl
  try { return await enviar(tipo, dataUrl) } catch { return dataUrl }
}
