import { useState, useEffect, useRef, useCallback, lazy, Suspense } from 'react'
import { BrowserRouter, Routes, Route } from 'react-router-dom'
import { ACOES, MODELOS, OPORTUNIDADES } from './dados/exemplo.js'
import { montarVitrine, slugify } from './regras/vitrine.js'
import { lerUI, gravarUI } from './regras/persistencia.js'
import { nuvem, lerSessao, gravarSessao, apagarSessao, normalizarAutor } from './servicos/nuvem.js'
import { definirCatalogoAulas } from './regras/aulas.js'
import { sincronizarLivros } from './regras/livros.js'
import { configurarEnvioDeImagem, ehDataUrl } from './servicos/imagens.js'
import { configurarUso, uso, despachar } from './servicos/uso.js'
import { AreaLogada } from './App.jsx'
import Entrar from './telas/Entrar.jsx'
import Comecar from './telas/Comecar.jsx'
const EntrarVersoes = lazy(() => import('./telas/EntrarVersoes.jsx'))
const Legal = lazy(() => import('./telas/Legal.jsx'))
import Vitrine from './telas/Vitrine.jsx'
import PaginaLivro from './telas/PaginaLivro.jsx'
import CadastroLivro from './telas/CadastroLivro.jsx'
const AdminNuvem = lazy(() => import('./telas/AdminNuvem.jsx'))
import Wordmark from './componentes/Wordmark.jsx'

/** Catálogo: o do código, sobrescrito pelo que a equipe editou no Admin (tabela lombada_catalogo). */
function useCatalogo() {
  const [cat, setCat] = useState({ acoes: ACOES, modelos: MODELOS, oportunidades: OPORTUNIDADES })
  useEffect(() => {
    nuvem.configPublica().then((cfg) => setCat((atual) => ({ ...atual, configPublica: cfg || {} }))).catch(() => {})
    nuvem.catalogo().then((c) => {
      definirCatalogoAulas(c?.aulas)
      setCat((atual) => ({ acoes: c?.acoes || atual.acoes, modelos: c?.modelos || atual.modelos, oportunidades: c?.oportunidades || atual.oportunidades, aulasEm: c?.aulas?.SINCRONIZACAO?.em || null }))
    }).catch(() => {})
  }, [])
  return cat
}

/** Vitrine pública lida da nuvem. */
function VitrineNuvem({ pagina }) {
  const [livros, setLivros] = useState(null)
  useEffect(() => { nuvem.vitrine().then((autores) => setLivros(montarVitrine(autores || []))).catch(() => setLivros([])) }, [])
  if (livros === null) return <Carregando />
  if (pagina) return <PaginaLivro livros={livros} onCapturarLeitor={(l) => nuvem.captarLeitor(l.slug, l.nome, l.email).catch(() => {})} />
  return <Vitrine livros={livros} />
}

function Carregando({ texto = 'Abrindo o LOMBADA…' }) {
  return (
    <div className="min-h-screen grid place-items-center">
      <div className="text-center">
        <Wordmark tamanho={28} />
        <p className="text-[13px] text-mudo mt-3">{texto}</p>
      </div>
    </div>
  )
}

export default function AppNuvem() {
  const catalogo = useCatalogo()
  return (
    <BrowserRouter basename={import.meta.env.BASE_URL.replace(/\/$/, '')}>
      <Routes>
        <Route path="/comecar" element={<Comecar />} />
        <Route path="/versoes-entrar" element={<Suspense fallback={null}><EntrarVersoes /></Suspense>} />
        <Route path="/termos" element={<Suspense fallback={null}><Legal tipo="termos" /></Suspense>} />
        <Route path="/privacidade" element={<Suspense fallback={null}><Legal tipo="privacidade" /></Suspense>} />
        <Route path="/vitrine" element={<VitrineNuvem />} />
        <Route path="/livro/:slug" element={<VitrineNuvem pagina />} />
        <Route path="/admin" element={<Suspense fallback={null}><AdminNuvem catalogoPadrao={catalogo} /></Suspense>} />
        <Route path="/*" element={<AutorNuvem catalogo={catalogo} />} />
      </Routes>
    </BrowserRouter>
  )
}

/** Área do autor na nuvem: sessão por token, autor carregado do banco, salvo a cada mudança. */
function AutorNuvem({ catalogo }) {
  const [token, setToken] = useState(lerSessao)
  const [autor, setAutor] = useState(null)
  const [estado, setEstado] = useState(token ? 'carregando' : 'entrar') // carregando | entrar | cadastro | pronto
  const [erro, setErro] = useState('')
  const [ocupado, setOcupado] = useState(false)
  const [leitores, setLeitores] = useState([])
  const [sugestoes, setSugestoes] = useState([])
  const [salvando, setSalvando] = useState(null) // null | 'salvando' | 'erro'
  const carregouEm = useRef(0)

  // quem veio de /comecar cai direto no cadastro
  useEffect(() => { if (!token && lerUI().abrirCadastro) { gravarUI({ abrirCadastro: false, modoAluno: false }); setEstado('cadastro') } }, [token])

  // carrega o autor da sessão
  useEffect(() => {
    if (!token) return
    let vivo = true
    setEstado('carregando')
    nuvem.meu(token)
      .then(async (dados) => {
        if (!vivo) return
        setAutor(normalizarAutor(dados)); carregouEm.current = Date.now(); setEstado('pronto')
        nuvem.leitores(token).then((l) => vivo && setLeitores(l || [])).catch(() => {})
        nuvem.minhasSugestoes(token).then((s) => vivo && setSugestoes(s || [])).catch(() => {})
      })
      .catch(() => { if (!vivo) return; apagarSessao(); setToken(null); setAutor(null); setEstado('entrar') })
    return () => { vivo = false }
  }, [token])

  // medição de uso: só com sessão; marca por onde o autor entrou (?de=email vem do e-mail da segunda)
  useEffect(() => {
    configurarUso(token ? (lote) => nuvem.eventos(token, lote) : null)
    if (token) {
      const origem = new URLSearchParams(window.location.search).get('de')
      uso('entrou', { origem: origem || 'direto' })
      if (origem) window.history.replaceState(null, '', window.location.pathname)
    }
    return () => { despachar(); configurarUso(null) }
  }, [token])

  // imagens: com sessão, capa e foto sobem para o Storage (o cadastro guarda só a URL)
  useEffect(() => {
    configurarEnvioDeImagem(token ? (tipo, dataUrl) => nuvem.enviarImagem(token, tipo, dataUrl) : null)
    return () => configurarEnvioDeImagem(null)
  }, [token])

  // cadastros antigos com imagem em base64: migra para o Storage na primeira abertura
  useEffect(() => {
    if (!token || !autor || estado !== 'pronto') return
    const pendentes = [['foto', autor.foto], ['capa', autor.livro?.capa]].filter(([, v]) => ehDataUrl(v))
    if (!pendentes.length) return
    let vivo = true
    Promise.all(pendentes.map(([tipo, v]) => nuvem.enviarImagem(token, tipo, v).then((url) => [tipo, url]).catch(() => null)))
      .then((res) => {
        if (!vivo) return
        const ok = Object.fromEntries(res.filter(Boolean))
        if (!Object.keys(ok).length) return
        setAutor((a) => ({ ...a, ...(ok.foto ? { foto: ok.foto } : {}), livro: { ...a.livro, ...(ok.capa ? { capa: ok.capa } : {}) } }))
      })
    return () => { vivo = false }
  }, [token, autor?.foto, autor?.livro?.capa, estado])

  // salva a cada mudança do autor (com pequena espera para agrupar cliques)
  useEffect(() => {
    if (!token || !autor || estado !== 'pronto' || Date.now() - carregouEm.current < 800) return
    setSalvando('salvando')
    const t = setTimeout(() => {
      nuvem.salvar(token, { ...sincronizarLivros(autor), slug: autor.livro?.slug || slugify(autor.livro?.titulo || '') })
        .then((salvo) => { setSalvando(null); if (salvo?.cadastro && JSON.stringify(salvo.cadastro) !== JSON.stringify(autor.cadastro)) setAutor((a) => ({ ...a, cadastro: salvo.cadastro })) })
        .catch(() => setSalvando('erro'))
    }, 700)
    return () => clearTimeout(t)
  }, [autor, token, estado])

  async function entrar(email, codigo) {
    setOcupado(true); setErro('')
    try {
      const r = await nuvem.entrar(email, codigo)
      gravarSessao(r.token); setAutor(normalizarAutor(r.autor)); carregouEm.current = Date.now(); setToken(r.token); setEstado('pronto')
    } catch (e) { setErro(e.message) } finally { setOcupado(false) }
  }

  async function cadastrar(dados) {
    setOcupado(true); setErro('')
    try {
      const r = await nuvem.cadastrar({ ...dados, slug: slugify(dados.livro?.titulo || '') })
      gravarSessao(r.token); setAutor(normalizarAutor(r.autor)); carregouEm.current = Date.now(); setToken(r.token); setEstado('pronto')
    } catch (e) { setErro(e.message); window.alert(e.message) } finally { setOcupado(false) }
  }

  function sair() {
    if (token) nuvem.sair(token).catch(() => {})
    apagarSessao(); setToken(null); setAutor(null); setLeitores([]); setSugestoes([]); setEstado('entrar')
  }

  const enviarSugestao = useCallback(async (_autorId, texto) => {
    await nuvem.sugerir(token, texto)
    setSugestoes(await nuvem.minhasSugestoes(token))
  }, [token])

  if (estado === 'carregando') return <Carregando />
  if (estado === 'cadastro') {
    return (
      <div className="min-h-screen">
        <div className="border-b-2 border-tinta"><div className="max-w-4xl mx-auto px-4 sm:px-6 py-4"><Wordmark tamanho={24} /></div></div>
        <main className="max-w-4xl mx-auto px-4 sm:px-6 py-8">
          <CadastroLivro inicial={null} onSalvar={cadastrar} onCancelar={() => setEstado('entrar')} />
        </main>
      </div>
    )
  }
  if (estado === 'entrar' || !autor) return <Entrar onEntrar={entrar} onCadastrar={() => setEstado('cadastro')} erro={erro} carregando={ocupado} />

  const setAutores = (fn) => setAutor((a) => (typeof fn === 'function' ? fn([a])[0] : fn[0]) || a)
  return (
    <>
      <AreaLogada
        autores={[autor]}
        setAutores={setAutores}
        leitores={leitores}
        acoes={catalogo.acoes}
        modelos={catalogo.modelos}
        oportunidades={catalogo.oportunidades}
        sugestoes={sugestoes}
        onEnviarSugestao={enviarSugestao}
        nuvem
        onSair={sair}
        onApagarConta={async () => { await nuvem.apagarConta(token); sair() }}
        urlCheckoutLivro={catalogo.configPublica?.url_checkout_livro || ''}
        onTrocarCodigo={(atual, novo) => nuvem.trocarCodigo(token, atual, novo)}
      />
      {salvando === 'erro' && <div className="fixed bottom-4 left-1/2 -translate-x-1/2 bg-alerta text-white px-4 py-2 text-[12.5px] font-bold corte-btn z-40">Não consegui salvar. Confira a internet; tento de novo na próxima mudança.</div>}
    </>
  )
}
