// Redes sociais do autor. O autor digita como quiser (@nome, nome ou link); aqui vira link e rótulo.
export const REDES_SOCIAIS = [
  { chave: 'instagram', rotulo: 'Instagram', base: 'https://instagram.com/', exemplo: '@seunome' },
  { chave: 'youtube', rotulo: 'YouTube', base: 'https://youtube.com/@', exemplo: '@seucanal ou link' },
  { chave: 'linkedin', rotulo: 'LinkedIn', base: 'https://linkedin.com/in/', exemplo: 'seu-nome ou link' },
  { chave: 'tiktok', rotulo: 'TikTok', base: 'https://tiktok.com/@', exemplo: '@seunome' },
  { chave: 'site', rotulo: 'Site', base: 'https://', exemplo: 'seusite.com.br' },
]

/** Link completo a partir do que o autor digitou. Vazio devolve null. */
export function linkDaRede(chave, valor) {
  const v = String(valor || '').trim()
  if (!v) return null
  if (/^https?:\/\//i.test(v)) return v
  const rede = REDES_SOCIAIS.find((r) => r.chave === chave)
  if (!rede) return null
  if (chave === 'site') return 'https://' + v.replace(/^\/+/, '')
  const usuario = v.replace(/^@/, '').replace(/^.*\.com\//i, '').replace(/^(in|@)\//, '').replace(/\/+$/, '')
  return rede.base + usuario
}

/** Texto curto para mostrar ao lado do ícone: "@camila" ou "seusite.com.br". */
export function rotuloDaRede(chave, valor) {
  const v = String(valor || '').trim()
  if (!v) return ''
  if (chave === 'site') return v.replace(/^https?:\/\//i, '').replace(/\/+$/, '')
  const usuario = v.replace(/^https?:\/\/[^/]+\//i, '').replace(/^(in|@)\//, '').replace(/^@/, '').replace(/\/+$/, '')
  return '@' + usuario
}

/** Lista pronta para a página pública: só as preenchidas. */
export function redesDoAutor(redes = {}) {
  return REDES_SOCIAIS
    .map((r) => ({ ...r, valor: redes[r.chave], link: linkDaRede(r.chave, redes[r.chave]), texto: rotuloDaRede(r.chave, redes[r.chave]) }))
    .filter((r) => r.link)
}
