import { linkAfiliado } from './amazon.js'
import { AMAZON_TAG_AFILIADO, AFILIADO_NOS_TEXTOS_DO_AUTOR } from '../marca.js'
import { trechoDaSemana } from './trechos.js'
// Substituição das variáveis dos modelos de texto.
// Única função responsável por isso. Para criar uma variável nova,
// basta adicionar uma linha em VARIAVEIS.

export const VARIAVEIS = {
  titulo_livro: { descricao: 'Título do livro', obter: (autor) => autor.livro.titulo },
  subtitulo: { descricao: 'Subtítulo do livro', obter: (autor) => autor.livro.subtitulo },
  genero: { descricao: 'Gênero', obter: (autor) => autor.livro.genero },
  publico_alvo: { descricao: 'Público-alvo', obter: (autor) => autor.livro.publicoAlvo },
  nome_autor: { descricao: 'Nome do autor', obter: (autor) => autor.nome },
  link_venda: { descricao: 'Link de venda', obter: (autor) => (AFILIADO_NOS_TEXTOS_DO_AUTOR ? linkAfiliado(autor.livro.linkVenda, AMAZON_TAG_AFILIADO) : autor.livro.linkVenda) },
  // Variáveis que vêm do próprio livro (voz do autor, não da plataforma)
  promessa: { descricao: 'Promessa do livro em uma frase', obter: (autor) => autor.livro.promessa },
  trecho: { descricao: 'Trecho do livro (gira a cada semana)', obter: (autor) => trechoDaSemana(autor.livro) },
  sinopse: { descricao: 'Sinopse', obter: (autor) => autor.livro.sinopse },
  cidade: { descricao: 'Cidade do autor', obter: (autor) => soCidade(autor.cidade) },
  primeiro_nome: { descricao: 'Primeiro nome do autor', obter: (autor) => (autor.nome || '').trim().split(/\s+/)[0] },
  sub_nicho: { descricao: 'Sub-nicho do livro', obter: (autor) => minusculaInicial(autor.livro.subNicho) },
  tema: { descricao: 'Tema do livro (sub-nicho ou gênero)', obter: (autor) => minusculaInicial(autor.livro.subNicho || autor.livro.genero) },
  profissao: { descricao: 'Profissão do autor', obter: (autor) => minusculaInicial(autor.profissao) },
}

/**
 * Preenche um texto com os dados do autor.
 * Sintaxe: {variavel} ou {variavel|texto usado se faltar}.
 * Sem texto alternativo, a variável vazia fica marcada como [variavel] para o autor perceber.
 * @returns {{ texto: string, faltando: string[] }}
 */
export function preencherModelo(texto, autor) {
  const faltando = new Set()
  const preenchido = (texto || '').replace(/\{([a-z_]+)(?:\|([^{}]*))?\}/g, (marcador, nome, alternativo) => {
    const variavel = VARIAVEIS[nome]
    if (!variavel) return marcador // variável desconhecida: deixa como está
    const valor = variavel.obter(autor)
    if (valor === undefined || valor === null || String(valor).trim() === '') {
      if (alternativo !== undefined) return alternativo
      faltando.add(nome)
      return `[${nome}]`
    }
    return String(valor)
  })
  return { texto: preenchido, faltando: [...faltando] }
}

/**
 * Título e descrição de uma ação escritos para este autor.
 * As ações usam sempre {variavel|alternativa}, então nunca aparece colchete aqui.
 */
export function personalizarAcao(acao, autor) {
  if (!autor) return { titulo: acao.titulo, descricao: acao.descricao }
  return {
    titulo: preencherModelo(acao.titulo, autor).texto,
    descricao: preencherModelo(acao.descricao, autor).texto,
  }
}

/** "Curitiba, PR" -> "Curitiba". */
function soCidade(c) {
  return c ? String(c).split(',')[0].trim() : c
}

/** "Consultor de gestão" -> "consultor de gestão" (mantém siglas como "CEO"). */
function minusculaInicial(t) {
  if (!t) return t
  return /^[A-ZÀ-Ü][a-zà-ü]/.test(t) ? t[0].toLowerCase() + t.slice(1) : t
}
