import { uso } from '../servicos/uso.js'
import { aulasNovas, sincronizacao } from '../regras/aulas.js'
import { BANNERS } from '../dados/exemplo.js'
import { formatarData } from '../regras/datas.js'

/** Bloco do Método The Book Business: últimas aulas (esquerda) + área de membros e Comunidade (direita). */
export default function NovasAulas({ onVerTodas }) {
  const SINCRONIZACAO = sincronizacao()
  const novas = aulasNovas(3)
  const primeiraLeitura = (SINCRONIZACAO.novas || []).length === 0
  const metodo = BANNERS.find((b) => b.id === 'mtbb')
  const comunidade = BANNERS.find((b) => b.id === 'comunidade')
  return (
    <section className="mt-14 entra atraso-6 grid grid-cols-1 md:grid-cols-[1.4fr_1fr]">
      <div className="bg-tinta text-white px-7 py-7 relative z-10 md:corte-d">
        <div className="flex flex-wrap items-baseline justify-between gap-2">
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Método The Book Business</p>
          <p className="text-[11px] text-white/50 font-semibold">atualizado em {formatarData(SINCRONIZACAO.em)}</p>
        </div>
        <h2 className="display text-[24px] mt-2">{primeiraLeitura ? 'Últimas aulas adicionadas' : 'Novas aulas desde a sua última visita'}</h2>
        <ul className="mt-5 grid gap-2">
          {novas.map((a, i) => (
            <li key={a.id}>
              <a href={a.url} target="_blank" rel="noopener noreferrer" onClick={() => uso('aula', { pageId: a.id, nome: a.nome, origem: 'novas' })} className="group grid grid-cols-[10px_1fr_auto] gap-3 items-baseline px-3 py-2.5 bg-white/5 hover:bg-white/10 transition-colors">
                <i className="w-2.5 h-2.5 rounded-full bg-ambar relative top-[1px] pisca" style={{ animationDelay: `${i * 0.4}s` }} />
                <span className="font-bold text-[13.5px] leading-snug">{a.nome}<span className="block text-[11px] font-semibold text-white/50 mt-0.5">{a.modulo}</span></span>
                <span className="text-[10.5px] font-extrabold uppercase tracking-[.1em] text-ambar group-hover:underline underline-offset-4">Assistir ↗</span>
              </a>
            </li>
          ))}
        </ul>
        <div className="mt-4 flex flex-wrap gap-4 items-center">
          <button onClick={onVerTodas} className="btn bg-ambar text-tinta corte-btn">Ver todas as aulas</button>
          {metodo && <a href={metodo.url} target="_blank" rel="noopener noreferrer" className="text-[12.5px] font-bold text-white/70 hover:text-white">Área de membros ↗</a>}
        </div>
      </div>
      {comunidade && (
        <a href={comunidade.url} target="_blank" rel="noopener noreferrer" onClick={() => uso('comunidade', { origem: 'bloco' })} className="group bg-ambar text-tinta px-7 py-7 md:-ml-[44px] md:pl-[72px] grid content-between gap-5 hover:bg-laranja transition-colors">
          <div>
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em]">{comunidade.kicker}</p>
            <p className="display text-[64px] sm:text-[76px] leading-[.9] mt-3 tracking-tight">{comunidade.numero}</p>
            <p className="text-[13px] font-extrabold uppercase tracking-[.1em] mt-1">{comunidade.unidade}</p>
            <p className="display text-[22px] leading-[1.05] mt-4 text-balance">{comunidade.titulo}</p>
          </div>
          <span className="btn bg-tinta text-white corte-btn justify-self-start group-hover:translate-x-1 transition-transform">{comunidade.cta} ↗</span>
        </a>
      )}
    </section>
  )
}
