// Nome e cores do produto. Único lugar para trocar.
export const NOME_PRODUTO = 'LOMBADA'
export const DESCRICAO_PRODUTO = 'A área do autor do Método The Book Business'

// Paleta MTBB (das páginas de venda do perpétuo)
export const CORES = {
  tinta: '#1a1a1a',
  creme: '#f3f0e8',
  ambar: '#faab00',
  laranja: '#fc783c',
  verde: '#14523e',
  alerta: '#cc3333', // só urgência (prazo em 7 dias)
}

// Uma cor por fase. `tinta` é a cor do texto sobre a cor da fase.
export const ESTILO_FASE = {
  construcao: { cor: CORES.verde, tinta: CORES.creme, nome: 'verde' },
  lancamento: { cor: CORES.laranja, tinta: CORES.tinta, nome: 'laranja' },
  permanencia: { cor: CORES.ambar, tinta: CORES.tinta, nome: 'âmbar' },
}

/** Variáveis CSS da fase, para usar em style={estiloFase(fase)}. */
export function estiloFase(fase) {
  const e = ESTILO_FASE[fase] || ESTILO_FASE.permanencia
  return { '--fase': e.cor, '--fase-tinta': e.tinta }
}

// Área de membros do Método The Book Business na Hotmart. Cada ação pode apontar para uma aula:
// acao.aula = { modulo: 3, nome: 'Avaliações na Amazon', url?: 'link direto da aula' }
// Sem url específica, o link cai na área de membros.
export const URL_AREA_DE_MEMBROS = 'https://hotmart.com/pt-br/club/the-book-business/products/2275987'
export function urlDaAula(aula) {
  return aula?.url || URL_AREA_DE_MEMBROS
}

