import { useState } from 'react'
import { extrairAsin, urlCapaAmazon } from '../regras/amazon.js'

/**
 * Capa do livro. Ordem: imagem enviada pelo autor > capa oficial da Amazon (pelo ASIN
 * do link de venda) > bloco de cor com o título.
 */
export default function Capa({ livro, className = '' }) {
  const asin = livro.asin || extrairAsin(livro.linkVenda)
  const [falhouAmazon, setFalhouAmazon] = useState(false)
  const src = livro.capa || (!falhouAmazon && asin ? urlCapaAmazon(asin) : null)
  const claro = ['#faab00', '#fc783c', '#f3f0e8', '#6c8ebf', '#b5651d'].includes((livro.capaCor || '').toLowerCase())

  if (src) {
    return (
      // REGRA: a capa real nunca é distorcida, cortada nem recortada. Mostra na proporção original,
      // ocupando a largura da caixa; a altura acompanha a imagem.
      <div className={'bg-areia ' + className}>
        <img
          src={src}
          alt={`Capa de ${livro.titulo}`}
          loading="lazy"
          decoding="async"
          className="block w-full h-auto"
          onError={() => setFalhouAmazon(true)}
          onLoad={(e) => { if (!livro.capa && e.currentTarget.naturalWidth <= 1) setFalhouAmazon(true) }}
        />
      </div>
    )
  }
  return (
    <div
      className={'aspect-[2/3] flex flex-col justify-end overflow-hidden corte-cap ' + (claro ? 'text-tinta' : 'text-white') + ' ' + className}
      style={{ backgroundColor: livro.capaCor || '#1a1a1a', containerType: 'inline-size', padding: 'clamp(6px, 9cqw, 12px)', paddingBottom: 'clamp(12px, 20cqw, 28px)' }}
    >
      {/* o tamanho do título acompanha a largura da capa: nunca estoura, da miniatura de 64px à capa grande */}
      <p className="display text-balance break-words" style={{ fontSize: 'clamp(8px, 13cqw, 15px)', lineHeight: 1.05 }}>{livro.titulo}</p>
      <p className="font-semibold opacity-85" style={{ fontSize: 'clamp(6px, 9cqw, 10px)', marginTop: 'clamp(3px, 5cqw, 8px)' }}>{livro.nomeAutor}</p>
    </div>
  )
}
