import { preencherModelo } from './variaveis.js'
// Regras do check-in do autor ("o que você fez pelo livro").
// Cadência segue a preferência de lembrete do cadastro:
//   semanal -> pede 1 check-in por semana; diario -> 1 por dia.

import { inicioDaSemana } from './datas.js'

const DIA_MS = 1000 * 60 * 60 * 24

function mesmoDia(a, b) {
  const x = new Date(a), y = new Date(b)
  return x.getFullYear() === y.getFullYear() && x.getMonth() === y.getMonth() && x.getDate() === y.getDate()
}

/**
 * Verdadeiro quando ainda não há check-in no período atual (semana ou dia)
 * E o autor não descartou a caixa neste período. Check-in é opcional:
 * "Agora não" grava a data em `checkinsDispensados` e a caixa some até o próximo período.
 */
export function precisaCheckin(autor, hoje = new Date()) {
  const registros = [...(autor.checkins || []), ...(autor.checkinsDispensados || []).map((d) => ({ data: d }))]
  if (autor.lembrete === 'diario') return !registros.some((c) => mesmoDia(c.data, hoje))
  const inicio = inicioDaSemana(hoje).getTime()
  return !registros.some((c) => new Date(c.data).getTime() >= inicio)
}

/** Verdadeiro se a data cai no período atual do autor (dia ou semana). */
export function checkinNoPeriodo(autor, data, hoje = new Date()) {
  if (autor.lembrete === 'diario') return mesmoDia(data, hoje)
  return new Date(data).getTime() >= inicioDaSemana(hoje).getTime()
}

/** Pergunta do check-in conforme a cadência. */
export function perguntaCheckin(autor) {
  return autor.lembrete === 'diario'
    ? 'O que você fez pelo seu livro hoje?'
    : 'O que você fez pelo seu livro nesta semana?'
}

/**
 * Linha do tempo do autor: check-ins, ações concluídas e rejeitadas,
 * mais recente primeiro. Cada item: { tipo, data, texto }.
 */
export function montarHistorico(autor, acoes) {
  const titulo = (id) => { const a = acoes.find((x) => x.id === id); return a ? preencherModelo(a.titulo, autor).texto : id }
  const itens = [
    ...(autor.checkins || []).map((c) => ({ tipo: 'checkin', data: c.data, texto: c.texto })),
    ...autor.concluidas.map((c) => ({ tipo: 'concluida', data: c.data, texto: titulo(c.acaoId) })),
    ...autor.rejeitadas.map((r) => ({ tipo: 'rejeitada', data: r.data, texto: titulo(r.acaoId) })),
  ]
  return itens.sort((a, b) => new Date(b.data) - new Date(a.data))
}

/** Agrupa a linha do tempo por semana (segunda-feira como chave). */
export function agruparPorSemana(itens) {
  const grupos = new Map()
  for (const item of itens) {
    const chave = inicioDaSemana(item.data).getTime()
    if (!grupos.has(chave)) grupos.set(chave, [])
    grupos.get(chave).push(item)
  }
  return [...grupos.entries()].sort((a, b) => b[0] - a[0]).map(([inicio, lista]) => ({ inicio: new Date(inicio), itens: lista }))
}

/** Datas de toda atividade do autor (ações concluídas + check-ins). Usado na sequência e no aviso de retomada. */
export function datasDeAtividade(autor) {
  return [...autor.concluidas.map((c) => c.data), ...(autor.checkins || []).map((c) => c.data)]
}

export { DIA_MS }
