import { useEffect, useRef, useState } from 'react'
import { formatarData, formatarTempo } from '../regras/datas.js'
import Anel from './Anel.jsx'
import LinkAula from './LinkAula.jsx'
import { personalizarAcao } from '../regras/variaveis.js'
import { explicarEscolha } from '../regras/personalizacao.js'
import { encadear } from '../regras/memoria.js'

export default function CartaoAcao({ acao, autor, acoes = [], numero, concluidaEm, destacada, onConcluir, onDesfazer, onRejeitar, onAbrirMaterial }) {
  const concluida = Boolean(concluidaEm)
  // festa curta quando a ação passa de pendente para concluída nesta sessão
  const antes = useRef(concluida)
  const [festa, setFesta] = useState(false)
  useEffect(() => {
    if (!antes.current && concluida) { setFesta(true); const t = setTimeout(() => setFesta(false), 1600); antes.current = true; return () => clearTimeout(t) }
    antes.current = concluida
  }, [concluida])
  const texto = personalizarAcao(acao, autor)
  const motivo = autor ? explicarEscolha(acao, autor) : null
  const elo = autor ? encadear(acao, autor, acoes) : null
  const estado = concluida ? 'feita' : destacada ? 'agora' : 'pendente'
  return (
    <li
      id={`acao-${acao.id}`}
      className={
        `relative grid grid-cols-[44px_1fr] sm:grid-cols-[44px_1fr_auto] gap-5 items-start pl-9 pr-6 py-7 entra-esq atraso-${Math.min(numero, 6)} ` +
        (concluida ? 'bg-white border-2 border-fio' : destacada ? 'bg-white border-2 border-tinta' : 'bg-areia') + (festa ? ' concluindo' : '')
      }
    >
      {festa && (
        <div aria-hidden="true" className="pointer-events-none absolute inset-0 overflow-hidden z-10">
          <span className="carimbo absolute right-6 top-5 display text-[26px] sm:text-[30px] text-tinta border-[4px] border-tinta px-3 py-1 bg-white/90">FEITA</span>
          {['#faab00', '#14523e', '#fc783c', '#1a1a1a', '#B5402E', '#faab00', '#14523e', '#fc783c'].map((cor, i) => (
            <i key={i} className="lombadinha-voa absolute bottom-6" style={{ left: `${18 + i * 10}%`, background: cor, animationDelay: `${i * 45}ms`, '--dx': `${(i % 2 ? 1 : -1) * (12 + i * 6)}px`, '--rot': `${(i % 2 ? -1 : 1) * (20 + i * 15)}deg` }} />
          ))}
        </div>
      )}
      {/* faixa diagonal à esquerda: cor do estado */}
      <i
        aria-hidden="true"
        className={'absolute left-0 top-0 bottom-0 w-4 ' + (concluida ? 'bg-tinta' : destacada ? 'bg-fase' : 'bg-fio')}
        style={{ clipPath: 'polygon(0 0, 100% 0, 40% 100%, 0 100%)' }}
      />
      <Anel numero={numero} estado={estado} />
      <div className="min-w-0">
        <h3 className={'font-bold text-[16px] leading-snug tracking-tight ' + (concluida ? 'text-mudo line-through decoration-tinta decoration-2' : 'text-tinta')}>
          {texto.titulo}
        </h3>
        <p className={'text-[13px] mt-2 leading-relaxed max-w-[58ch] ' + (concluida ? 'text-mudo' : 'text-apoio')}>{texto.descricao}</p>
        {elo && !concluida && (
          <p className="text-[12.5px] mt-2 text-apoio">
            <span aria-hidden="true" className="text-mudo mr-1.5">↳</span>Continua <b className="text-tinta">"{personalizarAcao(elo.anterior, autor).titulo}"</b> ({formatarData(elo.data)}).
          </p>
        )}
        {motivo && !concluida && <p className="text-[12px] mt-2 font-semibold text-fase-tinta"><span className="bg-fase text-fase-tinta px-1.5 py-0.5 mr-1.5 text-[10.5px] font-extrabold uppercase tracking-[.08em]">Para você</span><span className="text-apoio">{motivo}</span></p>}
        <p className="mt-4 text-[11.5px] font-extrabold uppercase tracking-[.08em] text-mudo">
          {formatarTempo(acao.tempoMinutos)}
        </p>
        {(acao.modeloIds.length > 0 || acao.aula) && (
          <div className="grid sm:flex sm:flex-wrap items-start gap-2.5 mt-3">
            {acao.modeloIds.length > 0 && (
              <button onClick={() => onAbrirMaterial(acao)} className="inline-flex items-start gap-2 text-left bg-ambar text-tinta px-3.5 py-2 text-[12.5px] font-extrabold corte-btn hover:bg-tinta hover:text-white transition-colors">
                <span aria-hidden="true" className="inline-block w-2.5 h-3 mt-1 shrink-0 border-2 border-current" />
                <span>Ver texto pronto{acao.modeloIds.length > 1 ? ` · ${acao.modeloIds.length} opções` : ''}</span>
              </button>
            )}
            {acao.aula && <LinkAula aula={acao.aula} botao />}
          </div>
        )}
      </div>
      <div className="grid gap-2 justify-items-start sm:justify-items-end min-w-[132px] col-span-2 sm:col-span-1 pl-[60px] sm:pl-0">
        {concluida ? (
          <div className="sm:text-right">
            <p className="text-[11.5px] font-extrabold uppercase tracking-[.08em]">Concluída</p>
            <p className="text-[12px] text-mudo font-semibold">
              {formatarData(concluidaEm)} ·{' '}
              <button onClick={() => onDesfazer(acao)} className="underline underline-offset-4 hover:text-tinta">desfazer</button>
            </p>
          </div>
        ) : (
          <>
            <button onClick={() => onConcluir(acao)} className={destacada ? 'btn-fase brilha' : 'btn-preto'}>Concluí</button>
            <button onClick={() => onRejeitar(acao)} className="btn-linha" title="Esta ação não se aplica ao meu livro. Tirar do plano.">Não se aplica</button>
          </>
        )}
      </div>
    </li>
  )
}
