import { useEffect } from 'react'
import { CORES } from '../marca.js'

const CORES_FESTA = [CORES.ambar, CORES.laranja, CORES.verde, CORES.creme, '#ffffff']

/**
 * Festa de conquista: escurece a tela, os anéis do LOMBADA explodem do centro,
 * bolinhas nas cores da marca voam e a frase aparece grande. Fecha sozinha ou ao toque.
 */
export default function Celebracao({ texto, onFechar, duracao = 3200 }) {
  useEffect(() => {
    const t = setTimeout(onFechar, duracao)
    return () => clearTimeout(t)
  }, [onFechar, duracao])

  const particulas = Array.from({ length: 22 }, (_, i) => {
    const ang = (i / 22) * Math.PI * 2 + (i % 3) * 0.3
    const dist = 180 + (i % 5) * 70
    return {
      cor: CORES_FESTA[i % CORES_FESTA.length],
      tam: 10 + (i % 4) * 6,
      dx: Math.cos(ang) * dist,
      dy: Math.sin(ang) * dist,
      atraso: (i % 6) * 0.05,
      anel: i % 4 === 0,
    }
  })

  return (
    <div role="status" aria-live="polite" onClick={onFechar} className="fixed inset-0 z-50 grid place-items-center festa-fundo cursor-pointer">
      <div className="relative grid place-items-center text-center px-6">
        {/* anéis que explodem */}
        {[0, 1, 2].map((i) => (
          <i key={i} aria-hidden="true" className="absolute rounded-full border-[10px] border-creme festa-anel" style={{ width: 160, height: 160, animationDelay: `${i * 0.18}s`, borderRightColor: 'transparent' }} />
        ))}
        {/* bolinhas */}
        {particulas.map((p, i) => (
          <i
            key={i}
            aria-hidden="true"
            className={'absolute festa-bolinha ' + (p.anel ? 'border-[4px]' : '')}
            style={{ width: p.tam, height: p.tam, borderRadius: '50%', background: p.anel ? 'transparent' : p.cor, borderColor: p.cor, '--dx': `${p.dx}px`, '--dy': `${p.dy}px`, animationDelay: `${p.atraso}s` }}
          />
        ))}
        <p className="relative text-[12px] font-extrabold uppercase tracking-[.2em] text-ambar festa-texto">Conquista registrada</p>
        <p className="relative display text-[34px] sm:text-[52px] text-white mt-3 max-w-[18ch] text-balance leading-[1] festa-texto" style={{ animationDelay: '.12s' }}>{texto}</p>
        <p className="relative text-[13px] text-white/70 mt-4 festa-texto" style={{ animationDelay: '.3s' }}>Já está na sua página pública. Quem conta, continua.</p>
      </div>
    </div>
  )
}
