import { CORES } from '../marca.js'
import Wordmark from './Wordmark.jsx'
import { LIVROS_POR_FASE } from '../dados/lombadas.js'
export { LIVROS_POR_FASE }

// A prateleira do LOMBADA: lombadas chapadas nas cores da marca, palavras da jornada,
// dois filetes e um pontinho, como nos estudos do cliente. Fundo creme, marca preta em cima.
export const VINHO = '#B5402E'
export const LIVROS = [
  { p: 'IDEIAS', cor: CORES.verde, alt: 78, larg: 1.1, ponto: true },
  { p: 'PLANEJAMENTO', cor: CORES.ambar, alt: 92, larg: 1.25 },
  { p: 'ESCRITA', cor: VINHO, alt: 88, larg: 1.05, filetes: 'topo' },
  { p: 'REVISÃO', cor: CORES.creme, alt: 82, larg: 1, ponto: true, escuro: true },
  { p: 'PUBLICAÇÃO', cor: CORES.tinta, alt: 96, larg: 1.2 },
  { p: 'ESTRATÉGIA', cor: CORES.creme, alt: 74, larg: 0.95, escuro: true, inclina: -5 },
  { p: 'LEITORES', cor: VINHO, alt: 90, larg: 1.15, ponto: true },
  { p: 'MARKETING', cor: CORES.tinta, alt: 84, larg: 1.05 },
  { p: 'RESULTADOS', cor: CORES.ambar, alt: 94, larg: 1.3, ponto: true },
  { p: 'VENDAS', cor: CORES.verde, alt: 80, larg: 1, filetes: 'topo' },
  { p: 'AUTOR', cor: CORES.verde, alt: 86, larg: 1.1, ponto: true },
  { p: 'HISTÓRIAS', cor: VINHO, alt: 92, larg: 1.05 },
  { p: 'LIBERDADE', cor: CORES.creme, alt: 76, larg: 1, escuro: true },
]

function Filetes({ escuro, onde = 'base' }) {
  const cor = escuro ? 'rgba(20,17,15,.55)' : 'rgba(255,255,255,.75)'
  const pos = onde === 'topo' ? { top: 22 } : { bottom: 26 }
  return (
    <>
      <i className="lomb-deco absolute left-3 right-3 h-[3px]" style={{ background: cor, ...pos }} />
      <i className="lomb-deco absolute left-3 right-3 h-[3px]" style={{ background: cor, ...(onde === 'topo' ? { top: 30 } : { bottom: 34 }) }} />
    </>
  )
}

/** Estante em pé: para desktop e telas largas. */
export function Estante({ livros, altura, gap = 8, fonte = 12 }) {
  return (
    <div className="flex items-end" style={{ height: altura, gap }}>
      {livros.map((l, i) => (
        <div
          key={l.p}
          className="relative flutua"
          style={{
            flexGrow: l.larg, flexBasis: 0, minWidth: 0,
            height: `${l.alt}%`, background: l.cor,
            borderRadius: '6px 6px 0 0',
            boxShadow: l.escuro ? `inset 0 0 0 3px ${CORES.tinta}` : undefined,
            transform: l.inclina ? `rotate(${l.inclina}deg)` : undefined, transformOrigin: 'bottom center',
            animationDuration: `${7 + (i % 5)}s`, animationDelay: `${-(i * 0.9)}s`,
            containerType: 'size',
          }}
        >
          <Filetes escuro={l.escuro} onde={l.filetes || 'base'} />
          {l.ponto && <i className="lomb-deco absolute left-1/2 -translate-x-1/2 rounded-full" style={{ width: 22, height: 22, ...(l.filetes === 'topo' ? { bottom: 24 } : { top: 26 }), background: l.escuro ? CORES.verde : l.cor === CORES.ambar ? CORES.verde : CORES.creme }} />}
          <span
            className={'absolute left-1/2 font-extrabold uppercase whitespace-nowrap tracking-[.1em] ' + (l.ponto && l.filetes !== 'topo' ? 'lomb-palavra-baixa' : 'lomb-palavra')}
            style={{
              // a palavra nunca estoura a lombada: encolhe conforme a altura disponível (--lomb-cqh, ver index.css);
              // em lombadas baixas os filetes e o ponto somem e a palavra ganha o espaço
              fontSize: `min(${fonte}px, calc(var(--lomb-cqh) / ${(l.p.length * 0.86).toFixed(2)}))`,
              transform: 'translate(-50%, -50%) rotate(-90deg)', color: l.escuro ? CORES.tinta : '#fff',
            }}
          >
            {l.p}
          </span>
        </div>
      ))}
    </div>
  )
}

/** Lombadas da fase, para a estante do hero: palavras do momento do autor. */

/** Pilha deitada: para o celular. Cada lombada é uma barra com dois filetes e a palavra. */
export function Pilha({ livros }) {
  return (
    <div className="grid" style={{ gap: 6 }}>
      {livros.map((l, i) => (
        <div
          key={l.p}
          className="relative flex items-center gap-3 px-3 entra"
          style={{ height: 34, background: l.cor, borderRadius: '0 6px 6px 0', width: `${68 + (l.alt % 30)}%`, animationDelay: `${i * 0.05}s`, boxShadow: l.escuro ? `inset 0 0 0 3px ${CORES.tinta}` : undefined }}
        >
          <span className="flex gap-1">
            <i className="block w-[3px] h-4" style={{ background: l.escuro ? 'rgba(20,17,15,.55)' : 'rgba(255,255,255,.75)' }} />
            <i className="block w-[3px] h-4" style={{ background: l.escuro ? 'rgba(20,17,15,.55)' : 'rgba(255,255,255,.75)' }} />
          </span>
          <span className="font-extrabold uppercase text-[12px] tracking-[.1em]" style={{ color: l.escuro ? CORES.tinta : '#fff' }}>{l.p}</span>
          {l.ponto && <i className="ml-auto rounded-full" style={{ width: 14, height: 14, background: l.escuro ? CORES.verde : CORES.creme }} />}
        </div>
      ))}
    </div>
  )
}

/**
 * Capa do LOMBADA. `frase`: a linha em caixa alta abaixo da marca.
 * Desktop: marca + frase à esquerda e estante ocupando a base. Celular: marca, frase e pilha deitada.
 */
export default function Prateleira({ frase = 'Ferramentas, conexões e oportunidades para autores', altura = 320, className = '', compacta = false }) {
  return (
    <div className={'relative overflow-hidden bg-creme text-tinta ' + className}>
      {/* desktop */}
      <div className="hidden sm:block px-8 pt-7">
        <div className="flex items-end justify-between gap-6">
          <div>
            <Wordmark tamanho={44} />
            <p className="text-[12px] font-bold uppercase tracking-[.22em] text-apoio mt-2 max-w-[34ch] leading-relaxed">{frase}</p>
          </div>
        </div>
        <div className="mt-4">
          <Estante livros={LIVROS} altura={altura} />
        </div>
      </div>
      {/* celular */}
      <div className="sm:hidden px-6 pt-6 pb-6">
        <Wordmark tamanho={36} />
        <p className="text-[11.5px] font-bold uppercase tracking-[.2em] text-apoio mt-2 leading-relaxed">{frase}</p>
        <div className="mt-5">
          {/* no celular a pilha é curta quando a tela precisa do formulário logo abaixo (entrar) */}
          <Pilha livros={compacta ? LIVROS.filter((_, i) => [0, 1, 4, 6].includes(i)) : LIVROS.filter((_, i) => i % 2 === 0 || i === 1)} />
        </div>
      </div>
    </div>
  )
}
