import { uso } from '../servicos/uso.js'
import { useState } from 'react'
import { preencherModelo, personalizarAcao, VARIAVEIS } from '../regras/variaveis.js'
import { formatarTempo } from '../regras/datas.js'
import LinkAula from '../componentes/LinkAula.jsx'
import GeradorPosts from '../componentes/GeradorPosts.jsx'
import { classificarFase } from '../regras/fase.js'

const NOME_TIPO = { post: 'Post para rede social', email: 'E-mail', mensagem: 'Mensagem direta (WhatsApp ou direct)' }

/** Divide o texto preenchido em trechos, marcando os que vieram das variáveis. */
function segmentar(texto, autor) {
  const partes = []
  const re = /\{([a-z_]+)\}/g
  let ultimo = 0, m
  while ((m = re.exec(texto))) {
    if (m.index > ultimo) partes.push({ t: texto.slice(ultimo, m.index) })
    const { texto: valor, faltando } = preencherModelo(m[0], autor)
    partes.push({ t: valor, v: true, falta: faltando.length > 0 })
    ultimo = m.index + m[0].length
  }
  if (ultimo < texto.length) partes.push({ t: texto.slice(ultimo) })
  return partes
}

function BotaoCopiar({ texto, rotulo = 'Copiar' }) {
  const [copiado, setCopiado] = useState(false)
  async function copiar() {
    uso('copiou_texto')
    try { await navigator.clipboard.writeText(texto) } catch { /* sem clipboard */ }
    setCopiado(true); setTimeout(() => setCopiado(false), 2000)
  }
  return <button onClick={copiar} className="btn-preto !py-2 !text-[11.5px] uppercase tracking-[.08em] min-w-[96px]">{copiado ? 'Copiado' : rotulo}</button>
}

export default function MaterialDeApoio({ acao, modelos, autor, jaConcluida, onVoltar, onConcluir, onRejeitar }) {
  const [indice, setIndice] = useState(0)
  const modelo = modelos[Math.min(indice, modelos.length - 1)]
  const corpo = preencherModelo(modelo.texto, autor)
  const assunto = modelo.assunto ? preencherModelo(modelo.assunto, autor) : null
  const faltando = [...new Set([...corpo.faltando, ...(assunto?.faltando ?? [])])]
  const partes = segmentar(modelo.texto, autor)
  const textoAcao = personalizarAcao(acao, autor)

  return (
    <div>
      <button onClick={onVoltar} className="btn-linha">← Voltar ao plano da semana</button>

      <header className="mt-5 bg-ambar text-tinta px-8 pt-8 pb-9 corte-b">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em]">
          {NOME_TIPO[modelo.tipo] ?? modelo.nome} · {formatarTempo(acao.tempoMinutos)}{modelo.genero ? ` · versão para ${modelo.genero}` : ''}
        </p>
        <h1 className="display text-[34px] sm:text-[42px] mt-3 text-balance">{textoAcao.titulo}</h1>
        <p className="text-[14px] font-medium mt-3 max-w-[60ch]">{textoAcao.descricao}</p>
        {acao.aula && (
          <p className="mt-4 text-[11.5px] font-extrabold uppercase tracking-[.08em]">
            <LinkAula aula={acao.aula} className="!border-tinta hover:!border-white" />
          </p>
        )}
      </header>

      {faltando.length > 0 && (
        <div className="bg-creme px-6 py-4 mt-4 text-[13.5px]">
          <p className="font-extrabold">Faltam dados do seu cadastro para completar este texto:</p>
          <p className="text-apoio mt-1">{faltando.map((v) => VARIAVEIS[v]?.descricao ?? v).join(', ')}. Os trechos aparecem entre colchetes.</p>
        </div>
      )}

      {modelos.length > 1 && (
        <div className="flex flex-wrap items-center gap-2 mt-6">
          {modelos.map((m, i) => (
            <button key={m.id} onClick={() => setIndice(i)} className={'text-[12.5px] font-bold px-4 py-2 corte-btn transition-colors ' + (i === indice ? 'bg-tinta text-white' : 'bg-areia text-apoio hover:bg-fio')}>
              Opção {i + 1} · {m.angulo}
            </button>
          ))}
        </div>
      )}

      <section className="mt-6 bg-areia relative">
        <div className="flex items-center justify-between gap-3 px-6 pt-4">
          <span className="text-[11px] font-extrabold uppercase tracking-[.12em] text-mudo">Texto pronto</span>
          <BotaoCopiar key={modelo.id} texto={corpo.texto} />
        </div>
        {assunto && (
          <div className="px-6 pt-4 pb-3 text-[14px] border-b-2 border-white">
            <span className="text-[11px] font-extrabold uppercase tracking-[.12em] text-mudo mr-3">Assunto</span>
            <span className="font-bold">{assunto.texto}</span>
            <button onClick={() => navigator.clipboard?.writeText(assunto.texto)} className="ml-3 text-[12px] font-semibold text-mudo underline underline-offset-4 hover:text-tinta">copiar</button>
          </div>
        )}
        <pre className="px-6 pt-4 pb-6 whitespace-pre-wrap font-sans text-[15px] leading-relaxed text-tinta">
          {partes.map((p, i) => p.v ? <mark key={i} className={'bg-creme text-tinta font-bold px-0.5 border-b-2 ' + (p.falta ? 'border-alerta' : 'border-ambar')}>{p.t}</mark> : p.t)}
        </pre>
      </section>
      {modelo.tipo === 'post' && (
        <div className="mt-6 bg-creme px-5 py-4 flex flex-wrap items-center justify-between gap-3">
          <span className="text-[13px] font-semibold">Quer mais variações deste post? O Gerador de Posts Magnéticos cria 5 ideias com os seus dados.</span>
          <GeradorPosts autor={autor} fase={classificarFase(autor.livro)} acaoDaSemana={acao.titulo} compacto />
        </div>
      )}
      <p className="text-[12.5px] text-mudo mt-3">Os trechos marcados vieram do cadastro de <span className="text-tinta font-semibold">{autor.livro.titulo}</span>. Ajuste o que quiser antes de publicar: quanto mais com a sua voz, melhor.</p>

      <div className="mt-12 pt-6 border-t-2 border-tinta flex flex-wrap items-center gap-4">
        {jaConcluida ? (
          <span className="text-[13px] font-semibold text-mudo">Esta ação já está concluída nesta semana.</span>
        ) : (
          <>
            <button onClick={onConcluir} className="btn-primario">Já fiz. Marcar como concluída</button>
            <button onClick={onRejeitar} className="btn-linha">Não se aplica ao meu livro</button>
          </>
        )}
        <button onClick={onVoltar} className="btn-linha ml-auto">Voltar ao plano</button>
      </div>
    </div>
  )
}
