// Persistência no navegador (localStorage). Substituir por banco depois:
// só estas funções tocam no armazenamento.

const CHAVE = 'lombada.estado.v1'

/** Lê o estado salvo. Devolve null se não houver ou se estiver corrompido. */
export function carregarEstado() {
  try {
    const bruto = window.localStorage.getItem(CHAVE)
    if (!bruto) return null
    const estado = JSON.parse(bruto)
    if (!estado || estado.versao !== 1 || !Array.isArray(estado.autores)) return null
    return estado
  } catch {
    return null
  }
}

/** Grava o estado inteiro. Falha em silêncio (modo privado, cota cheia). */
export function salvarEstado(estado) {
  try {
    window.localStorage.setItem(CHAVE, JSON.stringify({ ...estado, versao: 1, salvoEm: new Date().toISOString() }))
    return true
  } catch {
    return false
  }
}

export function apagarEstado() {
  try { window.localStorage.removeItem(CHAVE) } catch { /* nada */ }
}

/** Serializa para download (backup / envio do teste com alunos). */
export function exportarEstado(estado) {
  return JSON.stringify({ ...estado, versao: 1, exportadoEm: new Date().toISOString() }, null, 2)
}

/** Valida um JSON importado. Lança erro com mensagem amigável se inválido. */
export function validarImportacao(texto) {
  let estado
  try { estado = JSON.parse(texto) } catch { throw new Error('O arquivo não é um JSON válido.') }
  if (!estado || estado.versao !== 1) throw new Error('O arquivo não é um backup do LOMBADA (versão 1).')
  for (const campo of ['autores', 'leitores', 'acoes', 'modelos', 'oportunidades']) {
    if (!Array.isArray(estado[campo])) throw new Error(`Falta a lista "${campo}" no arquivo.`)
  }
  return estado
}

/** Chave separada para preferências leves da interface (última visita, avisos dispensados). */
const CHAVE_UI = 'lombada.ui.v1'
export function lerUI() {
  try { return JSON.parse(window.localStorage.getItem(CHAVE_UI) || '{}') } catch { return {} }
}
export function gravarUI(parcial) {
  try { window.localStorage.setItem(CHAVE_UI, JSON.stringify({ ...lerUI(), ...parcial })) } catch { /* nada */ }
}
