const NOME_MES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro']

function ocorrenciaNoAno(regra, ano) {
  if (regra.dia) return new Date(ano, regra.mes - 1, regra.dia, 12)
  if (regra.semana > 0) {
    const primeiro = new Date(ano, regra.mes - 1, 1, 12)
    const desloc = (regra.diaSemana - primeiro.getDay() + 7) % 7
    return new Date(ano, regra.mes - 1, 1 + desloc + (regra.semana - 1) * 7, 12)
  }
  // semana -1: último dia-da-semana do mês
  const ultimo = new Date(ano, regra.mes, 0, 12)
  const volta = (ultimo.getDay() - regra.diaSemana + 7) % 7
  return new Date(ano, regra.mes - 1, ultimo.getDate() - volta, 12)
}

/** Próxima ocorrência da data a partir de hoje (inclui hoje). */
export function proximaOcorrencia(regra, hoje = new Date()) {
  const base = new Date(hoje.getFullYear(), hoje.getMonth(), hoje.getDate())
  const esteAno = ocorrenciaNoAno(regra, hoje.getFullYear())
  return esteAno >= base ? esteAno : ocorrenciaNoAno(regra, hoje.getFullYear() + 1)
}

/** As datas dos próximos 12 meses no formato da Central de Oportunidades. */
export function datasComoOportunidades(hoje = new Date()) {
  return DATAS_COMEMORATIVAS.map((d) => {
    const quando = proximaOcorrencia(d.regra, hoje)
    const preparar = new Date(quando); preparar.setDate(preparar.getDate() - ANTECEDENCIA_MICROCICLO_DIAS)
    return {
      id: `${d.id}_${quando.getFullYear()}`,
      tipo: 'Data comemorativa',
      nome: `${d.nome} · ${quando.getDate()} de ${NOME_MES[quando.getMonth()]}`,
      descricao: `${d.dica} Comece o microciclo por volta de ${preparar.getDate()} de ${NOME_MES[preparar.getMonth()]}.`,
      generos: d.generos,
      prazo: quando.toISOString(),
      tipoPrazo: 'data',
      foco: d.foco,
      recorrencia: 'anual',
      link: null,
    }
  })
}
