import {
  OPCOES_STATUS, FORMATOS_PUBLICACAO, FAIXAS_AUDIENCIA, OBJETIVOS, FAIXAS_HORAS, LEMBRETES, CORES_CAPA,
} from '../dados/opcoes.js'
import { STATUS_LIVRO, classificarFase, NOME_FASE } from '../regras/fase.js'
