const ETAPAS_TODAS = ['O livro', 'Você, autor', 'Preferências']

// Estado inicial de um cadastro em branco
export function cadastroVazio() {
  return {
    livro: {
      titulo: '', subtitulo: '', genero: '', subNicho: '', publicoAlvo: '', sinopse: '',
      promessa: '', trecho: '', trechos: [], capa: null,
      status: STATUS_LIVRO.ESCREVENDO, dataPublicacao: '', dataLancamentoPrevista: '', formato: 'KDP', linkVenda: '', precoCapa: '', naAmazon: true, linkLoja: '',
    },
    conquistas: [],
    nome: '', email: '', whatsapp: '', cidade: '', profissao: '', bio: '', foto: null,
    redes: { instagram: '', youtube: '', linkedin: '', tiktok: '', site: '' },
    audiencia: { instagram: 'não tenho', youtube: 'não tenho', linkedin: 'não tenho', tiktok: 'não tenho' },
    temListaEmail: false, objetivo: 'vender_mais_copias', horasSemana: 'até 2 horas',
    lembrete: 'semanal', aparecerNaVitrine: true,
  }
}

// Validação por etapa: devolve { campo: mensagem }
function validar(etapa, dados) {
  const erros = {}
  if (etapa === 0) {
    if (!dados.livro.titulo.trim()) erros.titulo = 'Informe o título do livro.'
    if (!dados.livro.genero) erros.genero = 'Escolha um gênero.'
    if (!dados.livro.subNicho.trim()) erros.subNicho = 'Diga o sub-nicho: é o que deixa o plano e os textos específicos.'
    if (!dados.livro.publicoAlvo.trim()) erros.publicoAlvo = 'Descreva para quem é o livro.'
    if (!dados.livro.sinopse.trim()) erros.sinopse = 'A sinopse entra na sua página pública.'
    if (!dados.livro.promessa.trim()) erros.promessa = 'A promessa entra nos textos prontos.'
    if (listaTrechos(dados.livro).length === 0) erros.trecho = 'Pelo menos um trecho: ele entra nos posts e na sua página.'
    if (!dados.livro.capa && !(dados.livro.linkVenda || '').trim()) erros.capa = dados.livro.naAmazon === false ? 'Envie a capa do livro.' : 'Envie a capa (ou o link da Amazon, de onde a capa é buscada).'
    if (dados.livro.status !== STATUS_LIVRO.PUBLICADO && dados.livro.dataLancamentoPrevista && new Date(dados.livro.dataLancamentoPrevista) < new Date(new Date().toDateString())) erros.dataLancamentoPrevista = 'A data de lançamento prevista já passou. Se o livro saiu, marque como publicado.'
    if (dados.livro.status === STATUS_LIVRO.PUBLICADO) {
      if (!dados.livro.dataPublicacao) erros.dataPublicacao = 'Livro publicado precisa da data de publicação.'
      else if (new Date(dados.livro.dataPublicacao) > new Date()) erros.dataPublicacao = 'A data não pode estar no futuro.'
      if (dados.livro.naAmazon !== false && !dados.livro.linkVenda.trim()) erros.linkVenda = 'Livro publicado precisa do link da Amazon. Se não está lá, marque "Não está na Amazon".'
    }
    if (dados.livro.linkVenda.trim() && !eLinkAmazon(dados.livro.linkVenda)) erros.linkVenda = 'Cole o link da página do livro na Amazon (amazon.com.br/dp/...).'
  }
  if (etapa === 1) {
    if (!dados.nome.trim()) erros.nome = 'Informe seu nome como aparece no livro.'
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test((dados.email || '').trim())) erros.email = 'Informe um e-mail válido: é por ele que você entra.'
    if (((dados.whatsapp || '').replace(/\D/g, '')).length < 10) erros.whatsapp = 'WhatsApp com DDD: é por ele que o time envia o seu código.'
    if (!dados.cidade.trim()) erros.cidade = 'Sua cidade entra nas ações de imprensa e eventos.'
    if (!dados.profissao.trim()) erros.profissao = 'Sua profissão entra na bio e nos textos.'
    if (!dados.bio.trim()) erros.bio = 'A bio aparece na sua página pública.'
    if (!dados.foto) erros.foto = 'Sua foto aparece na página pública do livro.'
  }
  return erros
}

export default function CadastroLivro({ inicial, onSalvar, onCancelar, etapaInicial = 0, soLivro = false }) {
  const ETAPAS = soLivro ? ['O livro'] : ETAPAS_TODAS // livro adicional: só a etapa do livro
  const editando = Boolean(inicial)
  const [etapa, setEtapa] = useState(inicial ? etapaInicial : 0)
  const [dados, setDados] = useState(() => (inicial ? estruturar(inicial) : cadastroVazio()))
  const [erros, setErros] = useState({})

  const setLivro = (campo, valor) => setDados((d) => ({ ...d, livro: { ...d.livro, [campo]: valor } }))
  const setAutor = (campo, valor) => setDados((d) => ({ ...d, [campo]: valor }))
  const setRede = (rede, valor) => setDados((d) => ({ ...d, audiencia: { ...d.audiencia, [rede]: valor } }))

  const publicado = dados.livro.status === STATUS_LIVRO.PUBLICADO
  const fasePrevista = classificarFase(
    { status: dados.livro.status, dataPublicacao: dados.livro.dataPublicacao || null },
  )

  const [conferindo, setConferindo] = useState(false)
  const [amazonLido, setAmazonLido] = useState(null) // { asin, titulo, autor, bate }

  /** Confere na Amazon se o link é mesmo deste livro. Falha de rede não bloqueia. */
  async function conferirAmazon() {
    const asin = extrairAsin(dados.livro.linkVenda)
    if (!asin || dados.livro.naAmazon === false) return true
    if (amazonLido?.asin === asin) return amazonLido.bate || amazonLido.confirmado
    setConferindo(true)
    const d = await lerLivroAmazon(asin)
    setConferindo(false)
    if (!d) return true
    const bate = titulosBatem(dados.livro.titulo, d.titulo)
    const lido = { asin, titulo: d.titulo, autor: d.autor || '', bate, conferidoEm: new Date().toISOString() }
    setAmazonLido(lido)
    setLivro('amazon', lido)
    if (!bate) setErros((x) => ({ ...x, linkVenda: `Na Amazon esse link é "${d.titulo}"${d.autor ? `, de ${d.autor}` : ''}. Confira o link, ou confirme abaixo que é o seu livro mesmo.` }))
    return bate
  }

  async function avancar() {
    const e = validar(etapa, dados)
    setErros(e)
    if (Object.keys(e).length) return
    if (etapa === 0 && !(await conferirAmazon())) return
    if (etapa < ETAPAS.length - 1) {
      setEtapa(etapa + 1)
      window.scrollTo({ top: 0 })
    } else {
      onSalvar({ ...normalizar(dados, inicial), ...(editando || soLivro ? {} : { consentimento: { em: new Date().toISOString(), versao: VERSAO_LEGAL } }) })
    }
  }

  function voltar() {
    setErros({})
    if (etapa === 0) onCancelar()
    else setEtapa(etapa - 1)
  }

  const percentual = Math.round(((etapa + 1) / ETAPAS.length) * 100)

  return (
    <div>
      <button onClick={onCancelar} className="btn-linha">
        ← {editando ? 'Voltar sem salvar' : soLivro ? 'Voltar ao perfil' : 'Cancelar cadastro'}
      </button>

      <header className="mt-5 mb-8 bg-tinta text-white px-8 pt-8 pb-7 corte-d">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Etapa {etapa + 1} de {ETAPAS.length} · {ETAPAS[etapa]}</p>
        <h1 className="display text-[34px] sm:text-[42px] mt-3">{editando ? 'Editar cadastro' : soLivro ? 'Cadastre outro livro' : 'Cadastre seu livro'}</h1>
        <div className="mt-6 flex gap-1.5 h-3.5 max-w-md">
          {ETAPAS.map((nome, i) => (
            <i key={nome} className={'flex-1 block ' + (i < etapa ? 'bg-white' : i === etapa ? 'bg-ambar' : 'bg-white/25')} style={{ clipPath: 'polygon(0 0, 100% 0, 80% 100%, 0 100%)' }} />
          ))}
        </div>
        <ol className="mt-2 grid grid-cols-3 max-w-md text-[11px] font-extrabold uppercase tracking-[.08em] text-white/50">
          {ETAPAS.map((nome, i) => (
            <li key={nome} className={i === etapa ? 'text-ambar' : i < etapa ? 'text-white' : ''}>{nome}</li>
          ))}
        </ol>
      </header>

      <form
        onSubmit={(e) => { e.preventDefault(); avancar() }}
        className="space-y-6"
      >
        {etapa === 0 && (
          <>
            <p className="bg-areia px-5 py-3 text-[13px] text-apoio -mt-2">O time do Método The Book Business confere e libera. Só <b>subtítulo</b>, <b>preço</b> e <b>conquistas</b> são opcionais.</p>
            <Campo rotulo="Título do livro" erro={erros.titulo}>
              <input className={classeInput} value={dados.livro.titulo} onChange={(e) => setLivro('titulo', e.target.value)} autoFocus />
            </Campo>
            <Campo rotulo="Subtítulo (opcional)">
              <input className={classeInput} value={dados.livro.subtitulo} onChange={(e) => setLivro('subtitulo', e.target.value)} />
            </Campo>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <Campo rotulo="Gênero" erro={erros.genero}>
                <Select valor={dados.livro.genero} onChange={(v) => setLivro('genero', v)} opcoes={GENEROS} vazio="Escolha um gênero" />
              </Campo>
              <Campo rotulo="Sub-nicho" erro={erros.subNicho} ajuda="Ex.: liderança em pequenas empresas">
                <input className={classeInput} value={dados.livro.subNicho} onChange={(e) => setLivro('subNicho', e.target.value)} />
              </Campo>
            </div>
            <Campo rotulo="Público-alvo" erro={erros.publicoAlvo} ajuda="Complete a frase: escrevi este livro para...">
              <input className={classeInput} value={dados.livro.publicoAlvo} onChange={(e) => setLivro('publicoAlvo', e.target.value)} placeholder="donos de pequenas empresas com equipes de 5 a 30 pessoas" />
            </Campo>
            <Campo rotulo="Sinopse" erro={erros.sinopse}>
              <textarea className={classeInput + ' min-h-28'} value={dados.livro.sinopse} onChange={(e) => setLivro('sinopse', e.target.value)} />
            </Campo>
            <Campo rotulo="Promessa do livro em uma frase" erro={erros.promessa} ajuda="O que muda na vida de quem lê. Entra nos textos prontos das suas ações.">
              <input className={classeInput} value={dados.livro.promessa} onChange={(e) => setLivro('promessa', e.target.value)} />
            </Campo>
            <ListaTrechos valor={dados.livro.trechos} onChange={(v) => setLivro('trechos', v)} erro={erros.trecho} />

            <div className="grid grid-cols-1 sm:grid-cols-[1fr_auto] gap-6 items-start">
              <UploadImagem
                rotulo="Capa do livro"
                perfil="capa"
                formato="capa"
                valor={dados.livro.capa}
                onChange={(v) => setLivro('capa', v)}
                ajuda={extrairAsin(dados.livro.linkVenda) ? 'Sem envio, usamos a capa oficial da Amazon pelo link acima.' : 'JPG, PNG ou WebP. A imagem é redimensionada e comprimida aqui mesmo.'}
              />
            {erros.capa && <p className="text-[12.5px] font-semibold text-alerta -mt-3">{erros.capa}</p>}
              {!dados.livro.capa && extrairAsin(dados.livro.linkVenda) && (
                <div className="w-24"><span className="block text-[11px] font-extrabold uppercase tracking-[.08em] text-mudo mb-1.5">Da Amazon</span><Capa livro={{ ...dados.livro, nomeAutor: dados.nome }} /></div>
              )}
            </div>

            <Campo rotulo="Status do livro">
              <Escolha valor={dados.livro.status} onChange={(v) => setLivro('status', v)} opcoes={OPCOES_STATUS} />
            </Campo>

            {publicado && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
                <Campo rotulo="Data de publicação" erro={erros.dataPublicacao}>
                  <input type="date" className={classeInput} value={dados.livro.dataPublicacao} onChange={(e) => setLivro('dataPublicacao', e.target.value)} />
                </Campo>
                <Campo rotulo="Formato de publicação">
                  <Select valor={dados.livro.formato} onChange={(v) => setLivro('formato', v)} opcoes={FORMATOS_PUBLICACAO} />
                </Campo>
              </div>
            )}
            {!publicado && (
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <Campo rotulo="Formato de publicação previsto">
                <Select valor={dados.livro.formato} onChange={(v) => setLivro('formato', v)} opcoes={FORMATOS_PUBLICACAO} />
              </Campo>
              <Campo rotulo="Data prevista de lançamento (opcional)" erro={erros.dataLancamentoPrevista} ajuda="Sem data oficial não há campanha. O plano conta os dias até lá.">
                <input type="date" className={classeInput} value={dados.livro.dataLancamentoPrevista} onChange={(e) => setLivro('dataLancamentoPrevista', e.target.value)} />
              </Campo>
              </div>
            )}

            {publicado && (
              <Campo rotulo="O livro está na Amazon?" ajuda="Sem Amazon, a página pública fica sem botão de compra (ou usa o link de outra loja) e as ações da Amazon saem do plano.">
                <Escolha valor={dados.livro.naAmazon === false ? 'nao' : 'sim'} onChange={(v) => { setLivro('naAmazon', v === 'sim'); if (v === 'nao') { setLivro('linkVenda', ''); setAmazonLido(null) } }} opcoes={[{ valor: 'sim', rotulo: 'Sim, está na Amazon' }, { valor: 'nao', rotulo: 'Não está na Amazon' }]} />
              </Campo>
            )}
            {publicado && dados.livro.naAmazon === false && (
              <Campo rotulo="Link para comprar em outra loja (opcional)" ajuda="Site da editora, Clube de Autores, sua loja. Aparece como botão na página pública.">
                <input className={classeInput} value={dados.livro.linkLoja || ''} onChange={(e) => setLivro('linkLoja', e.target.value)} placeholder="https://" />
              </Campo>
            )}
            <div className={'grid grid-cols-1 sm:grid-cols-2 gap-6 ' + (publicado && dados.livro.naAmazon === false ? 'hidden' : '')}>
              <Campo rotulo="Link do livro na Amazon" erro={erros.linkVenda} ajuda={
                extrairAsin(dados.livro.linkVenda)
                  ? `Código do produto: ${extrairAsin(dados.livro.linkVenda)}. Na vitrine, o botão de compra vira ${AMAZON_TAG_AFILIADO ? 'o link de afiliado da The Book Business' : 'o link limpo do produto'}.`
                  : (publicado ? 'Cole o link da página do livro. O sistema limpa e monta o link de afiliado sozinho.' : 'Pode deixar em branco e preencher no lançamento.')
              }>
                <input className={classeInput} value={dados.livro.linkVenda} onChange={(e) => { setLivro('linkVenda', e.target.value); setAmazonLido(null); setErros((x) => ({ ...x, linkVenda: undefined })) }} placeholder="https://www.amazon.com.br/dp/..." />
                {conferindo && <span className="block text-[12px] text-mudo mt-1">Conferindo na Amazon…</span>}
                {amazonLido && amazonLido.asin === extrairAsin(dados.livro.linkVenda) && amazonLido.bate && <span className="block text-[12px] text-verde font-bold mt-1">Conferido: "{amazonLido.titulo}".</span>}
                {amazonLido && amazonLido.asin === extrairAsin(dados.livro.linkVenda) && !amazonLido.bate && !amazonLido.confirmado && (
                  <button type="button" onClick={() => { const c = { ...amazonLido, confirmado: true }; setAmazonLido(c); setLivro('amazon', c); setErros((x) => ({ ...x, linkVenda: undefined })) }} className="mt-2 text-[12.5px] font-bold underline underline-offset-4">É o meu livro mesmo, seguir</button>
                )}
              </Campo>
              <Campo rotulo="Preço de capa (R$) (opcional)">
                <input type="number" step="0.01" min="0" className={classeInput} value={dados.livro.precoCapa} onChange={(e) => setLivro('precoCapa', e.target.value)} />
              </Campo>
            </div>

            <p className="bg-areia px-5 py-4 text-[14px] font-semibold">
              Com esses dados, você entra na fase <span className="display text-[16px] ml-1">{NOME_FASE[fasePrevista]}</span>.
            </p>
          </>
        )}

        {etapa === 1 && (
          <>
            <Campo rotulo="Seu nome, como aparece no livro" erro={erros.nome}>
              <input className={classeInput} value={dados.nome} onChange={(e) => setAutor('nome', e.target.value)} autoFocus />
            </Campo>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <Campo rotulo="Seu e-mail" erro={erros.email} ajuda="É com ele que você entra no LOMBADA.">
                <input type="email" className={classeInput} value={dados.email || ''} onChange={(e) => setAutor('email', e.target.value)} disabled={editando} autoComplete="email" />
              </Campo>
              <Campo rotulo="Seu WhatsApp" erro={erros.whatsapp} ajuda="O time envia o código de acesso por aqui.">
                <input inputMode="tel" className={classeInput} value={dados.whatsapp || ''} onChange={(e) => setAutor('whatsapp', e.target.value)} placeholder="(11) 99999-9999" autoComplete="tel" />
              </Campo>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-6">
              <Campo rotulo="Cidade" erro={erros.cidade}>
                <input className={classeInput} value={dados.cidade} onChange={(e) => setAutor('cidade', e.target.value)} placeholder="Curitiba, PR" />
              </Campo>
              <Campo rotulo="Profissão" erro={erros.profissao}>
                <input className={classeInput} value={dados.profissao} onChange={(e) => setAutor('profissao', e.target.value)} />
              </Campo>
            </div>
            <Campo rotulo="Bio curta" erro={erros.bio} ajuda="Aparece na sua página na vitrine. Duas linhas bastam.">
              <textarea className={classeInput + ' min-h-20'} value={dados.bio} onChange={(e) => setAutor('bio', e.target.value)} />
            </Campo>
            <UploadImagem rotulo="Sua foto" perfil="foto" formato="foto" valor={dados.foto} onChange={(v) => setAutor('foto', v)} ajuda="Rosto visível, de frente. Recortamos em quadrado e comprimimos aqui mesmo." />
            {erros.foto && <p className="text-[12.5px] font-semibold text-alerta -mt-3">{erros.foto}</p>}
            <ListaConquistas valor={dados.conquistas || []} onChange={(v) => setAutor('conquistas', v)} />

            <div>
              <span className="block text-[12px] font-extrabold uppercase tracking-[.08em] text-tinta mb-1">Suas redes</span>
              <p className="text-[12.5px] text-mudo mb-3">O @ ou o link entra na sua página pública. O tamanho da audiência ajusta o plano.</p>
              <div className="grid gap-3">
                {REDES_SOCIAIS.map((r) => (
                  <div key={r.chave} className="grid grid-cols-[92px_1fr] sm:grid-cols-[110px_1fr_190px] gap-2 items-center">
                    <span className="text-[12.5px] font-extrabold">{r.rotulo}</span>
                    <input className={classeInput} placeholder={r.exemplo} value={dados.redes?.[r.chave] || ''} onChange={(e) => setAutor('redes', { ...(dados.redes || {}), [r.chave]: e.target.value })} />
                    {r.chave !== 'site' && (
                      <div className="col-start-2 sm:col-start-3">
                        <Select valor={dados.audiencia[r.chave] || 'não tenho'} onChange={(v) => setRede(r.chave, v)} opcoes={FAIXAS_AUDIENCIA} />
                      </div>
                    )}
                  </div>
                ))}
              </div>
            </div>

            <Campo rotulo="Você tem lista de e-mail?">
              <Escolha
                valor={dados.temListaEmail ? 'sim' : 'nao'}
                onChange={(v) => setAutor('temListaEmail', v === 'sim')}
                opcoes={[{ valor: 'sim', rotulo: 'Sim' }, { valor: 'nao', rotulo: 'Não' }]}
              />
            </Campo>
            <Campo rotulo="Objetivo principal com o livro">
              <Escolha valor={dados.objetivo} onChange={(v) => setAutor('objetivo', v)} opcoes={OBJETIVOS} />
            </Campo>
            <Campo rotulo="Horas disponíveis por semana para divulgar">
              <Escolha valor={dados.horasSemana} onChange={(v) => setAutor('horasSemana', v)} opcoes={FAIXAS_HORAS} />
            </Campo>
          </>
        )}

        {etapa === 2 && (
          <>
            <Campo rotulo="Com que frequência quer ser lembrado das ações?">
              <Escolha valor={dados.lembrete} onChange={(v) => setAutor('lembrete', v)} opcoes={LEMBRETES} />
            </Campo>
            <Campo rotulo="Aceita que seu livro apareça na vitrine pública?" ajuda="A vitrine reúne os livros dos alunos e tem uma página própria para cada livro, com botão de compra.">
              <Escolha
                valor={dados.aparecerNaVitrine ? 'sim' : 'nao'}
                onChange={(v) => setAutor('aparecerNaVitrine', v === 'sim')}
                opcoes={[{ valor: 'sim', rotulo: 'Sim, quero aparecer' }, { valor: 'nao', rotulo: 'Não por enquanto' }]}
              />
            </Campo>

            {!editando && (
              <label className="flex items-start gap-3 bg-areia p-4 text-[13.5px] cursor-pointer">
                <input type="checkbox" required className="mt-1 w-4 h-4 accent-[#1a1a1a]" />
                <span>Li e aceito os <Link to="/termos" target="_blank" className="underline underline-offset-4 font-bold">Termos de uso</Link> e a <Link to="/privacidade" target="_blank" className="underline underline-offset-4 font-bold">Política de privacidade</Link>. Sei que posso baixar ou apagar meus dados no Perfil do autor.</span>
              </label>
            )}

            <div className="bg-areia p-6 text-[14px] space-y-1">
              <p className="display text-[18px] mb-2">Resumo</p>
              <p><span className="text-mudo">Livro:</span> {dados.livro.titulo}{dados.livro.subtitulo ? `: ${dados.livro.subtitulo}` : ''}</p>
              <p><span className="text-mudo">Gênero:</span> {dados.livro.genero}</p>
              <p><span className="text-mudo">Autor:</span> {dados.nome}</p>
              <p><span className="text-mudo">Fase:</span> {NOME_FASE[fasePrevista]}</p>
            </div>
          </>
        )}

        <div className="flex items-center justify-between pt-6 border-t-2 border-tinta">
          <button type="button" onClick={voltar} className="btn-linha">
            {etapa === 0 ? 'Cancelar' : 'Voltar'}
          </button>
          <button type="submit" disabled={conferindo} className="btn-primario disabled:opacity-60">
            {conferindo ? 'Conferindo…' : etapa < ETAPAS.length - 1 ? 'Continuar' : editando ? 'Salvar alterações' : soLivro ? 'Salvar e ver o plano deste livro' : 'Salvar e ver meu plano'}
          </button>
        </div>
      </form>
    </div>
  )
}

// Autor salvo -> formato do formulário (datas em yyyy-mm-dd, números em texto)
function estruturar(autor) {
  return {
    ...autor,
    foto: autor.foto || null,
    redes: { instagram: '', youtube: '', linkedin: '', tiktok: '', site: '', ...(autor.redes || {}) },
    livro: {
      ...cadastroVazio().livro,
      ...autor.livro,
      dataPublicacao: autor.livro.dataPublicacao ? autor.livro.dataPublicacao.slice(0, 10) : '',
      dataLancamentoPrevista: autor.livro.dataLancamentoPrevista ? autor.livro.dataLancamentoPrevista.slice(0, 10) : '',
      precoCapa: autor.livro.precoCapa ?? '',
      trechos: (autor.livro.trechos && autor.livro.trechos.length) ? autor.livro.trechos : (autor.livro.trecho ? [{ id: 't1', texto: autor.livro.trecho }] : []),
    },
  }
}

// Formulário -> autor salvo. Mantém id, histórico e data de cadastro ao editar.
function normalizar(dados, inicial) {
  const publicado = dados.livro.status === STATUS_LIVRO.PUBLICADO
  return {
    ...(inicial ?? {}),
    ...dados,
    id: inicial?.id ?? `a_${Date.now()}`,
    cadastradoEm: inicial?.cadastradoEm ?? new Date().toISOString(),
    concluidas: inicial?.concluidas ?? [],
    rejeitadas: inicial?.rejeitadas ?? [],
    checkins: inicial?.checkins ?? [],
    foto: dados.foto || null,
    conquistas: (dados.conquistas || []).filter((c) => c.texto && c.texto.trim()).map((c) => ({ ...c, texto: c.texto.trim() })),
    cadastro: proximoStatusAoSalvar(inicial),
    livro: {
      ...dados.livro,
      dataPublicacao: publicado && dados.livro.dataPublicacao ? new Date(dados.livro.dataPublicacao + 'T12:00:00').toISOString() : null,
      dataLancamentoPrevista: !publicado && dados.livro.dataLancamentoPrevista ? new Date(dados.livro.dataLancamentoPrevista + 'T12:00:00').toISOString() : null,
      precoCapa: dados.livro.precoCapa === '' ? null : Number(dados.livro.precoCapa),
      capaCor: inicial?.livro?.capaCor ?? CORES_CAPA[Math.floor(Math.random() * CORES_CAPA.length)],
      capa: dados.livro.capa || null,
      trechos: (dados.livro.trechos || []).map((t) => ({ ...t, texto: (t.texto || '').trim() })).filter((t) => t.texto),
      trecho: listaTrechos(dados.livro)[0] || '',
    },
  }
}
