import { urlDaAula } from '../marca.js'
import { uso } from '../servicos/uso.js'

/** "Aula 4.2 · Evento de Lançamento": link para a aula de origem no Método The Book Business. */
export default function LinkAula({ aula, className = '', botao = false }) {
  if (!aula) return null
  const m = (aula.nome || '').match(/^(\d+(?:\.\d+)?)\s*[-–·]?\s*(.*)$/)
  const numero = m ? m[1] : null
  const nome = m ? m[2] : aula.nome
  if (botao) {
    return (
      <a
        href={urlDaAula(aula)}
        target="_blank"
        rel="noopener noreferrer"
        onClick={() => uso('aula', { pageId: aula.pageId || null, nome: aula.nome, origem: 'acao' })}
        className={'inline-flex items-start gap-2 text-left bg-verde text-creme px-3.5 py-2 text-[12.5px] font-extrabold normal-case tracking-normal corte-btn hover:bg-tinta transition-colors ' + className}
        title="Abre a aula na área de membros do Método The Book Business"
      >
        <span aria-hidden="true" className="inline-block w-0 h-0 mt-[5px] shrink-0 border-y-[5px] border-y-transparent border-l-[8px] border-l-current" />
        <span>Assistir aula {numero || `M${aula.modulo}`}<span className="font-semibold opacity-85"> · {nome}</span></span>
      </a>
    )
  }
  return (
    <a
      href={urlDaAula(aula)}
      target="_blank"
      rel="noopener noreferrer"
      onClick={() => uso('aula', { pageId: aula.pageId || null, nome: aula.nome, origem: 'acao' })}
      className={'inline normal-case tracking-normal text-[12.5px] font-semibold text-tinta hover:text-verde transition-colors ' + className}
      title="Abre a aula na área de membros do Método The Book Business"
    >
      <span className="text-[10.5px] font-extrabold uppercase tracking-[.1em] text-verde whitespace-nowrap mr-1.5">Aula {numero || `M${aula.modulo}`}</span>
      <span className="underline underline-offset-4 decoration-verde decoration-2">{nome}</span>
      <span aria-hidden="true" className="ml-1">↗</span>
    </a>
  )
}
