import { useState } from 'react'
import { perguntaCheckin, checkinNoPeriodo } from '../regras/checkin.js'
import { formatarData } from '../regras/datas.js'

/** Painel de check-in (verde). Opcional: "Agora não" some pelo resto do período. */
export default function CheckinSemana({ autor, pendente, ultimoCheckin, onRegistrar, onDispensar, onVerHistorico, onAbrirConquista, compacto = false, faixa = false }) {
  const [texto, setTexto] = useState('')
  const noPeriodo = ultimoCheckin && checkinNoPeriodo(autor, ultimoCheckin.data)

  if (!pendente && !noPeriodo) return null

  // Faixa: uma linha verde colada ao hero. Pergunta à esquerda, campo e botão à direita.
  if (faixa) {
    if (!pendente) {
      return (
        <div className="flex flex-col md:flex-row md:items-center gap-3 md:gap-6">
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] opacity-80 shrink-0">Check-in feito em {formatarData(ultimoCheckin.data)}</p>
          <p className="text-[14px] font-semibold leading-snug flex-1">"{ultimoCheckin.texto}"</p>
          <span className="flex items-center gap-4 text-[12px] font-bold shrink-0">
            <button onClick={onVerHistorico} className="underline underline-offset-4 opacity-80 hover:opacity-100">ver histórico</button>
            {onAbrirConquista && <button onClick={onAbrirConquista} className="text-ambar hover:text-white">+ Conquista</button>}
          </span>
        </div>
      )
    }
    return (
      <form onSubmit={(e) => { e.preventDefault(); if (!texto.trim()) return; onRegistrar(texto.trim()); setTexto('') }} className="flex flex-col md:flex-row md:flex-wrap md:items-center gap-3 md:gap-x-5 md:gap-y-2">
        <label className="shrink-0 md:max-w-[30ch]">
          <span className="block text-[11px] font-extrabold uppercase tracking-[.14em] opacity-80">Check-in da semana</span>
          <span className="block text-[14px] font-bold leading-snug mt-0.5">{perguntaCheckin(autor)}</span>
        </label>
        <div className="flex flex-1 min-w-[260px] gap-2">
          <input
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            className="flex-1 min-w-0 bg-white/10 border-2 border-creme/30 text-creme placeholder:text-creme/50 px-3 py-2.5 text-[14px] focus:outline-none focus:border-creme"
            placeholder="Uma frase basta."
          />
          <button type="submit" disabled={!texto.trim()} className="btn bg-ambar text-tinta corte-btn disabled:opacity-40 shrink-0">Registrar</button>
        </div>
        <span className="flex items-center gap-4 text-[12px] font-bold shrink-0 md:ml-auto">
          <button type="button" onClick={onDispensar} className="opacity-80 hover:opacity-100">Agora não</button>
          <button type="button" onClick={onVerHistorico} className="underline underline-offset-4 opacity-80 hover:opacity-100">histórico</button>
          {onAbrirConquista && <button type="button" onClick={onAbrirConquista} className="text-ambar hover:text-white whitespace-nowrap">+ Conquista</button>}
        </span>
      </form>
    )
  }

  // Compacto: vive dentro do hero. Uma linha para escrever, um botão, e os atalhos pequenos.
  if (compacto) {
    if (!pendente) {
      return (
        <div className="grid gap-2">
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Check-in feito em {formatarData(ultimoCheckin.data)}</p>
          <p className="text-[14px] font-semibold text-white/85 leading-snug">"{ultimoCheckin.texto}"</p>
          <div className="flex flex-wrap items-center gap-4 text-[12px] font-bold text-white/70">
            <button onClick={onVerHistorico} className="underline underline-offset-4 hover:text-white">ver histórico</button>
            {onAbrirConquista && <button onClick={onAbrirConquista} className="text-ambar hover:text-white">+ Registrar conquista</button>}
          </div>
        </div>
      )
    }
    return (
      <form onSubmit={(e) => { e.preventDefault(); if (!texto.trim()) return; onRegistrar(texto.trim()); setTexto('') }} className="grid gap-2">
        <label className="block">
          <span className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Check-in da semana</span>
          <span className="block text-[14px] font-bold text-white mt-1">{perguntaCheckin(autor)}</span>
        </label>
        <div className="flex flex-col sm:flex-row gap-2">
          <input
            value={texto}
            onChange={(e) => setTexto(e.target.value)}
            className="flex-1 bg-white/10 border-2 border-white/25 text-white placeholder:text-white/40 px-3 py-2.5 text-[14px] focus:outline-none focus:border-ambar"
            placeholder="Uma frase basta."
          />
          <button type="submit" disabled={!texto.trim()} className="btn bg-ambar text-tinta corte-btn disabled:opacity-40 shrink-0">Registrar</button>
        </div>
        <div className="flex flex-wrap items-center gap-4 text-[12px] font-bold text-white/70">
          <button type="button" onClick={onDispensar} className="hover:text-white">Agora não</button>
          <button type="button" onClick={onVerHistorico} className="underline underline-offset-4 hover:text-white">ver histórico</button>
          {onAbrirConquista && <button type="button" onClick={onAbrirConquista} className="text-ambar hover:text-white">+ Registrar conquista</button>}
        </div>
      </form>
    )
  }

  const botaoConquista = onAbrirConquista && (
    <button type="button" onClick={onAbrirConquista} className="inline-flex items-center gap-2 text-[12.5px] font-extrabold text-ambar hover:text-creme" title="Prêmio, lista, palestra, imprensa: vai para a sua página pública">
      <span className="inline-grid place-items-center w-5 h-5 rounded-full border-2 border-current text-[13px] leading-none">+</span> Registrar conquista
    </button>
  )

  if (!pendente) {
    return (
      <div className="bg-verde text-creme px-7 py-6 h-full grid content-between gap-4">
        <div>
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] opacity-80">Check-in feito em {formatarData(ultimoCheckin.data)}</p>
          <p className="font-bold text-[17px] leading-snug mt-3">"{ultimoCheckin.texto}"</p>
        </div>
        <div className="flex flex-wrap items-center gap-4">
          <button onClick={onVerHistorico} className="text-[12px] font-extrabold uppercase tracking-[.1em] underline underline-offset-4 decoration-2">ver histórico</button>
          {botaoConquista}
        </div>
      </div>
    )
  }

  return (
    <form
      onSubmit={(e) => { e.preventDefault(); if (!texto.trim()) return; onRegistrar(texto.trim()); setTexto('') }}
      className="bg-verde text-creme px-7 py-6 h-full grid content-between gap-4"
    >
      <label className="block">
        <span className="text-[11px] font-extrabold uppercase tracking-[.14em] opacity-80">Check-in da semana</span>
        <span className="block font-bold text-[17px] leading-snug mt-2">{perguntaCheckin(autor)}</span>
        <textarea
          value={texto}
          onChange={(e) => setTexto(e.target.value)}
          className="mt-3 w-full bg-white/10 border-2 border-creme/30 text-creme placeholder:text-creme/50 px-3 py-2 text-[14px] min-h-20 focus:outline-none focus:border-creme"
          placeholder="Uma frase basta."
        />
      </label>
      <div className="grid gap-3">
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <span className="flex items-center gap-4 text-[12px] font-bold">
            <button type="button" onClick={onDispensar} className="opacity-80 hover:opacity-100">Agora não</button>
            <button type="button" onClick={onVerHistorico} className="underline underline-offset-4 opacity-80 hover:opacity-100">ver histórico</button>
          </span>
          <button type="submit" disabled={!texto.trim()} className="btn bg-ambar text-tinta corte-btn">Registrar</button>
        </div>
        {botaoConquista && <div className="pt-3 border-t border-creme/20">{botaoConquista}</div>}
      </div>
    </form>
  )
}
