import { useState } from 'react'
import { NOME_FASE } from '../regras/fase.js'
import { montarPlanoDaSemana, calcularProgressoFase, calcularSemanasConsecutivas, precisaRetomar, ultimaAtividade, ePrimeiraSemana, resumoSemanaPassada, acoesPorSemana, OPCOES_ACOES_SEMANA } from '../regras/plano.js'

import { precisaCheckin } from '../regras/checkin.js'
import { inicioDaSemana, formatarDataLonga, formatarData, formatarTempo } from '../regras/datas.js'
import { estiloFase, CORES } from '../marca.js'
import CartaoAcao from '../componentes/CartaoAcao.jsx'
import AvisoRetomada from '../componentes/AvisoRetomada.jsx'
import CheckinSemana from '../componentes/CheckinSemana.jsx'
import NovasAulas from '../componentes/NovasAulas.jsx'
import FerramentasSemana from '../componentes/FerramentasSemana.jsx'
import NovaSemana from '../componentes/NovaSemana.jsx'
import Capa from '../componentes/Capa.jsx'
import { Estante, LIVROS_POR_FASE } from '../componentes/Prateleira.jsx'
import EstanteDaSemana from '../componentes/EstanteDaSemana.jsx'
import { situacaoNaJornada } from '../regras/jornada.js'
import { slugify } from '../regras/vitrine.js'
import { conquistaSugerida, jaRegistrada, novaConquista } from '../regras/conquistas.js'
import { trechoDaSemana, listaTrechos } from '../regras/trechos.js'
import RegistroConquista from '../componentes/RegistroConquista.jsx'
import { Link } from 'react-router-dom'
import Palavras from '../componentes/Palavras.jsx'
import { personalizarAcao } from '../regras/variaveis.js'
import { explicarTemasEvitados } from '../regras/memoria.js'
import { fraseDoPlano } from '../regras/personalizacao.js'
import { lerUI, gravarUI } from '../regras/persistencia.js'
import { BANNERS } from '../dados/exemplo.js'
import { useEffect } from 'react'

function numeroDaSemana(data) {
  const d = new Date(Date.UTC(data.getFullYear(), data.getMonth(), data.getDate()))
  const dia = d.getUTCDay() || 7
  d.setUTCDate(d.getUTCDate() + 4 - dia)
  const inicioAno = new Date(Date.UTC(d.getUTCFullYear(), 0, 1))
  return Math.ceil(((d - inicioAno) / 86400000 + 1) / 7)
}

export default function PlanoDaSemana({ autor, fase, acoes, onConcluir, onDesfazer, onRejeitar, onDesfazerRejeicao, onReativarTema, onAbrirMaterial, onCheckin, onDispensarCheckin, onVerHistorico, onEditarCadastro, onPerfil, onVerAulas, onRegistrarConquista, onAcoesPorSemana }) {
  const hoje = new Date()
  const [avisoDispensado, setAvisoDispensado] = useState(false)
  const [acaoDestacada, setAcaoDestacada] = useState(null)

  const plano = montarPlanoDaSemana(acoes, fase, autor, hoje)
  const primeiraSemana = ePrimeiraSemana(autor, hoje)
  const semanaPassada = resumoSemanaPassada(autor, hoje)
  const [verTodas, setVerTodas] = useState(false)
  const [aviso, setAviso] = useState(null)
  const [janelaConquista, setJanelaConquista] = useState(null) // null | { sugestao }
  const [outroTrecho, setOutroTrecho] = useState(0)
  const [pausado, setPausado] = useState(false)
  const totalTrechos = listaTrechos(autor.livro).length
  const trechoAtual = trechoDaSemana(autor.livro, hoje, outroTrecho)
  // índice do trecho da semana (deslocamento 0) e do trecho em exibição, para os pontinhos
  const indiceBase = totalTrechos ? listaTrechos(autor.livro).indexOf(trechoDaSemana(autor.livro, hoje, 0)) : 0
  const indiceTrecho = totalTrechos ? (((indiceBase + outroTrecho) % totalTrechos) + totalTrechos) % totalTrechos : 0
  // passa sozinho a cada 7 segundos; para quando a pessoa escolhe um pontinho
  useEffect(() => {
    if (totalTrechos < 2 || pausado) return
    const t = setInterval(() => setOutroTrecho((n) => n + 1), 7000)
    return () => clearInterval(t)
  }, [totalTrechos, pausado])
  useEffect(() => { if (!aviso) return; const t = setTimeout(() => setAviso(null), aviso.conquista ? 12000 : 3500); return () => clearTimeout(t) }, [aviso])
  // Momento "semana nova": só na primeira visita da semana, por autor
  const chaveVisita = `visita.${autor.id}`
  const [novaSemanaVista, setNovaSemanaVista] = useState(() => lerUI()[chaveVisita] === inicioDaSemana(hoje).toISOString())
  const marcarVisita = () => { gravarUI({ [chaveVisita]: inicioDaSemana(hoje).toISOString() }); setNovaSemanaVista(true) }
  const progresso = calcularProgressoFase(acoes, fase, autor.concluidas, autor.rejeitadas)
  const sequencia = calcularSemanasConsecutivas(autor, hoje)
  const mostrarAviso = !avisoDispensado && precisaRetomar(autor, hoje)

  const inicioSemana = inicioDaSemana(hoje)
  const fimSemana = new Date(inicioSemana); fimSemana.setDate(fimSemana.getDate() + 6)
  const conclusaoNaSemana = (acaoId) => autor.concluidas.find((c) => c.acaoId === acaoId && new Date(c.data) >= inicioSemana)?.data
  const temAtividade = autor.concluidas.length || (autor.checkins || []).length
  const ultimaConclusao = temAtividade ? ultimaAtividade(autor) : null
  const checkinPendente = precisaCheckin(autor, hoje)
  const ultimoCheckin = [...(autor.checkins || [])].sort((a, b) => new Date(b.data) - new Date(a.data))[0]
  const rejeitadasNaSemana = autor.rejeitadas.filter((r) => new Date(r.data) >= inicioSemana).map((r) => ({ ...r, acao: acoes.find((a) => a.id === r.acaoId) }))

  const proximaPendente = plano.find((a) => !conclusaoNaSemana(a.id))
  const feitasNaSemana = plano.filter((a) => conclusaoNaSemana(a.id)).length
  const destaque = acaoDestacada || proximaPendente?.id
  const semanaCompleta = plano.length > 0 && feitasNaSemana === plano.length
  const mostrarNovaSemana = !mostrarAviso && !primeiraSemana && !novaSemanaVista

  function concluir(acao) {
    onConcluir(autor.id, acao.id)
    const feitas = feitasNaSemana + 1
    const sugestao = conquistaSugerida(acao, autor)
    setAviso({
      texto: feitas >= plano.length
        ? `Semana completa. ${plano.length} de ${plano.length}. Sua sequência segue viva.`
        : `Boa. ${feitas} de ${plano.length} nesta semana. Sequência em ${Math.max(sequencia, 1)}.`,
      conquista: sugestao && !jaRegistrada(autor, sugestao) ? sugestao : null,
    })
  }
  function registrarSugestao(texto) {
    onRegistrarConquista(autor.id, novaConquista(texto, String(hoje.getFullYear())))
    setAviso({ texto: `Conquista registrada: "${texto}". Já está na sua página pública.` })
  }
  const primeiroNome = autor.nome.split(' ')[0]
  // Cor da fase também no fundo vivo (anéis atrás da página)
  useEffect(() => {
    const est = estiloFase(fase)
    document.documentElement.style.setProperty('--fase', est['--fase'])
    return () => document.documentElement.style.removeProperty('--fase')
  }, [fase])

  function retomar() {
    setAvisoDispensado(true)
    if (proximaPendente) {
      setAcaoDestacada(proximaPendente.id)
      document.getElementById(`acao-${proximaPendente.id}`)?.scrollIntoView({ behavior: 'smooth', block: 'center' })
    }
  }

  return (
    <div style={estiloFase(fase)}>
      {janelaConquista && (
        <RegistroConquista autor={autor} sugestao={janelaConquista.sugestao} onSalvar={(c) => onRegistrarConquista(autor.id, c)} onFechar={() => setJanelaConquista(null)} />
      )}
      {mostrarAviso && <AvisoRetomada ultimaConclusao={ultimaConclusao} proximaAcao={proximaPendente} onRetomar={retomar} />}
      {mostrarNovaSemana && (
        <NovaSemana inicioSemana={inicioSemana} semanaPassada={semanaPassada} sequencia={sequencia} primeiroNome={primeiroNome} onFechar={marcarVisita} />
      )}

      {/* Cabeçalho: painel preto cortado + painel da fase com círculos */}
      <header className="grid grid-cols-1 md:grid-cols-[1.25fr_1fr] min-h-[300px] entra">
        <div className="bg-tinta text-white px-6 py-7 sm:px-8 sm:py-9 md:corte-d relative z-10">
          <p className="text-[12px] font-bold uppercase tracking-[.12em] text-ambar">
            Semana de {formatarDataLonga(inicioSemana)} a {formatarDataLonga(fimSemana)}
          </p>
          <h1 className="display text-[34px] sm:text-[52px] mt-3 mb-4 text-balance">
            <Palavras texto={primeiraSemana
              ? `Bem-vindo, ${primeiroNome}. Sua primeira semana começa com uma ação só.`
              : `${primeiroNome}, ${plano.length} ${plano.length === 1 ? 'ação' : 'ações'} para ${autor.livro.titulo} chegar mais longe.`} />
          </h1>
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">{situacaoNaJornada(autor, fase, hoje).marcoTitulo}</p>
          <p className="text-[14px] text-white/75 max-w-[48ch] mt-1">{situacaoNaJornada(autor, fase, hoje).marco}</p>

        </div>
        <div className="bg-fase relative md:-ml-[44px] md:pl-[44px] min-h-[230px] md:min-h-[280px] overflow-hidden revela order-first md:order-none">
          <PainelLivro autor={autor} fase={fase} />
          <span className="absolute right-4 bottom-3 inline-flex items-end gap-3 text-[10.5px] font-extrabold uppercase tracking-[.14em] text-fase-tinta">
            <EstanteDaSemana total={plano.length} feitas={feitasNaSemana} altura={26} sobreFase />
            <span>{plano.length - feitasNaSemana} {plano.length - feitasNaSemana === 1 ? 'ação pendente' : 'ações pendentes'}</span>
          </span>
        </div>
      </header>
      {(checkinPendente || ultimoCheckin) && (
        <section className="bg-verde text-creme px-6 sm:px-8 py-4 entra atraso-1">
          <CheckinSemana
            faixa
            autor={autor}
            pendente={checkinPendente}
            ultimoCheckin={ultimoCheckin}
            onRegistrar={(texto) => onCheckin(autor.id, texto)}
            onDispensar={() => onDispensarCheckin(autor.id)}
            onVerHistorico={onVerHistorico}
            onAbrirConquista={() => setJanelaConquista({ sugestao: '' })}
          />
        </section>
      )}

      {/* Citação do livro (largura total) */}
      <section className="mt-4 entra atraso-1">
        <div className="bg-creme text-tinta px-8 pt-7 pb-6 corte-d">
          <span className="display text-[64px] leading-[.6] block">“</span>
          {trechoAtual ? (
            <>
              <p key={trechoAtual} className="font-extrabold text-[22px] sm:text-[26px] leading-tight tracking-tight mt-3 mb-4 max-w-[60ch] entra">{trechoAtual}</p>
              <div className="flex flex-wrap items-center justify-between gap-3">
                <small className="block text-[11.5px] font-bold uppercase tracking-[.08em] text-apoio">Trecho de {autor.livro.titulo} · esta semana nos seus textos</small>
                {totalTrechos > 1 && (
                  <span className="inline-flex items-center gap-2" role="tablist" aria-label="Trechos do livro">
                    {Array.from({ length: totalTrechos }, (_, i) => {
                      const ativo = i === indiceTrecho
                      return (
                        <button
                          key={i}
                          role="tab"
                          aria-selected={ativo}
                          aria-label={`Trecho ${i + 1}`}
                          onClick={() => { setOutroTrecho(i - indiceBase); setPausado(true) }}
                          className={'rounded-full transition-all duration-500 ' + (ativo ? 'w-6 h-2.5 bg-tinta' : 'w-2.5 h-2.5 bg-tinta/25 hover:bg-tinta/50')}
                        />
                      )
                    })}
                  </span>
                )}
              </div>
            </>
          ) : (
            <>
              <p className="font-extrabold text-[22px] leading-tight tracking-tight mt-4 mb-4 max-w-[26ch]">Um trecho do seu livro apareceria aqui, pronto para virar post.</p>
              <small className="block text-[11.5px] font-bold uppercase tracking-[.08em] text-apoio">Cadastre um trecho favorito em Editar cadastro</small>
            </>
          )}
        </div>
      </section>


      {/* Lista */}
      <section className="mt-6 entra atraso-2">
        <div className="flex flex-wrap items-baseline justify-between gap-2 pt-8 pb-6">
          <h2 className="display text-[26px] sm:text-[30px] text-balance">
            {primeiraSemana ? `Comece por aqui, ${primeiroNome}.`
              : semanaCompleta ? `Semana fechada, ${primeiroNome}.`
              : feitasNaSemana === 0 ? `${primeiroNome}, vamos começar.`
              : `Boa, ${primeiroNome}. ${plano.length - feitasNaSemana === 1 ? 'Falta uma.' : `Faltam ${plano.length - feitasNaSemana}.`}`}
          </h2>
          <span className="inline-flex items-end gap-3 text-[13px] font-semibold text-mudo">
            <EstanteDaSemana total={plano.length} feitas={feitasNaSemana} altura={30} />
            <span>{primeiraSemana ? 'uma ação hoje já conta' : feitasNaSemana === 0 ? 'nenhuma feita ainda' : `${feitasNaSemana} de ${plano.length} feitas`}</span>
          </span>
        </div>
        {/* o autor escolhe o ritmo, aqui mesmo, sem ir ao cadastro */}
        {onAcoesPorSemana && (
          <div className="flex flex-wrap items-center gap-3 -mt-2 mb-6 text-[12.5px] text-apoio" role="group" aria-label="Ações por semana">
            <span className="font-semibold">Ações por semana</span>
            <span className="inline-flex border-2 border-tinta">
              {OPCOES_ACOES_SEMANA.map((n) => {
                const ativo = (acoesPorSemana(autor) ?? plano.length) === n
                return <button key={n} onClick={() => onAcoesPorSemana(autor.id, n)} aria-pressed={ativo} className={'w-9 h-8 text-[13px] font-extrabold transition-colors ' + (ativo ? 'bg-tinta text-white' : 'bg-white text-tinta hover:bg-areia')}>{n}</button>
              })}
            </span>
          </div>
        )}
        {aviso && (
          <div role="status" className="mb-5 bg-ambar text-tinta px-5 py-3 text-[14px] corte-d surge-toast flex flex-wrap items-center gap-x-4 gap-y-2">
            <span className="font-extrabold">{aviso.texto}</span>
            {aviso.conquista && (
              <span className="flex flex-wrap items-center gap-2 text-[13px]">
                <span>Isso vira conquista na sua página?</span>
                <button onClick={() => registrarSugestao(aviso.conquista)} className="bg-tinta text-white px-3 py-1.5 font-extrabold text-[12px] corte-btn">Sim, registrar "{aviso.conquista}"</button>
                <button onClick={() => setAviso({ texto: aviso.texto })} className="underline underline-offset-4 font-semibold">agora não</button>
              </span>
            )}
          </div>
        )}
        {semanaCompleta && !aviso && (
          <div className="mb-5 bg-verde text-creme px-6 py-5 corte-d">
            <p className="display text-[24px]">Semana completa.</p>
            <p className="text-[13.5px] mt-1 opacity-90">Registre o check-in e volte na segunda.</p>
          </div>
        )}
        {explicarTemasEvitados(autor, acoes).map((t) => (
          <p key={t.tema} className="text-[12.5px] text-apoio bg-areia px-4 py-2.5 -mt-3 mb-5">
            Ações de <b className="text-tinta">{t.nome}</b> saíram do plano: você marcou {t.rejeitadas} como "não se aplica".
            <button onClick={() => onReativarTema(autor.id, t.tema)} className="ml-2 underline underline-offset-4 font-semibold hover:text-tinta">voltar a incluir</button>
          </p>
        ))}
        <ul className="grid gap-5">
          {(primeiraSemana && !verTodas ? plano.slice(0, 1) : plano).map((acao, i) => (
            <CartaoAcao
              key={acao.id}
              acao={acao}
              autor={autor}
              acoes={acoes}
              numero={i + 1}
              concluidaEm={conclusaoNaSemana(acao.id)}
              destacada={destaque === acao.id}
              onConcluir={() => concluir(acao)}
              onDesfazer={() => onDesfazer(autor.id, acao.id)}
              onRejeitar={() => onRejeitar(autor.id, acao.id)}
              onAbrirMaterial={onAbrirMaterial}
            />
          ))}
        </ul>
        {primeiraSemana && !verTodas && plano.length > 1 && (
          <div className="mt-6 bg-areia px-6 py-5">
            <p className="text-[11px] font-extrabold uppercase tracking-[.12em] text-mudo">Depois desta, vêm</p>
            <ol className="mt-2 grid gap-1.5">
              {plano.slice(1).map((a, i) => (
                <li key={a.id} className="flex items-baseline justify-between gap-4 text-[13.5px]">
                  <span><span className="text-mudo tabular-nums mr-2">{i + 2}</span>{personalizarAcao(a, autor).titulo}</span>
                  <span className="text-mudo text-[12px] font-semibold shrink-0">{formatarTempo(a.tempoMinutos)}</span>
                </li>
              ))}
            </ol>
            <button onClick={() => setVerTodas(true)} className="btn-linha mt-3 underline underline-offset-4">ver o plano completo</button>
          </div>
        )}
        {rejeitadasNaSemana.length > 0 && (
          <ul className="mt-6 space-y-1">
            {rejeitadasNaSemana.map((r) => (
              <li key={r.acaoId} className="text-[13px] text-mudo px-2">
                Você marcou <span className="text-tinta font-semibold">"{r.acao ? personalizarAcao(r.acao, autor).titulo : ''}"</span> como não aplicável em {formatarData(r.data)}.
                <button onClick={() => onDesfazerRejeicao(autor.id, r.acaoId)} className="ml-2 underline underline-offset-4 hover:text-tinta font-semibold">desfazer</button>
              </li>
            ))}
          </ul>
        )}
      </section>

      <FerramentasSemana
        autor={autor}
        fase={fase}
        feitasNaSemana={feitasNaSemana}
        totalNaSemana={plano.length}
        sequencia={sequencia}
        tituloProxima={proximaPendente ? personalizarAcao(proximaPendente, autor).titulo : undefined}
        numeroSemana={numeroDaSemana(hoje)}
        urlComunidade={BANNERS.find((b) => b.id === 'comunidade')?.url}
      />
      <NovasAulas onVerTodas={onVerAulas} />
    </div>
  )
}

/** Grade de círculos do cabeçalho: círculo preto com o total de ações, anel, e círculos nas cores da marca. */
/** Painel da fase: a capa do livro do autor no centro, com o número de ações e o anel em volta. */
function PainelLivro({ autor, fase }) {
  const livros = LIVROS_POR_FASE[fase] || LIVROS_POR_FASE.construcao
  return (
    <div className="absolute inset-0 md:pl-[44px] px-6 pt-6 pb-10 flex items-end gap-3">
      {/* lombadas da fase */}
      <div className="flex-1 min-w-0 h-full">
        <Estante livros={livros} altura="100%" gap={6} fonte={11} />
      </div>
      {/* a capa do autor, em pé, encostada na estante */}
      <div className="shrink-0 relative -rotate-3 translate-y-2 flutua" style={{ animationDuration: '7s' }}>
        <div className="p-1.5 bg-creme shadow-[10px_10px_0_0_rgba(20,17,15,.28)]">
          <Capa livro={{ ...autor.livro, nomeAutor: autor.nome }} className="w-[104px] md:w-[124px]" />
        </div>
      </div>
    </div>
  )
}
