import { Link } from 'react-router-dom'
import Capa from '../componentes/Capa.jsx'
import { NOME_FASE, classificarFase as classificarFaseDoLivro } from '../regras/fase.js'
import { slugify, leitoresDoLivro } from '../regras/vitrine.js'
import { temVaga } from '../regras/livros.js'
import AmazonDoLivro from '../componentes/AmazonDoLivro.jsx'
import { URL_SUPORTE } from '../marca.js'
import { NOME_STATUS_CADASTRO, statusCadastro } from '../regras/aprovacao.js'
import { listaTrechos } from '../regras/trechos.js'
import TrocarCodigo from '../componentes/TrocarCodigo.jsx'
import Compartilhar from '../componentes/Compartilhar.jsx'
import { useState } from 'react'

/** Perfil do autor: o que é dele e o que ele configura. Cadastro, leitores, conquistas, página pública, sugestões. */
export default function PerfilAutor({ autor, fase, leitores, sugestoes, onEditar, onLeitores, onSugestoes, onVoltar, onTrocarCodigo, onApagarConta, leitoresDoAutor = [], onNovoLivro, onFocarLivro, urlCheckoutLivro = '' }) {
  const [apagando, setApagando] = useState(false)
  const [trocando, setTrocando] = useState(false)
  const slug = slugify(autor.livro.titulo)
  const nLeitores = leitoresDoLivro(leitores, slug).length
  const nConquistas = (autor.conquistas || []).length
  const nTrechos = listaTrechos(autor.livro).length
  const minhasSugestoes = sugestoes.filter((s) => s.autorId === autor.id).length
  const iniciais = autor.nome.split(' ').map((n) => n[0]).slice(0, 2).join('')
  const urlPagina = `${window.location.origin}${import.meta.env.BASE_URL.replace(/\/$/, '')}/livro/${slug}`

  const cartoes = [
    { titulo: 'Cadastro', desc: `Livro, bio, foto, ${nTrechos} ${nTrechos === 1 ? 'trecho' : 'trechos'}, ${nConquistas} ${nConquistas === 1 ? 'conquista' : 'conquistas'}. Status: ${NOME_STATUS_CADASTRO[statusCadastro(autor)]}.`, cta: 'Editar cadastro', onClick: onEditar },
    { titulo: 'Meus leitores', desc: nLeitores === 0 ? 'Quem deixar e-mail na sua página aparece aqui.' : `${nLeitores} ${nLeitores === 1 ? 'e-mail captado' : 'e-mails captados'} na página do livro.`, cta: 'Ver e baixar', onClick: onLeitores },
    { titulo: 'Página pública', desc: autor.aparecerNaVitrine !== false ? 'A sua página na vitrine, com capa, trechos e conquistas.' : 'Desligada no cadastro.', cta: 'Abrir ↗', href: autor.aparecerNaVitrine !== false ? `/livro/${slug}` : null },
    ...(onTrocarCodigo ? [{ titulo: 'Código de acesso', desc: 'Seis números, fixos, que você usa com o seu e-mail para entrar em qualquer aparelho. Troque quando quiser.', cta: 'Trocar código', onClick: () => setTrocando(true) }] : []),
    { titulo: 'Sugestões para o LOMBADA', desc: minhasSugestoes ? `Você já enviou ${minhasSugestoes}. O time lê tudo.` : 'Faltou uma ação? Um texto não soou como você? Conta aqui.', cta: 'Sugerir', onClick: onSugestoes },
    { titulo: 'Meus dados', desc: 'Baixe tudo o que o LOMBADA guarda sobre você e o seu livro, ou apague a conta. Veja os Termos de uso e a Política de privacidade.', cta: 'Baixar meus dados', onClick: baixarDados, cta2: 'Apagar minha conta', onClick2: () => setApagando(true), links: true },
  ]

  function baixarDados() {
    const pacote = { exportadoEm: new Date().toISOString(), autor, leitores: leitoresDoAutor }
    const blob = new Blob([JSON.stringify(pacote, null, 2)], { type: 'application/json' })
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `lombada-${slug || 'meus-dados'}.json`; a.click(); URL.revokeObjectURL(a.href)
  }

  return (
    <div>
      {trocando && <TrocarCodigo onTrocar={onTrocarCodigo} onFechar={() => setTrocando(false)} />}
      {apagando && <ApagarConta onConfirmar={onApagarConta} onFechar={() => setApagando(false)} />}
      <button onClick={onVoltar} className="btn-linha">← Voltar ao plano da semana</button>
      <header className="mt-5 grid grid-cols-1 md:grid-cols-[1fr_auto] entra">
        <div className="bg-tinta text-white px-8 py-8 relative z-10 md:corte-d grid grid-cols-[auto_1fr] gap-6 items-center">
          {autor.foto ? (
            <img src={autor.foto} alt={autor.nome} className="w-20 h-20 rounded-full object-cover border-[3px] border-creme" />
          ) : (
            <div className="w-20 h-20 rounded-full bg-creme text-tinta grid place-items-center display text-[26px]">{iniciais}</div>
          )}
          <div>
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Perfil do autor</p>
            <h1 className="display text-[30px] sm:text-[38px] mt-1 leading-none">{autor.nome}</h1>
            <p className="text-[13.5px] text-white/75 mt-2">{autor.profissao}{autor.cidade ? ` · ${autor.cidade}` : ''}</p>
          </div>
        </div>
        <div className="bg-fase text-fase-tinta px-8 py-7 md:-ml-[44px] md:pl-[72px] grid grid-cols-[64px_1fr] gap-4 items-center">
          <Capa livro={{ ...autor.livro, nomeAutor: autor.nome }} className="w-16" />
          <div>
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em] opacity-80">Seu livro</p>
            <p className="font-extrabold text-[16px] leading-tight mt-1">{autor.livro.titulo}</p>
            <p className="text-[12px] mt-1 opacity-85">{autor.livro.genero} · fase {NOME_FASE[fase]}</p>
          </div>
        </div>
      </header>

      {/* vários livros: um em foco; livro adicional é liberado pela equipe (pago pela Hotmart) */}
      <section className="mt-8 bg-areia px-6 py-6 corte-d">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <p className="display text-[22px] leading-none">Meus livros</p>
            <p className="text-[13px] text-apoio mt-2">O plano da semana, o card e o e-mail de segunda seguem o livro em foco. Cada livro tem página, leitores e histórico próprios.</p>
          </div>
          {temVaga(autor)
            ? <button onClick={onNovoLivro} className="btn-preto">Cadastrar outro livro</button>
            : <a href={urlCheckoutLivro || URL_SUPORTE} target="_blank" rel="noopener noreferrer" className="btn-primario">Quero mais um livro</a>}
        </div>
        <ul className="mt-4 grid gap-2">
          {(autor.livros || []).map((l) => {
            const foco = l.id === autor.livroFoco
            return (
              <li key={l.id} className={'bg-white border-2 ' + (foco ? 'border-tinta' : 'border-fio')}>
                <div className="flex flex-wrap items-center gap-3 px-4 py-3">
                  <span className={'text-[10.5px] font-extrabold uppercase tracking-[.12em] px-2 py-0.5 ' + (foco ? 'bg-tinta text-white' : 'bg-areia text-mudo')}>{foco ? 'Em foco' : NOME_FASE[classificarFaseDoLivro(l)]}</span>
                  <span className="font-bold text-[14px] flex-1 min-w-[160px]">{l.titulo || 'Livro sem título'}</span>
                  <span className="text-[12px] text-mudo">{(l.concluidas || []).length} {(l.concluidas || []).length === 1 ? 'ação feita' : 'ações feitas'}</span>
                  {!foco && <button onClick={() => onFocarLivro(l.id)} className="text-[12.5px] font-bold underline underline-offset-4 hover:text-verde">Focar neste livro</button>}
                </div>
                {/* ranking, nota e avaliações na Amazon (só aparece se o livro tem link) */}
                <div className="border-t-2 border-fio"><AmazonDoLivro livro={l} /></div>
              </li>
            )
          })}
        </ul>
        {!temVaga(autor) && <p className="text-[12px] text-mudo mt-3">Livro adicional é um produto à parte do Método The Book Business. {urlCheckoutLivro ? 'Depois da compra, a equipe libera a vaga e o botão "Cadastrar outro livro" aparece aqui.' : 'Fale com a Dezza para liberar mais um.'}</p>}
      </section>

      <ul className="mt-6 grid grid-cols-1 sm:grid-cols-2 gap-4">
        {cartoes.map((c) => (
          <li key={c.titulo} className="bg-areia px-6 py-6 grid content-between gap-4">
            <div>
              <p className="display text-[22px] leading-none">{c.titulo}</p>
              <p className="text-[13px] text-apoio mt-2">{c.desc}</p>
            </div>
            {c.href ? (
              <span className="flex flex-wrap items-center gap-2">
                <Link to={c.href} target="_blank" className="btn-preto">{c.cta}</Link>
                <Compartilhar url={urlPagina} titulo={`${autor.livro.titulo}, de ${autor.nome}`} texto={`Conheça ${autor.livro.titulo}, meu livro.`} rotulo="Compartilhar" className="btn bg-white border-2 border-tinta text-tinta corte-btn" />
              </span>
            ) : c.href === null ? (
              <span className="text-[12px] text-mudo">Ative "aparecer na vitrine" no cadastro.</span>
            ) : (
              <span className="flex flex-wrap items-center gap-3">
                <button onClick={c.onClick} className="btn-preto">{c.cta}</button>
                {c.cta2 && <button onClick={c.onClick2} className="text-[12.5px] font-bold text-mudo hover:text-alerta underline underline-offset-4">{c.cta2}</button>}
                {c.links && <span className="text-[12px] text-mudo"><Link to="/termos" className="underline underline-offset-4">Termos</Link> · <Link to="/privacidade" className="underline underline-offset-4">Privacidade</Link></span>}
              </span>
            )}
          </li>
        ))}
      </ul>
    </div>
  )
}


/** Confirmação em duas etapas para apagar a conta: o autor digita APAGAR. Irreversível. */
function ApagarConta({ onConfirmar, onFechar }) {
  const [texto, setTexto] = useState('')
  const [ocupado, setOcupado] = useState(false)
  const [erro, setErro] = useState('')
  async function confirmar() {
    setOcupado(true); setErro('')
    try { await onConfirmar() } catch (e) { setErro(e.message || 'Não consegui apagar. Tente de novo.'); setOcupado(false) }
  }
  return (
    <div className="fixed inset-0 z-50 bg-tinta/70 grid place-items-center px-4" role="dialog" aria-modal="true" aria-labelledby="apagar-titulo">
      <div className="bg-white max-w-[440px] w-full p-7 border-2 border-tinta">
        <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-alerta">Irreversível</p>
        <h2 id="apagar-titulo" className="display text-[24px] mt-1">Apagar a sua conta do LOMBADA</h2>
        <p className="text-[14px] text-apoio mt-3">Cadastro, histórico de ações e check-ins, conquistas, lista de leitores e a página pública do livro são apagados agora, sem volta. O seu acesso ao Método The Book Business na Hotmart não muda.</p>
        <label className="block mt-5"><span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1.5">Digite APAGAR para confirmar</span><input value={texto} onChange={(e) => setTexto(e.target.value)} className="campo" autoFocus /></label>
        {erro && <p className="text-[13px] font-bold text-alerta mt-2">{erro}</p>}
        <div className="flex flex-wrap gap-3 mt-5">
          <button onClick={confirmar} disabled={texto.trim().toUpperCase() !== 'APAGAR' || ocupado} className="btn bg-alerta text-white corte-btn disabled:opacity-40">{ocupado ? 'Apagando…' : 'Apagar minha conta'}</button>
          <button onClick={onFechar} className="btn-linha">Cancelar</button>
        </div>
      </div>
    </div>
  )
}
