import { useState } from 'react'

/** O autor troca o próprio código de acesso: informa o atual e escolhe um novo de 6 números. */
export default function TrocarCodigo({ onTrocar, onFechar }) {
  const [atual, setAtual] = useState('')
  const [novo, setNovo] = useState('')
  const [confirma, setConfirma] = useState('')
  const [erro, setErro] = useState('')
  const [ok, setOk] = useState(false)
  const [ocupado, setOcupado] = useState(false)
  const so6 = (v) => v.replace(/\D/g, '').slice(0, 6)

  async function enviar(e) {
    e.preventDefault(); setErro('')
    if (novo !== confirma) { setErro('Os dois códigos novos não são iguais.'); return }
    setOcupado(true)
    try { await onTrocar(atual, novo); setOk(true) } catch (err) { setErro(err.message) } finally { setOcupado(false) }
  }

  const campo = 'campo text-[22px] tracking-[.3em] display'
  return (
    <div className="fixed inset-0 z-40 grid place-items-center px-4" style={{ background: 'rgba(20,17,15,.72)' }} onClick={onFechar}>
      <form onSubmit={enviar} onClick={(e) => e.stopPropagation()} className="w-full max-w-md bg-white text-tinta border-[3px] border-tinta p-6 sm:p-8 grid gap-4 surge-toast">
        <div>
          <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-mudo">Código de acesso</p>
          <h2 className="display text-[28px] mt-1 leading-none">{ok ? 'Código trocado.' : 'Escolha um código novo'}</h2>
          <p className="text-[13px] text-apoio mt-2">{ok ? 'Use o novo na próxima vez que entrar. Guarde em um lugar seguro.' : 'Seis números. É com ele e o seu e-mail que você entra em qualquer aparelho.'}</p>
        </div>
        {!ok && (
          <>
            <label className="block"><span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1">Código atual</span><input inputMode="numeric" value={atual} onChange={(e) => setAtual(so6(e.target.value))} className={campo} autoFocus /></label>
            <label className="block"><span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1">Código novo</span><input inputMode="numeric" value={novo} onChange={(e) => setNovo(so6(e.target.value))} className={campo} /></label>
            <label className="block"><span className="block text-[12px] font-extrabold uppercase tracking-[.08em] mb-1">Repita o novo</span><input inputMode="numeric" value={confirma} onChange={(e) => setConfirma(so6(e.target.value))} className={campo} /></label>
            {erro && <p className="text-[13px] font-bold text-alerta">{erro}</p>}
          </>
        )}
        <div className="flex flex-wrap items-center gap-3 pt-1">
          {ok ? (
            <button type="button" onClick={onFechar} className="btn-preto">Fechar</button>
          ) : (
            <>
              <button type="submit" disabled={ocupado || atual.length < 6 || novo.length < 6 || confirma.length < 6} className="btn-primario disabled:opacity-40">{ocupado ? 'Trocando…' : 'Trocar código'}</button>
              <button type="button" onClick={onFechar} className="btn-linha">cancelar</button>
            </>
          )}
        </div>
      </form>
    </div>
  )
}
