// Regras do catálogo de aulas (área de membros do Método The Book Business).

import { MODULOS as MODULOS_PADRAO, SINCRONIZACAO as SINCRONIZACAO_PADRAO } from '../dados/aulas_mtbb.js'

// O catálogo começa com o arquivo e é substituído pelo da nuvem (lombada_catalogo.aulas,
// sincronizado todo dia pela Edge Function lombada-sync-aulas) quando ele chega.
let catalogo = { MODULOS: MODULOS_PADRAO, SINCRONIZACAO: SINCRONIZACAO_PADRAO }
export function definirCatalogoAulas(dados) {
  if (dados && Array.isArray(dados.MODULOS) && dados.MODULOS.length && dados.SINCRONIZACAO) catalogo = { MODULOS: dados.MODULOS, SINCRONIZACAO: { ...SINCRONIZACAO_PADRAO, ...dados.SINCRONIZACAO } }
}
export const modulos = () => catalogo.MODULOS
export const sincronizacao = () => catalogo.SINCRONIZACAO

export const urlAula = (pageId) =>
  `https://hotmart.com/pt-br/club/${sincronizacao().slug}/products/${sincronizacao().produtoId}/content/${pageId}`

/** Lista plana: { id, nome, ordem, modulo, moduloId, tipo, url } */
export function todasAsAulas() {
  return modulos().flatMap((m) => m.aulas.map(([id, nome, ordem]) => ({ id, nome, ordem, modulo: m.nome, moduloId: m.id, tipo: m.tipo, url: urlAula(id) })))
}

/**
 * "Novas aulas": as que entraram na última sincronização. Se a sincronização
 * não marcou nenhuma (primeira leitura), cai nas últimas adicionadas aos
 * conteúdos extras (Lives, Workshops, Encontros), que é onde o Método The Book Business cresce.
 */
export function aulasNovas(limite = 4) {
  const todas = todasAsAulas()
  const marcadas = (sincronizacao().novas || []).map((id) => todas.find((a) => a.id === id)).filter(Boolean)
  if (marcadas.length) return marcadas.slice(0, limite)
  return todas.filter((a) => a.tipo === 'extra').sort((a, b) => b.ordem - a.ordem || b.modulo.localeCompare(a.modulo)).slice(0, limite)
}

export function totalDeAulas() {
  return todasAsAulas().length
}
