import { Component } from 'react'
import Wordmark from './Wordmark.jsx'
import { uso, despachar } from '../servicos/uso.js'

/**
 * Última linha de defesa: se algo quebrar na tela, o autor vê uma página amigável em vez de branco,
 * e o erro vira um evento de uso (`erro`) para a equipe ver no Admin.
 */
export default class ErroGlobal extends Component {
  state = { erro: null }
  static getDerivedStateFromError(erro) { return { erro } }
  componentDidCatch(erro, info) {
    try {
      uso('erro', { mensagem: String(erro?.message || erro).slice(0, 300), onde: (info?.componentStack || '').split('\n').slice(1, 4).join(' > ').slice(0, 300), url: window.location.pathname })
      despachar()
    } catch { /* nada */ }
  }
  render() {
    if (!this.state.erro) return this.props.children
    return (
      <div className="min-h-screen grid place-items-center px-6">
        <div className="max-w-[460px] w-full">
          <Wordmark tamanho={28} />
          <div className="bg-tinta text-white px-7 py-8 mt-6 corte-d">
            <p className="text-[11px] font-extrabold uppercase tracking-[.14em] text-ambar">Algo deu errado</p>
            <h1 className="display text-[28px] mt-2">Essa tela travou, mas o seu trabalho está salvo.</h1>
            <p className="text-[14px] text-white/75 mt-3">Ações, check-ins e cadastro ficam guardados na nuvem a cada mudança. Recarregue e continue de onde parou. Se acontecer de novo, conte para a equipe pelo Perfil → Sugestões.</p>
            <div className="flex flex-wrap gap-3 mt-6">
              <button onClick={() => window.location.reload()} className="btn-primario">Recarregar</button>
              <a href={import.meta.env.BASE_URL} className="btn bg-white/10 text-white corte-btn">Voltar ao início</a>
            </div>
          </div>
        </div>
      </div>
    )
  }
}

/** Erros fora do React (promessas, scripts) também viram evento. Chamar uma vez na inicialização. */
export function registrarErrosGlobais() {
  if (typeof window === 'undefined' || registrarErrosGlobais._ok) return
  registrarErrosGlobais._ok = true
  window.addEventListener('error', (e) => uso('erro', { mensagem: String(e.message || '').slice(0, 300), onde: `${e.filename || ''}:${e.lineno || ''}`.slice(0, 120), url: window.location.pathname }))
  window.addEventListener('unhandledrejection', (e) => uso('erro', { mensagem: String(e.reason?.message || e.reason || '').slice(0, 300), onde: 'promise', url: window.location.pathname }))
}
